// L1/bridge/interface language and L2/target language helpers
// (getInterfaceLabel/getSupportText/getTargetContent/getLanguagePairLabel) -
// see src/js/language-pair.js for the full definitions. bridgeLanguage IS
// the interface language in this architecture (one field, not two) - it is
// the language the platform's navigation, instructions, explanations, help
// and system messages appear in, not merely "a language the student already
// knows". Persisted server-side as profiles.bridge_language, paired with
// preferred_language/learningPathState.language (the target language being
// learned).
//
// Both live on learningPathState (learningPathState.bridgeLanguage /
// .language) - there used to be separate currentBridgeLanguage/
// currentTargetLanguage globals that had to be kept in sync by hand on every
// write; that duplication caused a real bug (the home cards/#languages tabs
// once updated only the target mirror, never learningPathState.language, so
// the two disagreed - see normalizeLanguageKey's comment below) and has been
// removed. learningPathState is the single source of truth for both.
const LanguagePair = window.AndergoLanguagePair;

// Lightweight, generated exercise feedback: no media files to download and
// no autoplay. It runs only from a learner's answer/check action. The short
// tones deliberately stay below speech volume so they reinforce feedback
// without competing with TTS or the Tutor.
let exerciseFeedbackAudioContext = null;

window.prepareExerciseFeedbackAudio = function prepareExerciseFeedbackAudio() {
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    if (!exerciseFeedbackAudioContext || exerciseFeedbackAudioContext.state === 'closed') {
      exerciseFeedbackAudioContext = new AudioContextClass();
    }
    if (exerciseFeedbackAudioContext.state === 'suspended') {
      exerciseFeedbackAudioContext.resume().catch(() => {});
    }
    return exerciseFeedbackAudioContext;
  } catch {
    return null;
  }
};

// Prime Web Audio synchronously during the learner's click. Answer checks
// finish after a network await; creating AudioContext only then is blocked
// by Chrome's autoplay policy and produces no audible feedback.
document.addEventListener(
  'pointerdown',
  (event) => {
    if (
      event.target.closest(
        '.mcq-option, .reading-comp-option, .grammar-test-option, .vocab-practice-option, [data-writing-answer], .writing-practice-check'
      )
    ) {
      window.prepareExerciseFeedbackAudio();
    }
  },
  { capture: true }
);

window.playExerciseFeedbackSound = function playExerciseFeedbackSound(correct) {
  try {
    const context = window.prepareExerciseFeedbackAudio();
    if (!context) return;
    const now = context.currentTime;
    const celebration = correct === 'celebration';
    const notes = celebration ? [523, 659, 784, 1046] : correct ? [660, 880] : [330, 220];
    notes.forEach((frequency, index) => {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      const isIncorrect = correct === false;
      const start = now + 0.015 + index * (celebration ? 0.1 : isIncorrect ? 0.13 : 0.09);
      const duration = celebration ? 0.17 : isIncorrect ? 0.2 : 0.11;
      oscillator.type = celebration || correct ? 'sine' : 'square';
      oscillator.frequency.setValueAtTime(frequency, start);
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(
        celebration ? 0.09 : isIncorrect ? 0.13 : 0.07,
        start + 0.012
      );
      gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
      oscillator.connect(gain).connect(context.destination);
      oscillator.start(start);
      oscillator.stop(start + duration + 0.01);
    });
  } catch {
    // Audio is an enhancement only; an unavailable/blocked Web Audio API
    // must never affect scoring or feedback.
  }
};

window.getExerciseReinforcement = function getExerciseReinforcement(correctCount, total) {
  const ratio = total ? correctCount / total : 0;
  if (ratio === 1) return 'Excelente, eres genial!';
  if (ratio >= 0.8) return 'Muy bueno, vas muy bien!';
  if (ratio >= 0.6) return 'Buen intento, puedes seguir mejorando.';
  if (ratio >= 0.4) return 'Aceptable, lo intentamos de nuevo?';
  if (ratio > 0) return 'Oh oh, podemos seguir intentando?';
  return 'No pasa nada, intentemoslo de nuevo paso a paso.';
};

// Native predictive writing support for every learner-facing editable text
// field, including fields inserted later by Speaking, Listening, Grammar,
// Writing, Tutor and Translator renderers. Password/email/number controls
// are intentionally outside the selector.
function enablePredictiveTextFields(root = document) {
  const fields = [];
  if (root.matches?.('textarea, input[type="text"], input[type="search"], [contenteditable="true"]')) {
    fields.push(root);
  }
  root
    .querySelectorAll?.(
      'textarea, input[type="text"], input[type="search"], [contenteditable="true"]'
    )
    .forEach((field) => fields.push(field));
  fields.forEach((field) => {
    if (field.closest('[data-no-predictive="true"]')) return;
    field.spellcheck = true;
    field.setAttribute('spellcheck', 'true');
    field.setAttribute('autocorrect', 'on');
    field.setAttribute('autocapitalize', 'sentences');
    field.setAttribute('inputmode', 'text');
    field.dataset.predictiveText = 'enabled';
  });
}

function initializeGlobalPredictiveText() {
  enablePredictiveTextFields(document);
  if (!document.body || typeof MutationObserver === 'undefined') return;
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.ELEMENT_NODE) enablePredictiveTextFields(node);
      });
    });
  });
  observer.observe(document.body, { childList: true, subtree: true });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeGlobalPredictiveText, { once: true });
} else {
  initializeGlobalPredictiveText();
}

