function renderSpeakingSttHtml(lesson) {
  const prompt = lesson.mission || lesson.intro || lesson.description || '';
  return `
    <div class="speaking-simple-panel">
      <span class="speaking-step-kicker">Hablar a texto · STT</span>
      <h4>Habla y mira cómo aparece tu respuesta</h4>
      <p>${escapeHtml(prompt)}</p>
      <textarea id="speakingTranscript" class="speaking-transcript" rows="6" placeholder="Pulsa «Empezar a dictar» y habla con naturalidad…"></textarea>
      <div class="speaking-simple-actions">
        <button type="button" class="primary-btn speaking-stt-start">🎙️ Empezar a dictar</button>
        <button type="button" class="secondary-btn speaking-stt-stop">■ Detener</button>
        <button type="button" class="secondary-btn speaking-correct-btn" disabled>Revisar lo que dije</button>
      </div>
      <p class="speaking-transcript-hint">Puedes corregir el texto antes de enviarlo. El audio no se conserva.</p>
      <div class="speaking-correction-result" aria-live="polite" hidden></div>
    </div>
  `;
}

function wireSpeakingSttMode(content, lesson) {
  resetSpeakingRecorder();
  speakingRecorder.container = content;
  speakingRecorder.lesson = lesson;
  speakingRecorder.correctionContext = {
    activityType: 'speech_to_text',
    situation: lesson.mission || lesson.intro || '',
    prompt: lesson.dialogue?.[0]?.line || ''
  };
  const transcript = content.querySelector('.speaking-transcript');
  transcript?.addEventListener('input', () => {
    speakingRecorder.transcript = transcript.value;
    speakingRecorder.transcriptEdited = true;
    updateSpeakingCorrectButtonState(content);
  });
  content.querySelector('.speaking-stt-start')?.addEventListener('click', () => {
    speakingRecorder.transcriptEdited = false;
    startSpeakingTranscription(content);
    const button = content.querySelector('.speaking-stt-start');
    if (button) button.textContent = '🔴 Escuchando…';
  });
  content.querySelector('.speaking-stt-stop')?.addEventListener('click', () => {
    stopSpeakingTranscription();
    const button = content.querySelector('.speaking-stt-start');
    if (button) button.textContent = '🎙️ Seguir dictando';
  });
  content.querySelector('.speaking-correct-btn')?.addEventListener('click', () => {
    requestSpeakingCorrection(content, lesson, speakingRecorder.correctionContext);
  });
  updateSpeakingCorrectButtonState(content);
}

function getPronunciationModels(lesson) {
  const fallbackByLanguage = {
    english: [
      'I am ready to practice English today.',
      'Please listen carefully and repeat after me.',
      'I can speak clearly and confidently.',
      'This sentence helps me improve my pronunciation.',
      'Learning a language takes practice every day.'
    ],
    french: [
      'Je suis prêt à pratiquer le français aujourd’hui.',
      'Écoutez attentivement et répétez après moi.',
      'Je peux parler clairement et avec confiance.',
      'Cette phrase améliore ma prononciation.',
      'Apprendre une langue demande une pratique quotidienne.'
    ],
    spanish: [
      'Estoy listo para practicar español hoy.',
      'Escucha con atención y repite después de mí.',
      'Puedo hablar con claridad y confianza.',
      'Esta oración mejora mi pronunciación.',
      'Aprender un idioma requiere práctica diaria.'
    ]
  };
  const fromLesson = [
    speakingViewState.pronunciationOverride,
    ...(lesson.dialogue || []).map((line) => line.line),
    ...(lesson.phrases || []),
    ...(lesson.vocabulary || []).map((item) => item.example),
    ...String(lesson.intro || '').split(/(?<=[.!?])\s+/),
    ...String(lesson.mission || '').split(/(?<=[.!?])\s+/)
  ];
  const unique = [];
  [...fromLesson, ...(fallbackByLanguage[learningPathState.language] || fallbackByLanguage.english)].forEach((item) => {
    const sentence = String(item || '').replace(/\s+/g, ' ').trim();
    if (sentence && !unique.some((known) => known.toLocaleLowerCase() === sentence.toLocaleLowerCase())) {
      unique.push(sentence);
    }
  });
  return unique.slice(0, 5);
}

function renderPronunciationPracticeHtml(lesson) {
  const models = getPronunciationModels(lesson);
  const activeIndex = Math.min(speakingViewState.pronunciationIndex, models.length - 1);
  const model = models[activeIndex] || lesson.title;
  return `
    <div class="speaking-simple-panel pronunciation-practice">
      <span class="speaking-step-kicker">Pronunciación</span>
      <h4>Lee y evalúa 5 oraciones</h4>
      <p class="pronunciation-intro">Elige una oración, escucha el modelo, léela en voz alta y evalúa lo que el reconocimiento entendió.</p>
      <div class="pronunciation-sentence-picker" role="group" aria-label="Cinco oraciones de práctica">
        ${models
          .map(
            (sentence, index) =>
              `<button type="button" class="pronunciation-sentence-btn${index === activeIndex ? ' is-active' : ''}" data-pronunciation-index="${index}" aria-pressed="${index === activeIndex}"><span>${index + 1}</span>${escapeHtml(sentence)}</button>`
          )
          .join('')}
      </div>
      <div class="pronunciation-model">
        <div><small>Oración ${activeIndex + 1} de ${models.length}</small><p>${escapeHtml(model)}</p></div>
        <button type="button" class="secondary-btn speaking-pronunciation-listen">🔊 Escuchar modelo</button>
      </div>
      <ol class="speaking-mini-steps"><li>Escucha el modelo.</li><li>Graba la misma frase.</li><li>Evalúa qué entendió el reconocimiento de voz.</li></ol>
      ${renderSpeakingRecorderHtml()}
      <p class="pronunciation-disclaimer">La evaluación usa la transcripción reconocida como referencia de claridad; no sustituye el análisis de un profesor.</p>
    </div>
  `;
}

function wirePronunciationMode(content, lesson) {
  const models = getPronunciationModels(lesson);
  const activeIndex = Math.min(speakingViewState.pronunciationIndex, models.length - 1);
  const model = models[activeIndex] || lesson.title;
  resetSpeakingRecorder();
  content.querySelectorAll('.pronunciation-sentence-btn').forEach((button) => {
    button.addEventListener('click', () => {
      speakingViewState.pronunciationIndex = Number(button.dataset.pronunciationIndex) || 0;
      renderSpeakingModeContent(content.closest('.skill-view-content'), lesson);
    });
  });
  content.querySelector('.speaking-pronunciation-listen')?.addEventListener('click', () => {
    playModelPhrase(model, getPronunciationLocale(learningPathState.language), learningPathState.language);
  });
  wireSpeakingRecorderControls(content, lesson, {
    activityType: 'pronunciation',
    situation: `Repite la frase modelo: ${model}`,
    prompt: model,
    conversationHistory: []
  });
  const correctBtn = content.querySelector('.speaking-correct-btn');
  if (correctBtn) correctBtn.textContent = `Evaluar oración ${activeIndex + 1}`;
}

// Turn-by-turn walkthrough (§3.A): the first distinct speaker plays as the
// tutor/character turn (auto-playable, "Continuar" advances); the second
// distinct speaker is treated as the student's turn and gets the shared
// recorder block. Kept short by construction - it just replays however many
// turns the unit's own dialogue already has (3-7 for A1 content), never
// invented here.
function renderGuidedPracticeHtml(lesson, dialogueSource) {
  const lines = dialogueSource.guidedLines || dialogueSource.lines;
  if (!lines.length) {
    return `<p class="skill-graph-empty">${speakingUiText('Todavía no hay un diálogo guiado para esta unidad.', 'Aucun dialogue guidé n’est encore disponible pour cette unité.')}</p>`;
  }
  const participants = [...new Set(lines.map((line) => line.speaker).filter(Boolean))];
  const studentRole = participants[1] || participants[0];
  const turnIndex = Math.min(speakingViewState.guidedTurnIndex, lines.length - 1);
  const turn = lines[turnIndex];
  const isStudentTurn = turn.speaker === studentRole && participants.length > 1;
  const progressLabel = speakingUiText(
    `Turno ${turnIndex + 1} de ${lines.length}`,
    `Réplique ${turnIndex + 1} sur ${lines.length}`
  );

  const historyHtml = lines
    .slice(0, turnIndex)
    .map(
      (line) =>
        `<li class="dialogue-line dialogue-line--done"><span class="dialogue-speaker">${escapeHtml(line.speaker || '')}</span><span class="dialogue-text">${escapeHtml(line.line || '')}</span></li>`
    )
    .join('');

  return `
    <section class="dialogue-personal-practice" aria-label="${speakingUiText('Practicar diálogo', 'Pratiquer le dialogue')}">
    <header class="dialogue-personal-practice-head"><span>${speakingUiText('Ahora te toca', 'À vous de jouer')}</span><h4>${speakingUiText('Practicar diálogo', 'Pratiquer le dialogue')}</h4><p>${speakingUiText('Interpreta uno de los personajes. Usa el modelo como apoyo, pero responde con tu nombre, experiencias, gustos u opiniones.', 'Jouez le rôle d’un personnage. Utilisez le modèle comme aide, mais répondez avec votre nom, vos expériences, vos goûts ou vos opinions.')}</p></header>
    <p class="speaking-guided-progress">${escapeHtml(progressLabel)}</p>
    ${historyHtml ? `<ul class="dialogue-lines-list dialogue-lines-list--history">${historyHtml}</ul>` : ''}
    <div class="speaking-guided-turn">
      <span class="dialogue-speaker">${escapeHtml(turn.speaker || '')}${isStudentTurn ? speakingUiText(' (tú)', ' (vous)') : ''}</span>
      <p class="speaking-guided-turn-text">${escapeHtml(turn.line || '')}</p>
      ${isStudentTurn ? `<p class="dialogue-personal-model"><strong>${speakingUiText('Modelo flexible', 'Modèle flexible')}:</strong> ${escapeHtml(turn.line || '')}<br><small>${speakingUiText('No tienes que repetirlo literalmente: cambia la información por la tuya.', 'Ne le répétez pas mot à mot : remplacez les informations par les vôtres.')}</small></p>` : ''}
      ${supportsSpeech() ? `<button type="button" class="secondary-btn speaking-guided-listen-btn">🔊 ${speakingUiText('Escuchar', 'Écouter')}</button>` : ''}
    </div>
    ${
      isStudentTurn
        ? renderSpeakingRecorderHtml() +
          `<div class="speaking-guided-actions"><button type="button" class="secondary-btn speaking-guided-next-btn" ${turnIndex >= lines.length - 1 ? 'hidden' : ''}>${speakingUiText('Continuar diálogo', 'Continuer le dialogue')} →</button></div>`
        : `<div class="speaking-guided-actions"><button type="button" class="primary-btn speaking-guided-next-btn" ${turnIndex >= lines.length - 1 ? 'hidden' : ''}>${speakingUiText('Continuar', 'Continuer')} →</button></div>`
    }
    </section>
  `;
}

function wireGuidedPracticeMode(content, lesson, dialogueSource) {
  const lines = dialogueSource.guidedLines || dialogueSource.lines;
  if (!lines.length) return;
  const participants = [...new Set(lines.map((line) => line.speaker).filter(Boolean))];
  const studentRole = participants[1] || participants[0];
  const turnIndex = Math.min(speakingViewState.guidedTurnIndex, lines.length - 1);
  const turn = lines[turnIndex];
  const isStudentTurn = turn.speaker === studentRole && participants.length > 1;
  const locale = getPronunciationLocale(learningPathState.language);
  const rate = getDefaultPronunciationRate();

  content.querySelector('.speaking-guided-listen-btn')?.addEventListener('click', () => {
    speakText(turn.line, { locale, rate });
  });

  if (isStudentTurn) {
    const priorTurns = lines.slice(Math.max(0, turnIndex - 3), turnIndex).map((line) => ({
      role: line.speaker === studentRole ? 'student' : 'tutor',
      content: line.line
    }));
    resetSpeakingRecorder();
    wireSpeakingRecorderControls(content, lesson, {
      activityType: 'guided_dialogue',
      situation: dialogueSource.situacion,
      prompt: turn.line,
      conversationHistory: priorTurns
    });
  }

  content.querySelector('.speaking-guided-next-btn')?.addEventListener('click', () => {
    speakingViewState.guidedTurnIndex = Math.min(turnIndex + 1, lines.length - 1);
    renderSpeakingModeContent(content.closest('.skill-view-content'), lesson);
  });
}

function renderDialoguePracticeSkeletonHtml(dialogueSource) {
  const lines = dialogueSource.guidedLines || dialogueSource.lines || [];
  const editableLines = lines.map((item, lineIndex) => {
    const segments = String(item.line || '').split(/\.{3}|…/);
    const lineHtml = segments.map((segment, segmentIndex) => {
      const text = escapeHtml(segment);
      if (segmentIndex >= segments.length - 1) return text;
      return `${text}<input type="text" class="dialogue-practice-blank" data-dialogue-practice-line="${lineIndex}" aria-label="${speakingUiText('Completa con tu información', 'Complétez avec vos informations')}" placeholder="${speakingUiText('tu información', 'vos informations')}" autocomplete="off">`;
    }).join('');
    return `<li class="dialogue-line dialogue-practice-line"><span class="dialogue-speaker">${escapeHtml(item.speaker || '')}</span><span class="dialogue-text">${lineHtml}</span></li>`;
  }).join('');

  return `
    <section class="dialogue-personal-practice" aria-label="${speakingUiText('Practicar diálogo', 'Pratiquer le dialogue')}">
      <header class="dialogue-personal-practice-head">
        <span>${speakingUiText('Ahora les toca a ustedes', 'À vous de jouer')}</span>
        <h4>${speakingUiText('Practicar diálogo', 'Pratiquer le dialogue')}</h4>
        <p>${speakingUiText('Completen los espacios con sus nombres, edades, lugares, gustos, experiencias u opiniones. Después representen la conversación completa en parejas.', 'Complétez les espaces avec vos noms, âges, lieux, goûts, expériences ou opinions. Jouez ensuite toute la conversation à deux.')}</p>
      </header>
      <ul class="dialogue-lines-list dialogue-practice-lines">${editableLines}</ul>
      <div class="games-action-row"><button type="button" class="secondary-btn dialogue-practice-reset">Limpiar respuestas</button></div>
    </section>`;
}

// Diálogos cotidianos (§2/§3.B): Écouter (sequential + per-line playback,
// translation toggle) and Jouer un rôle (pick a character; the other role's
// lines play back as scripted audio/text - not a live AI improvisation, see
// the redesign report's noted limitation; the student's own lines now get
// the full record/transcribe/correct block instead of a plain textarea).
function renderDialogueModeHtml(dialogueSource) {
  const lines = dialogueSource.lines;
  const canSpeak = supportsSpeech();

  if (!lines.length) {
    return `<p class="speaking-situation"><strong>${speakingUiText('Situación', 'Situation')} :</strong> ${escapeHtml(dialogueSource.situacion)}</p><p class="skill-graph-empty">${speakingUiText('Todavía no hay un diálogo de ejemplo para esta unidad.', 'Aucun dialogue modèle n’est encore disponible pour cette unité.')}</p>`;
  }

  const linesHtml = lines
    .map(
      (line, index) => `
      <li class="dialogue-line" data-index="${index}">
        <span class="dialogue-speaker">${escapeHtml(line.speaker || '')}</span>
        <span class="dialogue-text">${escapeHtml(line.line || '')}</span>
        ${canSpeak ? `<button type="button" class="dialogue-line-speak-btn" data-speak-text="${escapeHtml(line.line || '')}" aria-label="${speakingUiText('Escuchar esta línea', 'Écouter cette réplique')}" title="${speakingUiText('Escuchar', 'Écouter')}">🔊</button>` : ''}
        ${line.translation ? `<span class="dialogue-translation reading-vocab-support" hidden>${escapeHtml(line.translation)}</span>` : ''}
      </li>`
    )
    .join('');

  const participants = [...new Set(lines.map((line) => line.speaker || speakingUiText('Personaje', 'Personnage')))];
  const castHtml = participants
    .slice(0, 2)
    .map((speaker, index) => `<span class="dialogue-voice-chip dialogue-voice-chip--${index + 1}"><b>${index === 0 ? '🟣' : '🟡'}</b><span>${escapeHtml(speaker)}<small>Voz ${index + 1}</small></span></span>`)
    .join('');

  return `
    <header class="dialogue-section-header">
      <span>${speakingUiText('Conversación completa de la unidad', 'Conversation complète de l’unité')}</span>
      <h4>${escapeHtml(dialogueSource.title)}</h4>
    </header>
    <p class="dialogue-situation"><strong>${speakingUiText('Situación', 'Situation')} :</strong> ${escapeHtml(dialogueSource.situacion)}</p>
    <div class="dialogue-voice-cast" aria-label="Personajes y voces">${castHtml}</div>
    <div class="dialogue-panel dialogue-listen-panel">
      ${canSpeak ? `<div class="dialogue-audio-player" aria-label="${speakingUiText('Reproductor del diálogo', 'Lecteur du dialogue')}">
        <button type="button" class="primary-btn dialogue-play-all-btn">▶ ${speakingUiText('Reproducir diálogo', 'Lire le dialogue')}</button>
        <button type="button" class="secondary-btn dialogue-stop-btn" hidden>■ ${speakingUiText('Detener', 'Arrêter')}</button>
        <span class="dialogue-audio-hint">${speakingUiText('Usaremos una voz por personaje cuando el dispositivo tenga dos disponibles.', 'Une voix sera attribuée à chaque personnage lorsque l’appareil en propose deux.')}</span>
      </div>` : ''}
      <ul class="dialogue-lines-list">${linesHtml}</ul>
      ${lines.some((line) => line.translation) ? `<button type="button" class="secondary-btn dialogue-toggle-translation-btn">${speakingUiText('Mostrar apoyo en español', 'Afficher l’aide en espagnol')}</button>` : ''}
    </div>
    ${renderDialoguePracticeSkeletonHtml(dialogueSource)}
  `;
}

function wireDialogueMode(content, lesson, dialogueSource) {
  const lines = dialogueSource.lines;
  if (!lines.length) return;
  const locale = getPronunciationLocale(learningPathState.language);
  const rate = getDefaultPronunciationRate();
  const canSpeak = supportsSpeech();

  content.querySelector('.dialogue-practice-reset')?.addEventListener('click', () => {
    content.querySelectorAll('.dialogue-practice-blank').forEach((input) => { input.value = ''; });
    content.querySelector('.dialogue-practice-blank')?.focus();
  });

  content.querySelectorAll('.dialogue-mode-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      content.querySelectorAll('.dialogue-mode-btn').forEach((b) => b.classList.toggle('is-active', b === btn));
      const showListen = btn.dataset.mode === 'listen';
      content.querySelector('.dialogue-listen-panel')?.toggleAttribute('hidden', !showListen);
      content.querySelector('.dialogue-roleplay-panel')?.toggleAttribute('hidden', showListen);
    });
  });

  const playAllButton = content.querySelector('.dialogue-play-all-btn');
  const stopButton = content.querySelector('.dialogue-stop-btn');
  playAllButton?.addEventListener('click', () => {
    const alternating = playDialogueLinesSequentially(lines, locale, rate, content);
    playAllButton.hidden = true;
    stopButton.hidden = false;
    const hint = content.querySelector('.dialogue-audio-hint');
    if (hint) {
      hint.textContent = alternating
        ? speakingUiText('Voces alternadas activadas.', 'Voix alternées activées.')
        : speakingUiText('Tu dispositivo usa una sola voz compatible.', 'Votre appareil utilise une seule voix compatible.');
    }
  });
  stopButton?.addEventListener('click', () => {
    stopDialoguePlayback();
    stopButton.hidden = true;
    playAllButton.hidden = false;
  });

  content.querySelectorAll('.dialogue-line-speak-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      stopDialoguePlayback();
      const lineElement = btn.closest('.dialogue-line');
      const line = lines[Number(lineElement?.dataset.index) || 0];
      const { speakerVoices } = getDialogueVoiceBySpeaker(lines, locale);
      speakText(btn.dataset.speakText, {
        locale,
        rate,
        voice: speakerVoices.get(line?.speaker || 'Narrador/a')
      });
    });
  });

  content.querySelector('.dialogue-toggle-translation-btn')?.addEventListener('click', (event) => {
    const btn = event.currentTarget;
    const nowHidden = content.querySelector('.dialogue-translation')?.hidden;
    content.querySelectorAll('.dialogue-translation').forEach((el) => {
      el.hidden = !nowHidden;
    });
    btn.textContent = nowHidden
      ? speakingUiText('Ocultar apoyo en español', 'Masquer l’aide en espagnol')
      : speakingUiText('Mostrar apoyo en español', 'Afficher l’aide en espagnol');
  });

  content.querySelectorAll('.dialogue-role-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      content.querySelectorAll('.dialogue-role-btn').forEach((b) => b.classList.toggle('is-active', b === btn));
      const myRole = btn.dataset.role;
      const list = content.querySelector('.dialogue-roleplay-lines');
      if (!list) return;

      // Rebuilding the list below would otherwise orphan a live
      // "Responder oralmente" recorder if one was mounted for the
      // previously chosen character - release it first.
      resetSpeakingRecorder();

      list.innerHTML = lines
        .map((line, index) => {
          const isMine = line.speaker === myRole;
          if (!isMine) {
            return `
              <li class="dialogue-line">
                <span class="dialogue-speaker">${escapeHtml(line.speaker || '')}</span>
                <span class="dialogue-text">${escapeHtml(line.line || '')}</span>
                ${canSpeak ? `<button type="button" class="dialogue-line-speak-btn" data-speak-text="${escapeHtml(line.line || '')}" aria-label="Escuchar esta línea">🔊</button>` : ''}
              </li>`;
          }
          return `
            <li class="dialogue-line dialogue-line--mine" data-index="${index}">
              <span class="dialogue-speaker">${escapeHtml(line.speaker || '')}${speakingUiText(' (tú)', ' (vous)')}</span>
              <p class="dialogue-model-line" hidden>${escapeHtml(line.line || '')}</p>
              <button type="button" class="secondary-btn dialogue-show-model-btn">${speakingUiText('Ver el modelo', 'Voir le modèle')}</button>
              <button type="button" class="secondary-btn dialogue-respond-btn" data-index="${index}">🎙 ${speakingUiText('Responder oralmente', 'Répondre à l’oral')}</button>
              <div class="dialogue-respond-block" hidden></div>
            </li>`;
        })
        .join('');

      list.querySelectorAll('.dialogue-line-speak-btn').forEach((speakBtn) => {
        speakBtn.addEventListener('click', () => speakText(speakBtn.dataset.speakText, { locale, rate }));
      });
      list.querySelectorAll('.dialogue-show-model-btn').forEach((modelBtn) => {
        modelBtn.addEventListener('click', () => {
          const modelLine = modelBtn.previousElementSibling;
          if (modelLine) modelLine.hidden = !modelLine.hidden;
        });
      });
      // "Responder oralmente" lazily mounts the shared recorder block into
      // this specific line's own slot, the first time it's clicked, so
      // switching characters never leaves multiple live recorders wired at
      // once (only the most recently mounted one is ever active - matches
      // speakingRecorder's single-instance assumption).
      list.querySelectorAll('.dialogue-respond-btn').forEach((respondBtn) => {
        respondBtn.addEventListener('click', () => {
          const li = respondBtn.closest('.dialogue-line--mine');
          const block = li?.querySelector('.dialogue-respond-block');
          if (!block) return;

          // Only one "Responder oralmente" recorder is ever mounted at a
          // time - collapsing any other already-open one first avoids two
          // live copies of the shared recorder block (duplicate ids,
          // stale button handlers still pointing at a container that's no
          // longer speakingRecorder.container) if the student answers more
          // than one line in the same roleplay pass.
          resetSpeakingRecorder();
          list.querySelectorAll('.dialogue-respond-block:not([hidden])').forEach((openBlock) => {
            openBlock.hidden = true;
            openBlock.innerHTML = '';
          });
          list.querySelectorAll('.dialogue-respond-btn[hidden]').forEach((hiddenBtn) => {
            hiddenBtn.hidden = false;
          });

          const lineIndex = Number(respondBtn.dataset.index);
          const priorTurns = lines.slice(Math.max(0, lineIndex - 3), lineIndex).map((l) => ({
            role: l.speaker === myRole ? 'student' : 'tutor',
            content: l.line
          }));
          block.hidden = false;
          block.innerHTML = renderSpeakingRecorderHtml();
          wireSpeakingRecorderControls(block, lesson, {
            activityType: 'roleplay',
            situation: dialogueSource.situacion,
            prompt: lines[lineIndex]?.line || '',
            conversationHistory: priorTurns
          });
          respondBtn.hidden = true;
        });
      });
    });
  });
}

// Respuesta libre (§13's original flow): the open speaking prompt this
// section always had, now feeding the shared recorder/transcript/correction
// block instead of the old plain textarea + audio-upload button.
function renderFreeResponseHtml(lesson) {
  const situacion = lesson.mission || lesson.intro || lesson.description || '';
  const fraseModelo = lesson.dialogue?.[0]?.line || lesson.phrases?.[0] || '';
  return `
    <p class="speaking-situation"><strong>Situación:</strong> ${escapeHtml(situacion)}</p>
    ${fraseModelo ? `<p class="speaking-model"><strong>Frase o turno del Tutor:</strong> ${escapeHtml(fraseModelo)}</p>` : ''}
    ${
      lesson.phrases?.length
        ? `<div class="dialogue-phrases"><strong>Vocabulario útil</strong><ul>${lesson.phrases.map((phrase) => `<li>${escapeHtml(phrase)}</li>`).join('')}</ul></div>`
        : ''
    }
    ${renderSpeakingRecorderHtml()}
  `;
}

function wireFreeResponseMode(content, lesson) {
  const situacion = lesson.mission || lesson.intro || lesson.description || '';
  const fraseModelo = lesson.dialogue?.[0]?.line || lesson.phrases?.[0] || '';
  resetSpeakingRecorder();
  wireSpeakingRecorderControls(content, lesson, {
    activityType: 'free_response',
    situation: situacion,
    prompt: fraseModelo,
    conversationHistory: []
  });
}

// Renders whichever mode is active into #speakingStage without touching the
// mode tabs or the lesson header - called on first render and again every
// time the student switches modes or advances a guided-practice turn.
function renderSpeakingModeContent(content, lesson) {
  const stage = content.querySelector('#speakingStage');
  if (!stage) return;
  // Rebuilding the stage's innerHTML below would otherwise orphan a live
  // MediaRecorder/mic stream or Web Speech recognition instance if the
  // student switches modes (or advances a guided-practice turn) mid-
  // recording - always release it first, exactly like navigating away from
  // Speaking entirely already does.
  resetSpeakingRecorder();
  const dialogueSource = getSpeakingDialogueSource(lesson);

  content.querySelectorAll('.speaking-mode-btn').forEach((btn) => {
    btn.classList.toggle('is-active', btn.dataset.speakingMode === speakingViewState.mode);
    btn.setAttribute('aria-pressed', String(btn.dataset.speakingMode === speakingViewState.mode));
  });

  if (speakingViewState.mode === 'dialogue') {
    stage.innerHTML = renderDialogueModeHtml(dialogueSource);
    wireDialogueMode(stage, lesson, dialogueSource);
  } else if (speakingViewState.mode === 'corrector') {
    stage.innerHTML = renderSpeakingCorrectorHtml();
    setupCorrector();
    const correctorLanguage = stage.querySelector('#correctorLangSelect');
    if (correctorLanguage && [...correctorLanguage.options].some((option) => option.value === learningPathState.language)) {
      correctorLanguage.value = learningPathState.language;
    }
    if (pendingSpeakingCorrectorText) {
      const correctorInput = stage.querySelector('#correctorInput');
      if (correctorInput) {
        correctorInput.value = pendingSpeakingCorrectorText.slice(0, 1000);
        correctorInput.dispatchEvent(new Event('input'));
      }
      pendingSpeakingCorrectorText = '';
    }
  } else if (speakingViewState.mode === 'record') {
    stage.innerHTML = renderFreeResponseHtml(lesson);
    wireFreeResponseMode(stage, lesson);
  } else if (speakingViewState.mode === 'stt') {
    stage.innerHTML = renderSpeakingSttHtml(lesson);
    wireSpeakingSttMode(stage, lesson);
  } else if (speakingViewState.mode === 'pronunciation') {
    stage.innerHTML = renderPronunciationPracticeHtml(lesson);
    wirePronunciationMode(stage, lesson);
  } else {
    stage.innerHTML = renderGuidedPracticeHtml(lesson, dialogueSource);
    wireGuidedPracticeMode(stage, lesson, dialogueSource);
  }
}

function renderSpeakingView(section, lesson) {
  const content = section.querySelector('.skill-view-content');
  if (!content) return;
  resetSpeakingRecorder();

  if (speakingViewState.lessonSlug !== lesson.slug) {
    speakingViewState = {
      lessonSlug: lesson.slug,
      mode: 'dialogue',
      guidedTurnIndex: 0,
      pronunciationIndex: 0,
      pronunciationOverride: ''
    };
  }

  const taskConfig = {
    minimumSeconds: 5,
    targetSeconds: 30,
    maximumSeconds: 60,
    allowShortSubmission: false,
    ...(lesson.speakingTask || {})
  };
  speakingRecorder.config = taskConfig;

  content.innerHTML = `
    <h3>${escapeHtml(lesson.title)}</h3>
    ${renderSpeakingModeTabsHtml(speakingViewState.mode)}
    <div id="speakingStage" class="speaking-stage"></div>
  `;

  content.querySelectorAll('.speaking-mode-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      if (btn.dataset.speakingMode === 'tutor') {
        openTutorDrawer({
          skill: 'speaking',
          contextScope: 'lesson',
          lessonTitle: lesson.title,
          lessonIntro: lesson.intro || lesson.description || '',
          lessonSlug: lesson.slug,
          supportMode: 'practice',
          currentActivity: `Tutor dentro de la lección de Speaking: ${lesson.title}`,
          // Speaking's free conversation is otherwise a blank textbox facing
          // the student - this gives the tutor an explicit, mandatory nudge
          // to open with a concrete topic/question tied to the lesson
          // instead of waiting on the student to invent one (see the
          // matching skill==='speaking' guidance in aiTutorService's
          // buildTutorInput).
          fallbackPrompt: `Quiero practicar una conversación oral sobre "${lesson.title}". Es el inicio: propón tú un tema o una situación concreta relacionada con la lección y hazme una pregunta sencilla para que yo empiece a hablar.`,
          welcomeMessage: speakingUiText(
            `👋 Vamos a conversar en voz sobre «${lesson.title}». Pulsa «Hablar» o escribe algo - si no sabes por dónde empezar, solo pulsa «Enviar» y el Tutor te propondrá un tema.`,
            `👋 Parlons à voix haute de « ${lesson.title} ». Appuyez sur « Parler » ou écrivez quelque chose - si vous ne savez pas par où commencer, appuyez simplement sur « Envoyer » et le Tuteur vous proposera un sujet.`
          )
        });
        return;
      }
      speakingViewState.mode = btn.dataset.speakingMode;
      speakingViewState.guidedTurnIndex = 0;
      if (btn.dataset.speakingMode === 'pronunciation') {
        speakingViewState.pronunciationIndex = 0;
        speakingViewState.pronunciationOverride = '';
      }
      renderSpeakingModeContent(content, lesson);
    });
  });

  renderSpeakingModeContent(content, lesson);
}

// Print-only Q&A worksheet shared by Grammar and Vocabulary PDFs -
// deliberately independent from the interactive .mcq-option exercises
// rendered on-screen (renderLessonExercise), so the printable answer key
// (showAnswers: true) never touches or risks the interactive component.
// Letters (A/B/C/D) are a print-worksheet convention only - the on-screen
// exercises never show them (see renderLessonExercise).
function renderPrintableExerciseList(exercises, { showAnswers = false } = {}) {
  const letters = ['A', 'B', 'C', 'D'];
  return (exercises || [])
    .filter((item) => item.type === 'mcq' && Array.isArray(item.options))
    .map((item, index) => {
      const optionsHtml = item.options
        .map((option, optIndex) => {
          const isCorrect = showAnswers && optIndex === Number(item.answer);
          return `<li class="skill-print-option${isCorrect ? ' is-correct-answer' : ''}">${letters[optIndex] || optIndex + 1}) ${escapeHtml(optionLabel(option) || '')}</li>`;
        })
        .join('');
      return `
        <div class="skill-print-question">
          <p><strong>${index + 1}.</strong> ${escapeHtml(item.prompt)}</p>
          <ul class="skill-print-options">${optionsHtml}</ul>
        </div>
      `;
    })
    .join('');
}

// Shared compact print header for every printable skill document. It keeps
// the course metadata but omits the redundant "ANDERGO Language Academy"
// line below the official logo so page-one content starts higher.
// `answerKey` renders the teacher/admin variant
// (correct options marked) instead of the student worksheet (blank answer
// lines) - gated by entitlements.role==='ceo' (this app's only staff/admin
// role today - see lib/entitlementsService.js) at the call site, never
// decided here.
function renderSkillPrintHeaderHtml(lesson) {
  const bridgeLabel = LanguagePair
    ? LanguagePair.languageNameIn(learningPathState.bridgeLanguage, learningPathState.bridgeLanguage)
    : languageDisplayNames[learningPathState.bridgeLanguage] || learningPathState.bridgeLanguage;
  const targetLabel = LanguagePair
    ? LanguagePair.languageNameIn(learningPathState.bridgeLanguage, learningPathState.language)
    : languageDisplayNames[learningPathState.language] || learningPathState.language;
  const unit = lesson?.unitId
    ? learningPathState.units.find((item) => item.id === lesson.unitId)
    : null;
  return `
    <div class="print-only reading-print-header skill-print-header">
      <img class="skill-print-brand-image" src="/andergo-logo.png" alt="ANDERGO - Learn Any Language. Unlock Your World." />
      <p class="skill-print-language-pair">
        <span>Idioma puente: <strong>${escapeHtml(bridgeLabel)}</strong></span>
        <span aria-hidden="true">→</span>
        <span>Idioma meta: <strong>${escapeHtml(targetLabel)}</strong></span>
        <span>· Nivel <strong>${escapeHtml(learningPathState.level)}</strong></span>
      </p>
      ${unit?.title ? `<p class="skill-print-unit">${escapeHtml(unit.title)}</p>` : ''}
      <p class="reading-print-date">${escapeHtml(new Date().toLocaleDateString('es'))}</p>
    </div>
  `;
}

function isStaffEntitled() {
  return authStatus.entitlements?.role === 'ceo';
}

function renderGrammarConceptCards(lesson) {
  const note = String(lesson.grammar || lesson.description || '').trim();
  const phrases = Array.isArray(lesson.phrases) ? lesson.phrases.filter(Boolean) : [];
  const profile = lesson.extra?.grammarProfile || {};
  const parsedSections = parseGrammarNoteSections(note);
  const sectionBody = (...keys) =>
    parsedSections.find((section) => keys.includes(section.key))?.body || '';
  const sentences = note
    .split(/(?<=[.!?])\s+/)
    .map((item) => item.trim())
    .filter(Boolean);
  const french = isFrenchTargetLanguage();
  const cards = [
    {
      icon: '💡',
      tone: 'idea',
      label: french ? 'Définition' : 'Definition',
      title: french ? 'Comprendre la règle' : 'What this grammar is',
      body:
        profile.definition ||
        profile.explanation ||
        sectionBody('rule') ||
        sentences[0] ||
        note
    },
    {
      icon: '🧩',
      tone: 'structure',
      label: 'Structure',
      title: french ? 'Construire la phrase' : 'How it is formed',
      body:
        profile.structure ||
        sectionBody('pattern', 'affirmative', 'negative', 'questions') ||
        (phrases[0]
          ? `${french ? 'Schéma central' : 'Core pattern'} : ${phrases[0]}`
          : french
            ? `Étudiez la forme et la place de ${profile.name || lesson.title}.`
            : `Study the form and sentence position of ${profile.name || lesson.title}.`)
    },
    {
      icon: '💬',
      tone: 'use',
      label: french ? 'Emploi en français' : 'Function in English',
      title: french ? 'Ce qu’elle permet d’exprimer' : 'What it communicates',
      body:
        profile.function ||
        profile.purpose ||
        sectionBody('goal', 'use') ||
        lesson.description ||
        (french
          ? 'Utilisez-la pour exprimer des idées complexes avec clarté et précision.'
          : 'Use it to communicate the main ideas clearly and accurately.')
    },
    {
      icon: '✍️',
      tone: 'example',
      label: french ? 'Exemples' : 'Practical examples',
      title: french ? 'Formes à retenir' : 'Examples from the lesson',
      body:
        (profile.examples || []).filter(Boolean).join(' · ') ||
        sectionBody('examples', 'affirmative', 'negative', 'questions') ||
        (phrases.length
          ? phrases.join(' · ')
          : french
            ? 'Créez votre propre phrase avec cette structure.'
            : 'Create your own sentence with this structure.')
    }
  ];

  const forms = [
    (profile.affirmative || sectionBody('affirmative')) && {
      key: 'affirmative',
      icon: '✅',
      label: french ? 'Forme affirmative' : 'Afirmativa',
      body: profile.affirmative || sectionBody('affirmative')
    },
    (profile.negative || sectionBody('negative')) && {
      key: 'negative',
      icon: '🚫',
      label: french ? 'Forme négative' : 'Negativa',
      body: profile.negative || sectionBody('negative')
    },
    (profile.questions || sectionBody('questions')) && {
      key: 'questions',
      icon: '❓',
      label: french ? 'Forme interrogative' : 'Interrogativa',
      body: profile.questions || sectionBody('questions')
    }
  ].filter(Boolean);

  return `
    <div class="grammar-card-grid" id="grammar-concepts">
      ${cards
        .map(
          (card, index) => `
        <article class="grammar-concept-card grammar-concept-card--${card.tone}">
          <div class="grammar-concept-card-heading">
            <span class="grammar-concept-icon" aria-hidden="true">${card.icon}</span>
            <span class="grammar-concept-step">${String(index + 1).padStart(2, '0')}</span>
          </div>
          <span>${escapeHtml(card.label)}</span>
          <h4>${escapeHtml(card.title)}</h4>
          <p>${escapeHtml(card.body)}</p>
        </article>
      `
        )
        .join('')}
    </div>
    ${
      forms.length
        ? `<div class="grammar-quick-forms-block">
      <p class="grammar-quick-forms-heading">${french ? 'Formes de la phrase' : 'Formas de la oración'}</p>
      <div class="grammar-quick-forms">
        ${forms
          .map(
            (form) => `
          <article class="grammar-quick-forms--${form.key}">
            <span class="grammar-form-label">${form.icon} ${escapeHtml(form.label)}</span>
            <p>${escapeHtml(form.body).replace(/\n/g, '<br>')}</p>
          </article>`
          )
          .join('')}
      </div>
    </div>`
        : ''
    }
  `;
}

