function normalizeGameText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase()
    .replace(/[^\p{L}]/gu, '');
}

// Shared by loadGamesVocabulary (A1-only, short words for the word
// search/match games) and getHangmanChallengeWords (higher levels, long
// words for Ahorcado on Desafío) so both read lesson vocabulary the same way.
function vocabularyFromLessons(lessons, { minLength, maxLength }) {
  const seen = new Set();
  return lessons
    .flatMap((lesson) => lesson.vocabulary || [])
    .map((item) => ({ term: item.term || item.word || item.text || '', translation: item.translation || item.meaning || item.es || '' }))
    .filter(({ term, translation }) => {
      const normalized = normalizeGameText(term);
      if (normalized.length < minLength || normalized.length > maxLength || seen.has(normalized)) return false;
      seen.add(normalized);
      return Boolean(translation);
    });
}

async function loadGamesVocabulary(language) {
  await ensureLanguageWorld(language);
  const lessons = getLocalFallbackLessons(language, 'A1');
  const words = vocabularyFromLessons(lessons, { minLength: 3, maxLength: 9 }).slice(0, 18);
  return words.length >= 4 ? words : GAME_FALLBACK_VOCABULARY[language].map(([term, translation]) => ({ term, translation }));
}

// Ahorcado on Desafío asks for long (10-12 letter) words specifically. A1
// vocabulary (loadGamesVocabulary's source) is deliberately short/basic, so
// this pulls from higher CEFR levels instead - the language world is already
// loaded by loadGamesVocabulary's ensureLanguageWorld() by the time this
// runs, so it can read window.ANDERGO_LANGUAGE_WORLDS synchronously. Falls
// back to the regular A1 pool if a language's B1-C1 content has no match, so
// Ahorcado never has zero words to choose from.
const HANGMAN_CHALLENGE_LEVELS = ['B1', 'B2', 'C1'];
function getHangmanChallengeWords(language, fallbackWords) {
  const lessons = HANGMAN_CHALLENGE_LEVELS.flatMap((level) => getLocalFallbackLessons(language, level));
  const words = vocabularyFromLessons(lessons, { minLength: 10, maxLength: 12 }).slice(0, 18);
  return words.length ? words : fallbackWords;
}

function getGamesLocale() {
  return LANGUAGE_LOCALES[gamesState.language] || 'en-US';
}

function recordGameSuccess() {
  gamesState.score += getGamesDifficulty().points;
  window.AndergoGamification?.recordCorrectAnswer();
  window.AndergoGamification?.recordSkillTouched('vocabulary', gamesState.language);
  document.querySelector('#gamesApp .games-score-value')?.replaceChildren(String(gamesState.score));
}

function gameButtonHtml(game) {
  return `<button type="button" class="games-type-btn" data-game-id="${game.id}" aria-pressed="${String(gamesState.gameId === game.id)}">${game.icon} ${game.title}</button>`;
}

function getGameRoundWords(words, count, offset = 0) {
  if (!words.length) return [];
  const start = (gamesState.round * count + offset) % words.length;
  return Array.from({ length: Math.min(count, words.length) }, (_, index) => words[(start + index) % words.length]);
}

function makeWordSearch(words) {
  const difficulty = getGamesDifficulty();
  const columns = difficulty.wordSearchColumns || difficulty.wordSearchSize;
  const rows = difficulty.wordSearchRows || difficulty.wordSearchSize;
  const letters = Array.from({ length: columns * rows }, () => String.fromCharCode(65 + Math.floor(Math.random() * 26)));
  const forwardDirections = [
    { row: 0, column: 1, label: 'horizontal' },
    { row: 1, column: 0, label: 'vertical' },
    ...(difficulty.wordSearchDiagonal ? [
      { row: 1, column: 1, label: 'diagonal' },
      { row: 1, column: -1, label: 'diagonal' }
    ] : [])
  ];
  // Only Desafío mixes in the reversed direction of each of the four axes
  // above (right-to-left, bottom-to-top, etc.) - easy/normal keep the
  // "No hay palabras al revés" guarantee their instructions text promises.
  const directions = difficulty.wordSearchReversed
    ? forwardDirections.flatMap((direction) => [
        direction,
        { row: -direction.row, column: -direction.column, label: direction.label }
      ])
    : forwardDirections;
  const targets = getGameRoundWords(words, difficulty.wordSearchWords)
    .map((item) => ({ ...item, word: normalizeGameText(item.term).toUpperCase() }))
    .filter((item) => item.word.length <= Math.max(columns, rows));
  const placed = [];
  const occupied = new Map();
  targets.forEach((target, targetIndex) => {
    const preferred = directions[(targetIndex + gamesState.round) % directions.length];
    const attempts = [preferred, ...directions.filter((direction) => direction !== preferred)];
    let placement = null;
    for (const direction of attempts) {
      for (let tryIndex = 0; tryIndex < 80 && !placement; tryIndex += 1) {
        const row = Math.floor(Math.random() * rows);
        const column = Math.floor(Math.random() * columns);
        const endRow = row + direction.row * (target.word.length - 1);
        const endColumn = column + direction.column * (target.word.length - 1);
        if (endRow < 0 || endRow >= rows || endColumn < 0 || endColumn >= columns) continue;
        const positions = target.word.split('').map((_, index) => (row + direction.row * index) * columns + column + direction.column * index);
        const fits = positions.every((position, index) => !occupied.has(position) || occupied.get(position) === target.word[index]);
        if (fits) placement = { positions, direction: direction.label };
      }
      if (placement) break;
    }
    if (!placement) return;
    placement.positions.forEach((position, index) => {
      const letter = target.word[index];
      letters[position] = letter;
      occupied.set(position, letter);
    });
    placed.push({ ...target, ...placement });
  });
  return { columns, rows, letters, targets: placed };
}

function formatGamesTime(totalSeconds) {
  const seconds = Math.max(0, Math.floor(Number(totalSeconds) || 0));
  return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
}

function updateGamesTimerUi() {
  const display = document.querySelector('#gamesApp .games-timer-display');
  const pauseButton = document.querySelector('#gamesApp .games-timer-pause');
  const stage = document.querySelector('#gamesApp .games-themed-stage');
  if (!display) return;
  const countdown = Number(gamesState.timerMode);
  const value = countdown > 0 ? gamesState.timerRemaining : gamesState.timerElapsed;
  display.textContent = gamesState.timerMode === 'off' ? 'Sin límite' : formatGamesTime(value);
  display.classList.toggle('is-warning', countdown > 0 && value <= 30);
  if (pauseButton) {
    pauseButton.hidden = gamesState.timerMode === 'off' || gamesState.timerFinished;
    pauseButton.textContent = gamesState.timerPaused ? '▶ Continuar' : 'Ⅱ Pausar';
    pauseButton.setAttribute('aria-pressed', String(gamesState.timerPaused));
  }
  if (stage) {
    const paused = gamesState.timerPaused && !gamesState.timerFinished;
    stage.classList.toggle('is-paused', paused);
    stage.inert = paused;
    stage.setAttribute('aria-busy', String(paused));
  }
}

function stopGamesTimer() {
  window.clearInterval(gamesState.timerInterval);
  gamesState.timerInterval = null;
}

function expireGamesTimer() {
  stopGamesTimer();
  gamesState.timerFinished = true;
  document.querySelectorAll('#gamesApp .games-themed-stage button, #gamesApp .games-themed-stage input').forEach((control) => { control.disabled = true; });
  setGamesFeedback('Se acabó el tiempo. Pulsa «Nuevo reto» para intentarlo de nuevo.', 'is-wrong');
  updateGamesTimerUi();
}

function resetGamesTimer() {
  stopGamesTimer();
  gamesState.timerElapsed = 0;
  gamesState.timerRemaining = Number(gamesState.timerMode) || 0;
  gamesState.timerPaused = false;
  gamesState.timerFinished = false;
  gamesState.timerAutoPaused = false;
  const result = document.querySelector('#gamesApp .games-timer-result');
  if (result) result.textContent = '';
  updateGamesTimerUi();
  if (gamesState.timerMode === 'off') return;
  gamesState.timerInterval = window.setInterval(() => {
    if (gamesState.timerPaused || gamesState.timerFinished || document.hidden) return;
    gamesState.timerElapsed += 1;
    if (Number(gamesState.timerMode) > 0) {
      gamesState.timerRemaining = Math.max(0, gamesState.timerRemaining - 1);
      if (gamesState.timerRemaining === 0) expireGamesTimer();
    }
    updateGamesTimerUi();
  }, 1000);
}

function finishGamesTimer(success = true) {
  if (gamesState.timerFinished) return '';
  stopGamesTimer();
  gamesState.timerFinished = true;
  const elapsed = gamesState.timerElapsed;
  let bonus = 0;
  let best = null;
  if (success && gamesState.timerMode !== 'off') {
    bonus = gamesState.difficulty === 'challenge' ? 15 : 5;
    gamesState.score += bonus;
    document.querySelector('#gamesApp .games-score-value')?.replaceChildren(String(gamesState.score));
    const { topic } = getCurrentGamesTheme();
    const key = `andergo_game_best_${gamesState.language}_${gamesState.gameId}_${normalizeGameText(topic.title)}`;
    try {
      const previous = Number(localStorage.getItem(key));
      best = previous > 0 ? Math.min(previous, elapsed) : elapsed;
      localStorage.setItem(key, String(best));
    } catch {
      best = elapsed;
    }
  }
  const summary = gamesState.timerMode === 'off'
    ? 'Ronda completada sin límite de tiempo.'
    : `Tiempo: ${formatGamesTime(elapsed)}${best !== null ? ` · Mejor: ${formatGamesTime(best)}` : ''}${bonus ? ` · +${bonus} puntos` : ''}`;
  const result = document.querySelector('#gamesApp .games-timer-result');
  if (result) result.textContent = summary;
  updateGamesTimerUi();
  return summary;
}

document.addEventListener('visibilitychange', () => {
  if (!document.querySelector('#gamesApp') || gamesState.timerFinished || gamesState.timerMode === 'off') return;
  if (document.hidden && !gamesState.timerPaused) {
    gamesState.timerPaused = true;
    gamesState.timerAutoPaused = true;
  } else if (!document.hidden && gamesState.timerAutoPaused) {
    gamesState.timerPaused = false;
    gamesState.timerAutoPaused = false;
  }
  updateGamesTimerUi();
});

function renderGamesView() {
  const app = document.getElementById('gamesApp');
  if (!app) return;
  const languageLabels = { english: 'Inglés', french: 'Francés', spanish: 'Español' };
  const game = GAMES_CATALOG.find((item) => item.id === gamesState.gameId) || GAMES_CATALOG[0];
  const difficulty = getGamesDifficulty();
  app.innerHTML = `
    <div class="games-topbar">
      <div class="games-language-picker" aria-label="Idioma para jugar"><span>Jugar en</span>${Object.entries(languageLabels).map(([id, label]) => `<button type="button" class="games-language-btn" data-game-language="${id}" aria-pressed="${String(gamesState.language === id)}">${label}</button>`).join('')}</div>
      <div class="games-type-picker" aria-label="Elegir juego">${GAMES_CATALOG.map(gameButtonHtml).join('')}</div>
      <div class="games-difficulty-picker" role="group" aria-label="Grado de dificultad">
        <span>Dificultad</span>
        ${Object.entries(GAME_DIFFICULTIES).map(([id, item]) => `<button type="button" class="games-difficulty-btn games-difficulty-btn--${id}" data-game-difficulty="${id}" aria-pressed="${String(gamesState.difficulty === id)}">${item.icon} ${item.label}</button>`).join('')}
      </div>
    </div>
    <div class="games-difficulty-summary games-difficulty-summary--${gamesState.difficulty}"><span aria-hidden="true">${difficulty.icon}</span><div><strong>${difficulty.label} · ${difficulty.cefr}</strong><small>${difficulty.description}</small></div><b>+${difficulty.points} puntos por acierto</b></div>
    <div class="games-score-strip"><span>Puntos: <strong class="games-score-value">${gamesState.score}</strong></span><span>Idioma: <strong>${languageLabels[gamesState.language]}</strong></span><span>Nivel: <strong>${difficulty.label}</strong></span><span>Reto <strong class="games-round-value">${gamesState.round + 1}</strong></span><div class="games-round-meter"><span>Progreso <strong class="games-round-progress-label">0/0 · 0%</strong></span><progress class="games-round-progress" value="0" max="1" aria-label="Progreso de la ronda"></progress></div><div class="games-timer-controls"><label>Tiempo <select class="games-timer-mode"><option value="stopwatch" ${gamesState.timerMode === 'stopwatch' ? 'selected' : ''}>Cronómetro</option><option value="120" ${gamesState.timerMode === '120' ? 'selected' : ''}>2 minutos</option><option value="180" ${gamesState.timerMode === '180' ? 'selected' : ''}>3 minutos</option><option value="300" ${gamesState.timerMode === '300' ? 'selected' : ''}>5 minutos</option><option value="off" ${gamesState.timerMode === 'off' ? 'selected' : ''}>Sin tiempo</option></select></label><strong class="games-timer-display">00:00</strong><button type="button" class="games-timer-pause" aria-pressed="false">Ⅱ Pausar</button><small class="games-timer-result" aria-live="polite"></small></div></div>
    <div class="games-board"><div class="games-game-card"><div class="games-game-heading"><div><span>${game.icon} Juego de vocabulario</span><h3>${game.title}</h3><p>${game.hint}</p></div><button type="button" class="secondary-btn games-new-round">Nuevo reto</button></div><div class="games-game-content"></div><p class="games-feedback" aria-live="polite"></p></div></div>
  `;
  app.querySelectorAll('[data-game-language]').forEach((button) => button.addEventListener('click', async () => {
    const nextLanguage = button.dataset.gameLanguage;
    if (nextLanguage === gamesState.language) return;
    gamesState.language = nextLanguage;
    gamesState.vocabulary = [];
    await loadGamesView();
  }));
  app.querySelectorAll('[data-game-id]').forEach((button) => button.addEventListener('click', () => {
    gamesState.gameId = button.dataset.gameId;
    gamesState.round += 1;
    renderGamesView();
  }));
  app.querySelectorAll('[data-game-difficulty]').forEach((button) => button.addEventListener('click', () => {
    if (button.dataset.gameDifficulty === gamesState.difficulty) return;
    gamesState.difficulty = button.dataset.gameDifficulty;
    gamesState.timerMode = getGamesDifficulty().timerDefault;
    gamesState.round += 1;
    renderGamesView();
  }));
  app.querySelector('.games-timer-mode')?.addEventListener('change', (event) => {
    gamesState.timerMode = event.target.value;
    setGamesFeedback('');
    renderSelectedGame();
  });
  app.querySelector('.games-timer-pause')?.addEventListener('click', () => {
    if (gamesState.timerFinished || gamesState.timerMode === 'off') return;
    gamesState.timerPaused = !gamesState.timerPaused;
    gamesState.timerAutoPaused = false;
    updateGamesTimerUi();
  });
  app.querySelector('.games-new-round')?.addEventListener('click', () => {
    gamesState.round += 1;
    app.querySelector('.games-round-value')?.replaceChildren(String(gamesState.round + 1));
    setGamesFeedback('');
    renderSelectedGame();
  });
  renderSelectedGame();
}

function setGamesFeedback(message, tone = '') {
  const feedback = document.querySelector('#gamesApp .games-feedback');
  if (!feedback) return;
  feedback.textContent = message;
  feedback.className = `games-feedback ${tone}`;
}

function getCurrentGamesTheme() {
  const topics = GAME_CROSSWORD_TOPICS[gamesState.language] || GAME_CROSSWORD_TOPICS.english;
  const topicIndex = ((gamesState.round % topics.length) + topics.length) % topics.length;
  const topic = topics[topicIndex];
  // learningPathState.bridgeLanguage is this student's actual native/bridge
  // language (set at sign-up / in preferences) - falling back to the old
  // spanish<->english guess only if that state isn't available yet, so a
  // French course studied via an English bridge (for example) gets English
  // clues instead of always assuming Spanish.
  const bridgeLanguage =
    learningPathState?.bridgeLanguage && learningPathState.bridgeLanguage !== gamesState.language
      ? learningPathState.bridgeLanguage
      : gamesState.language === 'spanish' ? 'english' : 'spanish';
  const bridgeTopic = (GAME_CROSSWORD_TOPICS[bridgeLanguage] || [])[topicIndex];
  const words = topic.entries.map(([term, clue], index) => ({
    term,
    translation: bridgeTopic?.entries?.[index]?.[0] || clue,
    clue
  }));
  return { topic, words, bridgeTopic };
}

function renderSelectedGame() {
  const content = document.querySelector('#gamesApp .games-game-content');
  if (!content) return;
  const { topic, words, bridgeTopic } = getCurrentGamesTheme();
  const difficulty = getGamesDifficulty();
  content.innerHTML = `<div class="games-theme-banner"><span>Tema de la ronda</span><strong>${escapeHtml(topic.title)}</strong><small>${difficulty.icon} ${difficulty.label} · ${difficulty.cefr} · ${difficulty.description}</small></div><div class="games-themed-stage"></div>`;
  const stage = content.querySelector('.games-themed-stage');
  resetGamesTimer();
  if (gamesState.gameId === 'word-search') return renderWordSearchGame(stage, words);
  if (gamesState.gameId === 'crossword') return renderCrosswordGame(stage, topic, bridgeTopic);
  if (gamesState.gameId === 'hangman') return renderHangmanGame(stage, words);
  renderMatchGame(stage, words);
}

function renderWordSearchGame(content, words) {
  const difficulty = getGamesDifficulty();
  const puzzle = makeWordSearch(words);
  const picked = new Set();
  const found = new Set();
  setGamesRoundProgress(0, puzzle.targets.length);
  const directionsNote = difficulty.wordSearchReversed
    ? `Encuentra ${puzzle.targets.length} palabras en horizontal, vertical, diagonal y también al revés.`
    : difficulty.wordSearchDiagonal
      ? `Encuentra ${puzzle.targets.length} palabras en horizontal, vertical o diagonal. No hay palabras al revés.`
      : `Encuentra ${puzzle.targets.length} palabras en horizontal o vertical. No hay diagonales ni palabras al revés.`;
  const bankLabel = difficulty.wordSearchMeaningClues ? 'Pistas en tu idioma' : 'Palabras que debes encontrar';
  const audioHint = difficulty.wordSearchMeaningClues ? '' : '<button type="button" class="secondary-btn games-speak-target">🔊 Pista de audio</button>';
  content.innerHTML = `<p class="games-search-directions">${directionsNote}</p><div class="games-word-search-layout"><div class="games-word-grid" style="--word-grid-columns:${puzzle.columns};--word-grid-rows:${puzzle.rows}" aria-label="Sopa de letras">${puzzle.letters.map((letter, index) => `<button type="button" class="games-letter-cell" data-letter-index="${index}" aria-label="Letra ${letter}">${letter}</button>`).join('')}</div><div class="games-word-bank"><strong>${bankLabel}</strong>${puzzle.targets.map((target, index) => `<span data-word-index="${index}">${escapeHtml(difficulty.wordSearchMeaningClues ? target.translation : target.term)}</span>`).join('')}</div></div><div class="games-action-row"><button type="button" class="secondary-btn games-clear-search">Limpiar selección</button>${audioHint}</div>`;
  const check = () => {
    const selected = [...picked].join(',');
    const targetIndex = puzzle.targets.findIndex((target) => target.positions.join(',') === selected);
    if (targetIndex < 0) return false;
    if (!found.has(targetIndex)) { found.add(targetIndex); recordGameSuccess(); setGamesFeedback(`¡Encontraste «${puzzle.targets[targetIndex].term}»!`, 'is-correct'); }
    puzzle.targets[targetIndex].positions.forEach((position) => {
      const cell = content.querySelector(`[data-letter-index="${position}"]`);
      cell?.classList.remove('is-selected');
      cell?.classList.add('is-picked');
    });
    content.querySelector(`[data-word-index="${targetIndex}"]`)?.classList.add('is-found');
    picked.clear();
    setGamesRoundProgress(found.size, puzzle.targets.length);
    if (found.size === puzzle.targets.length) {
      const timing = finishGamesTimer(true);
      setGamesFeedback(`¡Completaste la sopa de letras! ${timing}`, 'is-correct');
    }
    return true;
  };
  const grid = content.querySelector('.games-word-grid');
  let selecting = false;
  let activePointerId = null;
  let startIndex = -1;

  const clearCurrentSelection = () => {
    picked.clear();
    content.querySelectorAll('.games-letter-cell.is-selected').forEach((item) => item.classList.remove('is-selected'));
  };

  const straightPath = (fromIndex, toIndex) => {
    const fromRow = Math.floor(fromIndex / puzzle.columns);
    const fromColumn = fromIndex % puzzle.columns;
    const toRow = Math.floor(toIndex / puzzle.columns);
    const toColumn = toIndex % puzzle.columns;
    const rowDelta = toRow - fromRow;
    const columnDelta = toColumn - fromColumn;
    if (rowDelta !== 0 && columnDelta !== 0 && Math.abs(rowDelta) !== Math.abs(columnDelta)) return [];
    const length = Math.max(Math.abs(rowDelta), Math.abs(columnDelta));
    const rowStep = Math.sign(rowDelta);
    const columnStep = Math.sign(columnDelta);
    return Array.from({ length: length + 1 }, (_, offset) =>
      (fromRow + rowStep * offset) * puzzle.columns + fromColumn + columnStep * offset
    );
  };

  const paintPath = (endIndex) => {
    const path = straightPath(startIndex, endIndex);
    clearCurrentSelection();
    path.forEach((index) => {
      picked.add(index);
      content.querySelector(`[data-letter-index="${index}"]`)?.classList.add('is-selected');
    });
  };

  grid?.addEventListener('pointerdown', (event) => {
    const cell = event.target.closest('.games-letter-cell');
    if (!cell) return;
    event.preventDefault();
    selecting = true;
    activePointerId = event.pointerId;
    startIndex = Number(cell.dataset.letterIndex);
    grid.setPointerCapture?.(event.pointerId);
    grid.classList.add('is-selecting');
    paintPath(startIndex);
  });

  grid?.addEventListener('pointermove', (event) => {
    if (!selecting || event.pointerId !== activePointerId) return;
    event.preventDefault();
    const hovered = document.elementFromPoint(event.clientX, event.clientY)?.closest?.('.games-letter-cell');
    if (!hovered || !grid.contains(hovered)) return;
    paintPath(Number(hovered.dataset.letterIndex));
  });

  const finishSelection = (event) => {
    if (!selecting || event.pointerId !== activePointerId) return;
    selecting = false;
    activePointerId = null;
    grid?.classList.remove('is-selecting');
    if (!check()) {
      setGamesFeedback('Sigue intentando: desliza en línea recta hasta completar una palabra.');
      window.setTimeout(clearCurrentSelection, 280);
    }
  };

  grid?.addEventListener('pointerup', finishSelection);
  grid?.addEventListener('pointercancel', finishSelection);

  // Enter or Space still lets keyboard users choose one cell at a time.
  content.querySelectorAll('[data-letter-index]').forEach((button) => button.addEventListener('click', (event) => {
    if (event.detail !== 0) return;
    const index = Number(button.dataset.letterIndex);
    if (button.classList.contains('is-picked')) return;
    picked.has(index) ? picked.delete(index) : picked.add(index);
    button.classList.toggle('is-selected', picked.has(index));
    check();
  }));
  content.querySelector('.games-clear-search')?.addEventListener('click', () => { picked.clear(); content.querySelectorAll('.games-letter-cell.is-selected').forEach((item) => item.classList.remove('is-selected')); });
  content.querySelector('.games-speak-target')?.addEventListener('click', () => { const next = puzzle.targets.find((_, index) => !found.has(index)) || puzzle.targets[0]; speakText(next.term, { locale: getGamesLocale() }); });
}

function buildCrosswordPuzzle(topic, bridgeTopic) {
  const size = 25;
  const difficulty = getGamesDifficulty();
  // Clues are shown in the student's bridge/native language, not the target
  // language, the same way renderWordSearchGame/renderHangmanGame/
  // renderMatchGame already do via getCurrentGamesTheme()'s `words.translation`
  // - guessing a target-language answer from a target-language clue is a much
  // harder (and different) task than the crossword is meant to test. Themes
  // have the same entries in the same order across every language (see
  // GAME_CROSSWORD_TOPICS), so entries[i] and bridgeTopic.entries[i] describe
  // the same word - matched by index before the sort/slice below reorders
  // them, since after that the two arrays would no longer line up.
  const entries = topic.entries
    .map(([term, clue], index) => ({
      term,
      clue: difficulty.crosswordTargetClues
        ? clue
        : `${bridgeTopic?.entries?.[index]?.[1] || clue}${difficulty.crosswordFirstLetter ? ` · Empieza con ${normalizeGameText(term).charAt(0).toUpperCase()}.` : ''}`,
      answer: normalizeGameText(term).toUpperCase()
    }))
    .filter((item) => item.answer.length >= 3)
    .sort((a, b) => b.answer.length - a.answer.length)
    .slice(0, getGamesDifficulty().crosswordWords);
  const cells = new Map();
  const placed = [];
  const key = (row, column) => `${row}:${column}`;
  const canPlace = (entry, row, column, direction) => {
    const endRow = row + direction.row * (entry.answer.length - 1);
    const endColumn = column + direction.column * (entry.answer.length - 1);
    if (row < 1 || column < 1 || endRow >= size - 1 || endColumn >= size - 1 || endRow < 1 || endColumn < 1) return false;
    let intersections = 0;
    for (let index = 0; index < entry.answer.length; index += 1) {
      const currentRow = row + direction.row * index;
      const currentColumn = column + direction.column * index;
      const existing = cells.get(key(currentRow, currentColumn));
      if (existing && existing !== entry.answer[index]) return false;
      if (existing === entry.answer[index]) intersections += 1;
    }
    return !placed.length || intersections > 0;
  };
  const commit = (entry, row, column, direction) => {
    const positions = [];
    [...entry.answer].forEach((letter, index) => {
      const currentRow = row + direction.row * index;
      const currentColumn = column + direction.column * index;
      cells.set(key(currentRow, currentColumn), letter);
      positions.push({ row: currentRow, column: currentColumn });
    });
    placed.push({ ...entry, row, column, orientation: direction.row === 0 ? 'across' : 'down', positions });
  };

  if (entries[0]) commit(entries[0], 12, Math.max(2, Math.floor((size - entries[0].answer.length) / 2)), { row: 0, column: 1 });
  entries.slice(1).forEach((entry) => {
    let option = null;
    for (const anchor of placed) {
      const direction = anchor.orientation === 'across' ? { row: 1, column: 0 } : { row: 0, column: 1 };
      for (let entryIndex = 0; entryIndex < entry.answer.length && !option; entryIndex += 1) {
        for (let anchorIndex = 0; anchorIndex < anchor.answer.length && !option; anchorIndex += 1) {
          if (entry.answer[entryIndex] !== anchor.answer[anchorIndex]) continue;
          const intersection = anchor.positions[anchorIndex];
          const row = intersection.row - direction.row * entryIndex;
          const column = intersection.column - direction.column * entryIndex;
          if (canPlace(entry, row, column, direction)) option = { row, column, direction };
        }
      }
      if (option) break;
    }
    if (option) commit(entry, option.row, option.column, option.direction);
  });

  const numberByStart = new Map();
  [...placed]
    .sort((a, b) => a.row - b.row || a.column - b.column)
    .forEach((entry) => {
      const startKey = key(entry.row, entry.column);
      if (!numberByStart.has(startKey)) numberByStart.set(startKey, numberByStart.size + 1);
      entry.number = numberByStart.get(startKey);
    });
  const rows = placed.flatMap((entry) => entry.positions.map((position) => position.row));
  const columns = placed.flatMap((entry) => entry.positions.map((position) => position.column));
  const bounds = {
    minRow: Math.min(...rows), maxRow: Math.max(...rows),
    minColumn: Math.min(...columns), maxColumn: Math.max(...columns)
  };
  return { topic, cells, placed, numberByStart, bounds, key };
}

function renderCrosswordGame(content, topic, bridgeTopic) {
  if (!topic) ({ topic, bridgeTopic } = getCurrentGamesTheme());
  const puzzle = buildCrosswordPuzzle(topic, bridgeTopic);
  let completed = false;
  setGamesRoundProgress(0, puzzle.cells.size);
  const { minRow, maxRow, minColumn, maxColumn } = puzzle.bounds;
  const columnCount = maxColumn - minColumn + 1;
  const gridHtml = Array.from({ length: (maxRow - minRow + 1) * columnCount }, (_, flatIndex) => {
    const row = minRow + Math.floor(flatIndex / columnCount);
    const column = minColumn + (flatIndex % columnCount);
    const solution = puzzle.cells.get(puzzle.key(row, column));
    if (!solution) return '<span class="games-crossword-block" aria-hidden="true"></span>';
    const number = puzzle.numberByStart.get(puzzle.key(row, column));
    return `<label class="games-crossword-cell">${number ? `<span>${number}</span>` : ''}<input type="text" maxlength="1" autocomplete="off" data-crossword-row="${row}" data-crossword-column="${column}" data-crossword-solution="${solution}" aria-label="Casilla${number ? ` ${number}` : ''}"></label>`;
  }).join('');
  const cluesHtml = (orientation, heading) => `<section><h4>${heading}</h4><ol>${puzzle.placed.filter((entry) => entry.orientation === orientation).sort((a, b) => a.number - b.number).map((entry) => `<li value="${entry.number}">${escapeHtml(entry.clue)}</li>`).join('')}</ol></section>`;
  content.innerHTML = `<div class="games-crossword-layout"><div class="games-crossword-grid" style="--crossword-columns:${columnCount}" aria-label="Crucigrama: ${escapeHtml(topic.title)}">${gridHtml}</div><div class="games-crossword-clues">${cluesHtml('across', 'Horizontal')}${cluesHtml('down', 'Vertical')}</div></div><div class="games-action-row"><button type="button" class="primary-btn games-check-crossword">Comprobar</button><button type="button" class="secondary-btn games-clear-crossword">Borrar</button></div>`;
  const inputs = [...content.querySelectorAll('[data-crossword-solution]')];
  inputs.forEach((input, index) => input.addEventListener('input', () => {
    input.value = normalizeGameText(input.value).slice(-1).toUpperCase();
    input.classList.remove('is-correct', 'is-wrong');
    setGamesRoundProgress(inputs.filter((cell) => cell.value === cell.dataset.crosswordSolution).length, inputs.length);
    if (input.value && inputs[index + 1]) inputs[index + 1].focus();
  }));
  content.querySelector('.games-check-crossword')?.addEventListener('click', () => {
    const correct = inputs.filter((input) => {
      const isCorrect = input.value === input.dataset.crosswordSolution;
      input.classList.toggle('is-correct', isCorrect);
      input.classList.toggle('is-wrong', Boolean(input.value) && !isCorrect);
      return isCorrect;
    }).length;
    setGamesRoundProgress(correct, inputs.length);
    if (correct === inputs.length && !completed) {
      completed = true;
      recordGameSuccess();
      const timing = finishGamesTimer(true);
      setGamesFeedback(`¡Completaste «${topic.title}»! ${timing}`, 'is-correct');
      return;
    }
    setGamesFeedback(correct === inputs.length ? `¡Completaste «${topic.title}»!` : `${correct} de ${inputs.length} letras correctas.`, correct === inputs.length ? 'is-correct' : 'is-wrong');
  });
  content.querySelector('.games-clear-crossword')?.addEventListener('click', () => {
    inputs.forEach((input) => { input.value = ''; input.classList.remove('is-correct', 'is-wrong'); });
    setGamesRoundProgress(0, inputs.length);
    inputs[0]?.focus();
    setGamesFeedback('');
  });
}

function renderHangmanGame(content, words) {
  const difficulty = getGamesDifficulty();
  const wordPool = difficulty.hangmanLongWords
    ? getHangmanChallengeWords(gamesState.language, words)
    : words;
  const item = getGameRoundWords(wordPool, 1, 4)[0];
  const answer = normalizeGameText(item.term).toUpperCase();
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  const maximumMisses = difficulty.hangmanLives;
  const repeatedCount = answer.length - new Set(answer).size;
  const maskedMeaning = String(item.translation || '')
    .split(/(\s+|[-/])/)
    .map((part) => {
      if (!/[\p{L}\p{N}]/u.test(part)) return part;
      const characters = [...part];
      return characters.map((character, index) => (
        index === 0 || index === characters.length - 1 || index % 3 === 0 ? character : '_'
      )).join(' ');
    })
    .join('');
  let guesses = new Set(); let misses = 0; let finished = false;
  const hangmanParts = [
    '<circle cx="92" cy="48" r="16"/>',
    '<line x1="92" y1="64" x2="92" y2="112"/>',
    '<line x1="92" y1="78" x2="68" y2="94"/>',
    '<line x1="92" y1="78" x2="116" y2="94"/>',
    '<line x1="92" y1="112" x2="72" y2="142"/>',
    '<line x1="92" y1="112" x2="112" y2="142"/>'
  ];
  const draw = () => {
    const word = [...answer].map((letter) => guesses.has(letter) ? letter : '_').join(' ');
    const remaining = Math.max(0, maximumMisses - misses);
    const wrongLetters = [...guesses].filter((letter) => !answer.includes(letter));
    const revealedLetters = [...answer].filter((letter) => guesses.has(letter)).length;
    const structuralHint = `${answer.length} letras${misses >= Math.ceil(maximumMisses / 2) ? ` · ${repeatedCount ? 'contiene letras repetidas' : 'no contiene letras repetidas'}` : ''}`;
    const meaningHint = gamesState.difficulty === 'easy'
      ? String(item.translation || 'Observa la cantidad de letras.')
      : gamesState.difficulty === 'challenge'
        ? misses < 3
          ? 'Sin traducción inicial: deduce la palabra por el tema y su estructura.'
          : misses < 4 ? maskedMeaning : String(item.translation || maskedMeaning)
        : misses < 2
          ? 'La palabra pertenece al tema de esta ronda. Observa su cantidad de letras.'
          : misses < 4 ? maskedMeaning : String(item.translation || maskedMeaning);
    setGamesRoundProgress(revealedLetters, answer.length);
    const hintAction = difficulty.hangmanHintPenalty === null
      ? ''
      : `<button type="button" class="secondary-btn games-hangman-hint">Revelar una letra (${difficulty.hangmanHintPenalty ? '−1 intento' : 'ayuda gratis'})</button>`;
    content.innerHTML = `<div class="games-hangman"><div class="games-hangman-layout"><div class="games-hangman-scene"><svg viewBox="0 0 170 170" role="img" aria-label="Ahorcado con ${remaining} intentos restantes"><path class="games-hangman-gallows" d="M18 154H152M42 154V18H112V32"/>${hangmanParts.slice(0, Math.ceil((misses / maximumMisses) * hangmanParts.length)).join('')}</svg><div class="games-hangman-lives" aria-label="${remaining} vidas">${Array.from({ length: maximumMisses }, (_, index) => `<span class="${index < remaining ? 'is-live' : ''}">♥</span>`).join('')}</div></div><div class="games-hangman-play"><p class="games-hangman-help"><strong>Pista progresiva:</strong> ${escapeHtml(meaningHint)}<small>${structuralHint}</small></p><div class="games-hangman-word" aria-label="Palabra: ${word}">${word}</div><p class="games-hangman-used"><strong>Letras falladas:</strong> ${wrongLetters.length ? wrongLetters.join(', ') : 'ninguna'}</p><div class="games-hangman-keyboard" aria-label="Teclado de letras">${alphabet.map((letter) => `<button type="button" data-hangman-letter="${letter}" ${guesses.has(letter) || finished ? 'disabled' : ''}>${letter}</button>`).join('')}</div><div class="games-action-row">${finished ? '<button type="button" class="secondary-btn games-speak-hangman">🔊 Escuchar palabra</button>' : hintAction}</div></div></div></div>`;
    content.querySelectorAll('[data-hangman-letter]').forEach((button) => button.addEventListener('click', () => {
      if (finished) return;
      const letter = button.dataset.hangmanLetter;
      guesses.add(letter);
      if (answer.includes(letter)) setGamesFeedback('¡Esa letra está en la palabra!', 'is-correct');
      else { misses += 1; setGamesFeedback('Esa letra no aparece.', 'is-wrong'); }
      if ([...answer].every((char) => guesses.has(char))) {
        finished = true;
        recordGameSuccess();
        const timing = finishGamesTimer(true);
        setGamesFeedback(`¡Ganaste! ${item.term}. ${timing}`, 'is-correct');
      } else if (misses >= maximumMisses) {
        finished = true;
        const timing = finishGamesTimer(false);
        setGamesFeedback(`La palabra era «${item.term}». ${timing} Pulsa Nuevo reto.`, 'is-wrong');
      }
      draw();
    }));
    content.querySelector('.games-hangman-hint')?.addEventListener('click', () => {
      if (finished) return;
      const hiddenLetters = [...new Set(answer)].filter((letter) => !guesses.has(letter));
      const hiddenLetter = hiddenLetters[Math.floor(Math.random() * hiddenLetters.length)];
      if (!hiddenLetter) return;
      guesses.add(hiddenLetter);
      misses = Math.min(maximumMisses, misses + difficulty.hangmanHintPenalty);
      setGamesFeedback(difficulty.hangmanHintPenalty ? 'Pista utilizada: se descontó un intento.' : 'Pista gratuita utilizada.', difficulty.hangmanHintPenalty ? 'is-wrong' : '');
      if ([...answer].every((char) => guesses.has(char))) {
        finished = true;
        recordGameSuccess();
        const timing = finishGamesTimer(true);
        setGamesFeedback(`¡Completaste la palabra! ${item.term}. ${timing}`, 'is-correct');
      } else if (misses >= maximumMisses) {
        finished = true;
        const timing = finishGamesTimer(false);
        setGamesFeedback(`Sin intentos. La palabra era «${item.term}». ${timing}`, 'is-wrong');
      }
      draw();
    });
    content.querySelector('.games-speak-hangman')?.addEventListener('click', () => speakText(item.term, { locale: getGamesLocale() }));
  };
  draw();
}

function renderMatchGame(content, words) {
  const pairs = getGameRoundWords(words, getGamesDifficulty().matchPairs, 1);
  const cards = pairs.flatMap((item, id) => [{ id, text: item.term, kind: 'term' }, { id, text: item.translation, kind: 'meaning' }]);
  for (let index = cards.length - 1; index > 0; index -= 1) {
    const other = Math.floor(Math.random() * (index + 1));
    [cards[index], cards[other]] = [cards[other], cards[index]];
  }
  let selected = null; let locked = false; const matched = new Set();
  setGamesRoundProgress(0, pairs.length);
  content.innerHTML = `<p class="games-match-instruction">Memoriza y une ${pairs.length} palabras con su significado. Cada pareja contiene una palabra y una definición.</p><div class="games-match-grid">${cards.map((card, index) => `<button type="button" class="games-match-card" data-pair-id="${card.id}" data-card-kind="${card.kind}" data-card-index="${index}" aria-label="Tarjeta oculta"><span class="games-match-cover" aria-hidden="true">?</span><span class="games-match-value">${escapeHtml(card.text)}</span></button>`).join('')}</div>`;
  content.querySelectorAll('.games-match-card').forEach((button) => button.addEventListener('click', () => {
    if (locked || button.classList.contains('is-matched') || button === selected) return;
    button.classList.add('is-selected', 'is-revealed');
    button.setAttribute('aria-label', button.querySelector('.games-match-value')?.textContent || 'Tarjeta revelada');
    if (!selected) { selected = button; return; }
    const previous = selected;
    const matchedPair = previous.dataset.pairId === button.dataset.pairId && previous.dataset.cardKind !== button.dataset.cardKind;
    if (matchedPair) {
      previous.classList.remove('is-selected');
      button.classList.remove('is-selected');
      previous.classList.add('is-matched');
      button.classList.add('is-matched');
      matched.add(button.dataset.pairId);
      recordGameSuccess();
      setGamesRoundProgress(matched.size, pairs.length);
      if (matched.size === pairs.length) {
        const timing = finishGamesTimer(true);
        setGamesFeedback(`¡Encontraste las ${pairs.length} parejas! ${timing}`, 'is-correct');
      } else {
        setGamesFeedback(`${matched.size} de ${pairs.length} parejas.`, 'is-correct');
      }
    } else {
      locked = true;
      setGamesFeedback('No forman pareja. Memoriza su posición.', 'is-wrong');
      window.setTimeout(() => {
        previous.classList.remove('is-selected', 'is-revealed');
        button.classList.remove('is-selected', 'is-revealed');
        previous.setAttribute('aria-label', 'Tarjeta oculta');
        button.setAttribute('aria-label', 'Tarjeta oculta');
        locked = false;
      }, getGamesDifficulty().matchDelay);
    }
    selected = null;
  }));
}

async function loadGamesView() {
  const app = document.getElementById('gamesApp');
  if (!app) return;
  if (!gamesState.vocabulary.length) {
    app.innerHTML = '<p class="skill-graph-empty">Preparando juegos…</p>';
    try { gamesState.vocabulary = await loadGamesVocabulary(gamesState.language); } catch { gamesState.vocabulary = GAME_FALLBACK_VOCABULARY[gamesState.language].map(([term, translation]) => ({ term, translation })); }
  }
  gamesState.round += 1;
  renderGamesView();
}

const VIEW_SECTIONS = {
  // #premium (the Free/Premium plans section) lives at the end of the home
  // view now, not as its own nav destination - see handleHomeAction's
  // 'upgrade' case, which stays on/goes to 'home' and scrolls to it instead
  // of routing to a dedicated 'premium' view.
  home: ['.hero', '#premium'],
  learn: ['#learning-path'],
  progress: ['#progress', '#achievements'],
  security: ['#security'],
  goals: ['#goals'],
  tutor: ['#tutor'],
  translator: ['#translator'],
  tests: ['#tests'],
  music: ['#music'],
  games: ['#games'],
  downloads: ['#downloads'],
  about: ['#about'],
  verbs: ['#verbs'],
  listening: ['#listening'],
  speaking: ['#speaking'],
  reading: ['#reading'],
  writing: ['#writing'],
  grammar: ['#grammar'],
  vocabulary: ['#vocabulary'],
  'teacher-curriculum': ['#teacherCurriculum'],
  'reset-password': ['#resetPasswordSection'],
  'email-confirmed': ['#emailConfirmedSection']
};

// Focus target per view: the one heading a screen reader / keyboard user
// should land on after a hash change, per view. tabindex="-1" on these in
// index.html makes them programmatically focusable without joining the
// normal Tab order.
const VIEW_TITLE_SELECTORS = {
  home: '.hero-content h2',
  learn: '#learning-path h2',
  progress: '#progress h2',
  security: '#security h2',
  goals: '#goals h2',
  tutor: '#tutor h2',
  translator: '#translator h2',
  tests: '#tests h2',
  music: '#music h2',
  games: '#games h2',
  downloads: '#downloads h2',
  about: '#about h2',
  verbs: '#verbs h2',
  listening: '#listening .level-tab[data-tab="listening"]',
  speaking: '#speaking .level-tab[data-tab="speaking"]',
  reading: '#reading .level-tab[data-tab="reading"]',
  writing: '#writing .level-tab[data-tab="writing"]',
  grammar: '#grammar .level-tab[data-tab="grammar"]',
  vocabulary: '#vocabulary .level-tab[data-tab="vocabulary"]'
  ,
  'teacher-curriculum': '#teacherCurriculum h2'
};

function getViewFromHash() {
  // Only the first /-separated segment is the view id - 'learn' and skill
  // views can carry /<language>/<level>/<unitId>/<lessonSlug> after it (see
  // updateLearnHash/parseLearnHashState below), which used to make this
  // whole lookup miss (VIEW_SECTIONS['reading/french/A1/...'] is undefined)
  // and silently fall back to 'home'.
  const raw = window.location.hash.replace('#', '').split('/')[0];
  if (!raw) return 'home';
  // Keep old bookmarked #achievements links working after merging achievements
  // below Progress in a single member view.
  if (raw === 'achievements') return 'progress';
  if (raw.startsWith('language-') || targetLanguageMap[raw]) return 'learn';
  return VIEW_SECTIONS[raw] ? raw : 'home';
}

// Parses the optional /<language>/<level>/<unitId>/<lessonSlug> segments a
// 'learn' or skill-view hash can carry after the view id - e.g.
// #reading/french/A1/french-a1-unit-02/french-a1-unit-02-reading-01, written
// by updateLearnHash() below. Any/all of these can be absent (plain
// #reading, or the legacy #language-french marketing links keep working
// unchanged since they never match VIEW_SECTIONS as a view id here).
function parseLearnHashState() {
  const [, language, level, unitId, lessonSlug] = window.location.hash
    .replace('#', '')
    .split('/');
  return {
    language: language && languageDisplayNames[language] ? language : null,
    level: level || null,
    unitId: unitId || null,
    lessonSlug: lessonSlug || null
  };
}

// Keeps the hash in sync with language/level/unit/lesson for 'learn' and
// skill views, so reload, Back/Forward (via the popstate listener below),
// and sharing the link restore the exact same content instead of always
// landing on whichever unit/lesson happens to load first. Every other view
// keeps its plain #viewId hash untouched.
function updateLearnHash(viewOverride) {
  const view = viewOverride || getViewFromHash();
  if (view !== 'learn' && !SKILL_VIEWS.includes(view)) return;
  const parts = [view, learningPathState.language, learningPathState.level];
  if (learningPathState.unitId) {
    parts.push(learningPathState.unitId);
    if (learningPathState.activeSlug) parts.push(learningPathState.activeSlug);
  }
  const next = `#${parts.join('/')}`;
  if (window.location.hash !== next) history.pushState(null, '', next);
}

function showView(viewId) {
  let resolved = VIEW_SECTIONS[viewId] ? viewId : 'home';
  if (
    resolved === 'teacher-curriculum' &&
    !['teacher', 'ceo'].includes(authStatus.entitlements?.role)
  ) {
    resolved = 'home';
    if (window.location.hash === '#teacher-curriculum') history.replaceState(null, '', '#home');
  }
  setPricingExpanded(resolved === 'home');
  // A freshly loaded/restored Ruta is still unit-specific. Do not let it
  // inherit the full-library mode from a previous Explore visit.
  if (resolved === 'learn') learningPathState.skillEntryContext = 'route';

  // Any navigation away from the current view must release the mic and
  // drop any in-progress Speaking recording - a no-op when nothing is active.
  resetSpeakingRecorder();
  stopTutorDictation();
  stopTranslatorDictation();
  // Same rule for reading audio - no view change should leave a reading
  // playing in the background (also a no-op when nothing is attached).
  readingSpeechPlayer.teardown();

  const allViewElements = new Set();
  Object.values(VIEW_SECTIONS)
    .flat()
    .forEach((selector) =>
      document.querySelectorAll(selector).forEach((element) => allViewElements.add(element))
    );
  const activeViewElements = new Set();
  VIEW_SECTIONS[resolved].forEach((selector) =>
    document.querySelectorAll(selector).forEach((element) => activeViewElements.add(element))
  );
  allViewElements.forEach((element) => {
    const active = activeViewElements.has(element);
    element.classList.toggle('compact-hidden-section', !active);
    element.hidden = !active;
    element.setAttribute('aria-hidden', String(!active));
  });

  document.querySelectorAll('.nav-group a[href^="#"], .mobile-app-nav a[href^="#"], .mobile-header-tabs a[href^="#"]').forEach((link) => {
    const linkView = link.getAttribute('href')?.slice(1);
    const isLearningAppDestination =
      link.closest('.mobile-app-nav') &&
      linkView === 'learn' &&
      (resolved === 'learn' || SKILL_VIEWS.includes(resolved));
    const isActive = linkView === resolved || isLearningAppDestination;
    link.classList.toggle('active', isActive);
    if (isActive) {
      link.setAttribute('aria-current', 'page');
    } else {
      link.removeAttribute('aria-current');
    }
  });

  // Ruta/Reading/Listening/.../Vocabulary tab strip repeated at the top of
  // #learning-path and each of the 6 skill sections (index.html's
  // .level-tabs) - same active/aria-current toggling as the main nav above.
  document.querySelectorAll('.level-tab[href^="#"]').forEach((link) => {
    const linkView = link.dataset.tab === 'learn' ? 'learn' : link.dataset.tab;
    const isActive = linkView === resolved;
    link.classList.toggle('active', isActive);
    if (isActive) {
      link.setAttribute('aria-current', 'page');
    } else {
      link.removeAttribute('aria-current');
    }
  });
  updateLevelTabLabels();

  // Restores language/level/unit/lesson from the hash for 'learn' and skill
  // views (see updateLearnHash/parseLearnHashState) - only once lessons are
  // already loaded (cold-boot restore is handled separately by
  // renderSkillView's own loading guard and bootstrapLearningPath, since
  // learningPathState.lessons is still empty at that point).
  if ((resolved === 'learn' || SKILL_VIEWS.includes(resolved)) && learningPathState.lessons.length) {
    const hashState = parseLearnHashState();
    const languageChanged = hashState.language && hashState.language !== learningPathState.language;
    const levelChanged = hashState.level && hashState.level !== learningPathState.level;
    if (languageChanged || levelChanged) {
      const nextLanguage = hashState.language || learningPathState.language;
      const pathLanguageSelect = document.getElementById('pathLanguageSelect');
      if (pathLanguageSelect) pathLanguageSelect.value = nextLanguage;
      loadLearningPath({
        language: nextLanguage,
        level: hashState.level || learningPathState.level,
        restoreUnitId: hashState.unitId,
        restoreSlug: hashState.lessonSlug
      }).then(() => {
        if (SKILL_VIEWS.includes(resolved)) renderSkillView(resolved);
        updateLearnHash(resolved);
      });
    } else {
      let changed = false;
      if (
        hashState.lessonSlug &&
        hashState.lessonSlug !== learningPathState.activeSlug &&
        learningPathState.lessons.some((item) => item.slug === hashState.lessonSlug)
      ) {
        setActiveLesson(hashState.lessonSlug);
        changed = true;
      } else if (
        hashState.unitId &&
        hashState.unitId !== learningPathState.unitId &&
        learningPathState.units.some((unit) => unit.id === hashState.unitId)
      ) {
        selectUnit(hashState.unitId, { render: false });
        changed = true;
      }
      if (changed && resolved === 'learn') renderLearningPath();
    }
  }

  if (resolved === 'learn') {
    // Mobile's route drawer is user-driven ("Ver ruta"/"Volver a la ruta") -
    // entering #learn should land on the lesson panel (continue card or the
    // last-opened lesson), not force the drawer open every time.
    showLearnState('lesson');
    const langToken = getLanguageTabFromHash();
    if (langToken) setTargetLanguage(langToken);
  }
  if (resolved === 'tutor') {
    // Opening Tutor from the global navigation is a free consultation, not
    // an implicit continuation of the learner's last course route.
    updateAiTutorContext({ freeMode: true });
    checkTutorConnection();
    refreshTutorUsageCounter();
  }
  if (resolved === 'translator') syncTranslatorLanguagesFromState();
  if (resolved === 'tests') loadTestsView();
  if (resolved === 'music') initInfographicApp();
  if (resolved === 'games') loadGamesView();
  if (resolved === 'progress' || resolved === 'goals') loadDashboard();
  if (resolved === 'security') loadSecurityStatus();
  if (resolved === 'teacher-curriculum') loadTeacherCurriculumPanel();
  if (resolved === 'verbs') {
    const verbsDeck = document.getElementById('verbsCardDeck');
    verbsDeck?.setAttribute('aria-busy', 'true');
    ensureVerbsModules()
      .then(() => {
        verbsDeck?.removeAttribute('aria-busy');
        if (getViewFromHash() === 'verbs') window.renderVerbsView?.();
      })
      .catch((error) => {
        if (verbsDeck) {
          verbsDeck.removeAttribute('aria-busy');
          verbsDeck.innerHTML = `<p class="skill-graph-empty">${escapeHtml(error.message)}</p>`;
        }
      });
    renderUnitVerbContext();
  }
  if (SKILL_VIEWS.includes(resolved)) renderSkillView(resolved);
  syncMobileActivityFocus(resolved);

  // Normalizes the hash to reflect the state that actually just rendered -
  // covers plain nav-tab clicks (<a href="#reading">, no unit/lesson
  // suffix), which would otherwise "forget" the previously selected
  // unit/lesson in the address bar even though the content itself is still
  // correct. A no-op when nothing changed (updateLearnHash only pushes when
  // the computed hash differs from the current one).
  // Guarded on lessons.length: on a cold load this fires before
  // bootstrapLearningPath has fetched anything, with learningPathState still
  // at its english/A1 defaults - without this guard it would overwrite a
  // deep-linked hash (e.g. #reading/french/A1/...) with those defaults
  // before bootstrapLearningPath's own parseLearnHashState() ever reads it.
  if ((resolved === 'learn' || SKILL_VIEWS.includes(resolved)) && learningPathState.lessons.length) {
    updateLearnHash(resolved);
  }

  // The floating Tutor IA button is redundant on the dedicated Tutor view,
  // and the drawer shouldn't stay open across a navigation - it loses
  // whatever context it had anyway.
  document.getElementById('tutorFab')?.toggleAttribute('hidden', resolved === 'tutor');
  closeTutorDrawer();

  window.scrollTo({ top: 0, behavior: 'auto' });
  document.querySelector(VIEW_TITLE_SELECTORS[resolved])?.focus({ preventScroll: true });
}

window.addEventListener('hashchange', () => {
  showView(getViewFromHash());
  // A plain <a href="#premium"> (nav/footer) fires a real hashchange, unlike
  // handleHomeAction's 'upgrade' case above - #premium resolves to the home
  // view (it's no longer its own VIEW_SECTIONS entry), so land on it too.
  if (window.location.hash === '#premium') {
    window.setTimeout(() => {
      document.getElementById('premium')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
  }
});

// A route tab is not merely a view switch: it means "open this skill for the
// unit I am currently studying". Intercept the static anchors so they cannot
// leave the hash/tab on one activity while the mission strip still refers to
// another one.
document.addEventListener('click', (event) => {
  const tab = event.target.closest('.level-tab[data-tab]');
  if (!tab || tab.closest('[hidden]')) return;
  const skill = tab.dataset.tab;
  if (skill !== 'learn' && !SKILL_VIEWS.includes(skill)) return;
  event.preventDefault();
  openLearningRouteTab(skill);
});

// goTo() (handleHomeAction) navigates via history.pushState, which never
// fires 'hashchange' - only a real link click or address-bar edit does.
// Without this, the browser's Back/Forward buttons moved the URL bar but
// left the previous view rendered on screen.
window.addEventListener('popstate', () => showView(getViewFromHash()));

// Closing only via the explicit X (not a backdrop click) is intentional -
// a student mid-form who clicks slightly outside the card while filling in
// their name/email/password shouldn't lose everything they typed.
closeModal?.addEventListener('click', closeAuth);

function showHomeToast(message = '') {
  let toast = document.querySelector('.home-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.className = 'home-toast';
    toast.setAttribute('role', 'status');
    toast.setAttribute('aria-live', 'polite');
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('is-visible');
  window.clearTimeout(showHomeToast.timeoutId);
  showHomeToast.timeoutId = window.setTimeout(() => {
    toast.classList.remove('is-visible');
  }, 2600);
}

function showCelebration(message = '') {
  const celebration = document.createElement('div');
  celebration.className = 'celebration-toast';
  celebration.setAttribute('role', 'status');
  celebration.setAttribute('aria-live', 'assertive');
  celebration.textContent = message;
  document.body.appendChild(celebration);

  window.requestAnimationFrame(() => celebration.classList.add('is-visible'));
  window.setTimeout(() => {
    celebration.classList.remove('is-visible');
    window.setTimeout(() => celebration.remove(), 400);
  }, 3200);
}

function showUnitCompletionPanel({ unitId, xpReward = 30 } = {}) {
  const unit = learningPathState.units.find((item) => item.id === unitId);
  if (!unit) return;
  document.querySelector('.unit-completion-overlay')?.remove();
  const nextUnit = learningPathState.units.find((item) => item.order === unit.order + 1);
  const metrics = getUnitProgressMetrics(unitId);
  const copy = getUnitRouteCopy();
  const feedback = getUnitScoreFeedback(metrics.progressPercent);
  const overlay = document.createElement('div');
  overlay.className = 'unit-completion-overlay';
  overlay.innerHTML = `
    <section class="unit-completion-card" role="dialog" aria-modal="true" aria-labelledby="unitCompletionTitle">
      <button type="button" class="unit-completion-close" aria-label="Cerrar">×</button>
      <span class="unit-completion-icon" aria-hidden="true">🏁</span>
      <span class="unit-completion-kicker">${escapeHtml(copy.completed)}</span>
      <h2 id="unitCompletionTitle">${escapeHtml(unit.title)}</h2>
      <p>${escapeHtml(copy.summary)}</p>
      <div class="unit-completion-feedback" role="status">
        <strong>${escapeHtml(feedback.title)}</strong>
        <span>${escapeHtml(feedback.detail)}</span>
      </div>
      <div class="unit-completion-results">
        <span><strong>${metrics.completedCount}/${metrics.total}</strong> actividades</span>
        <span><strong>${metrics.progressPercent}/100</strong> score</span>
        <span><strong>+${escapeHtml(String(xpReward))}</strong> XP</span>
      </div>
      <div class="unit-completion-actions">
        <button type="button" class="secondary-btn unit-completion-retry">${escapeHtml(copy.retry)}</button>
        ${
          nextUnit
            ? `<button type="button" class="primary-btn unit-completion-next" data-unit-id="${escapeHtml(nextUnit.id)}">${escapeHtml(copy.nextLesson)} →</button>`
            : '<button type="button" class="primary-btn unit-completion-progress">Ver mi progreso</button>'
        }
      </div>
    </section>
  `;
  document.body.appendChild(overlay);
  overlay.querySelector('.unit-completion-close')?.focus();
  const close = () => overlay.remove();
  overlay.querySelector('.unit-completion-close')?.addEventListener('click', close);
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) close();
  });
  overlay.querySelector('.unit-completion-progress')?.addEventListener('click', () => {
    close();
    history.pushState(null, '', '#progress');
    showView('progress');
  });
  overlay.querySelector('.unit-completion-retry')?.addEventListener('click', () => {
    close();
    const activities = getUnitActivities(unit.id);
    const lesson =
      activities.find((item) => item.skill === 'reading' && !item.locked) ||
      activities.find((item) => !item.locked) ||
      activities[0];
    if (lesson) openUnitSequenceStep(lesson.skill, lesson.slug);
  });
  overlay.querySelector('.unit-completion-next')?.addEventListener('click', () => {
    const nextButton = overlay.querySelector('.unit-completion-next');
    const selected = learningPathState.units.find(
      (item) => String(item.id) === String(nextButton?.dataset.unitId)
    );
    if (!selected) {
      showHomeToast('No se pudo encontrar la siguiente unidad.');
      return;
    }
    close();
    selectUnit(selected.id, { render: false });
    const activities = getUnitActivities(selected.id);
    const lesson =
      activities.find((item) => item.skill === 'reading' && !item.locked) ||
      activities.find((item) => !item.locked) ||
      activities[0];
    if (lesson) openUnitSequenceStep(lesson.skill, lesson.slug);
    else {
      showView('learn');
      renderLearningPath();
    }
  });
}

window.AndergoGamification?.onEvent((type, payload) => {
  if (type === 'unit-complete') showUnitCompletionPanel(payload);
});

// Purely visual reaction to an activity being completed - called right
// after showHomeToast()'s "+X XP" toast at each completion call site
// (Speaking/Listening/lesson workspace). Never reads or writes
// scoring/progress data, only reacts to it once the server has already
// confirmed completion. Confetti node creation is skipped under
// prefers-reduced-motion since CSS alone can animate a burst away
// instantly but can't prevent the DOM churn of creating it.
function celebrateActivityCompletion() {
  const toast = document.querySelector('.home-toast');
  toast?.classList.add('xp-celebrate');
  window.setTimeout(() => toast?.classList.remove('xp-celebrate'), 700);

  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;

  const burst = document.createElement('div');
  burst.className = 'confetti-burst';
  const pieceCount = 18;
  for (let i = 0; i < pieceCount; i += 1) {
    const piece = document.createElement('span');
    piece.className = 'confetti-piece';
    piece.style.left = `${Math.random() * 100}vw`;
    piece.style.background = `var(--confetti-${(i % 4) + 1})`;
    piece.style.animationDelay = `${Math.random() * 200}ms`;
    burst.appendChild(piece);
  }
  document.body.appendChild(burst);
  window.setTimeout(() => burst.remove(), 1500);
}

window.celebratePerfectPractice = function celebratePerfectPractice() {
  window.playExerciseFeedbackSound?.('celebration');
  showCelebration('🎉 Resultado perfecto! Excelente trabajo.');
  celebrateActivityCompletion();
};

function handleHomeAction(action) {
  const goTo = (view, toast) => {
    if (window.location.hash !== `#${view}`) history.pushState(null, '', `#${view}`);
    showView(view);
    if (toast) showHomeToast(toast);
  };
  const openLanguageSelector = async () => {
    // The homepage language cards are the single canonical language chooser.
    // Keep selection in one place instead of duplicating the same decision at
    // the top of the learning route.
    goTo('home');
    window.requestAnimationFrame(() => {
      document.querySelector('.hero-language-tabs')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      document.querySelector('.hero-language-tabs button')?.focus({ preventScroll: true });
    });
  };
  const openLanguageRoute = async (language) => {
    if (language) {
      if (
        language === learningPathState.bridgeLanguage &&
        learningPathState.language !== learningPathState.bridgeLanguage
      ) {
        swapLearningPathLanguages();
      } else {
        setTargetLanguage(language);
      }
      void suggestNativeLanguage();
    }
    learningPathState.activeSlug = '';
    if (window.location.hash !== '#learn') history.pushState(null, '', '#learn');
    showView('learn');
    showLearnState('route');
    await loadLearningPath({
      language: learningPathState.language,
      level: learningPathState.level
    });
    learningPathState.activeSlug = '';
    renderLearningPath();
    window.requestAnimationFrame(() => {
      document.getElementById('learning-path')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      document.querySelector('#learning-path h2')?.focus({ preventScroll: true });
    });
  };

  switch (action) {
    case 'continue-lesson':
      goTo('learn', 'Ruta de lecciones abierta. Elige una lección y completa el reto.');
      break;
    case 'start-free':
      void openLanguageSelector();
      showHomeToast('Elige el idioma que deseas aprender.');
      break;
    case 'goals':
      goTo('goals', 'Elige o gestiona tu objetivo.');
      break;
    case 'view-progress':
      goTo('progress', 'Aquí puedes ver tu progreso y actividad reciente.');
      break;
    case 'upgrade':
      // #premium now lives at the end of the home view (see VIEW_SECTIONS)
      // instead of being its own destination - go home, then scroll to it,
      // same pattern as 'explore-languages' below.
      goTo('home');
      setPricingExpanded(true);
      window.setTimeout(() => {
        document.getElementById('premium')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }, 50);
      showHomeToast(`Plan premium único: USD ${premiumPriceUsd}.`);
      break;
    case 'view-plans': {
      const details = document.querySelector('.pricing-details');
      const expand = Boolean(details?.hidden);
      setPricingExpanded(expand);
      if (expand) {
        window.setTimeout(() => {
          details?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 50);
      }
      break;
    }
    case 'ai-tutor':
      goTo('tutor', 'Tutor IA abierto. Practica listening, speaking o writing.');
      break;
    case 'explore-languages':
      void openLanguageSelector();
      showHomeToast('Elige un idioma para ver su ruta completa.');
      break;
    case 'explore-english':
      void openLanguageRoute('english');
      showHomeToast('English seleccionado. Explora su ruta y elige tu nivel.');
      break;
    case 'explore-frances':
      void openLanguageRoute('french');
      showHomeToast('Français seleccionado. Explora su ruta y elige tu nivel.');
      break;
    case 'explore-espanol':
      void openLanguageRoute('spanish');
      showHomeToast('Español seleccionado. Explora su ruta y elige tu nivel.');
      break;
    default:
      break;
  }
}

function enableHomepageActions() {
  document.querySelectorAll('.paddle-checkout-btn').forEach((button) => {
    button.addEventListener('click', () => {
      openPremiumPayment(button.dataset.billingCycle || 'monthly', button);
    });
  });

  document.querySelectorAll('[data-paddle-action]').forEach((button) => {
    button.addEventListener('click', () => {
      if (button.dataset.paddleAction === 'manage') {
        openPaddleCustomerPortal(button);
      } else if (button.dataset.paddleAction === 'pause') {
        pausePaddleSubscription(button);
      }
    });
  });

  document.querySelectorAll('[data-home-action]').forEach((element) => {
    element.addEventListener('click', (event) => {
      const action = element.dataset.homeAction;
      if (action) {
        event.preventDefault();
        handleHomeAction(action);
      }
    });
  });

  document.querySelectorAll('.skill-competency-card').forEach((card) => {
    card.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        card.click();
      }
    });
  });

  document.addEventListener('click', async (event) => {
    // Delegated (rather than a one-time listener on a single element) because
    // renderLessonWorkspace() now fully replaces #lessonWorkspace's innerHTML
    // when it switches between the "continue" card and full lesson detail,
    // which would otherwise orphan a listener bound to the old button node.
    if (event.target.closest('.lesson-complete-btn')) {
      completeActiveLesson();
      return;
    }

    const dictateBtn = event.target.closest('.tutor-dictate-btn');
    if (dictateBtn) {
      const target = dictateBtn.dataset.dictateTarget;
      // Dictation only fills the text box. The learner reviews it and sends
      // it explicitly, preventing accidental Tutor requests and token use.
      startTutorDictation(target);
      return;
    }
    const dictateStopBtn = event.target.closest('.tutor-dictate-stop-btn');
    if (dictateStopBtn) {
      stopTutorDictation();
      return;
    }

    if (event.target.closest('.translator-dictate-btn')) {
      startTranslatorDictation();
      return;
    }
    if (event.target.closest('.translator-dictate-stop-btn')) {
      stopTranslatorDictation();
      return;
    }

    if (event.target.closest('[data-action="open-forgot-password"]')) {
      setAuthMessage('');
      resetForgotPasswordForm();
      openModal('forgotPassword');
      return;
    }
    if (event.target.closest('[data-action="back-to-login"]')) {
      setAuthMessage('');
      resetForgotPasswordForm();
      clearPendingMfa();
      openModal('login');
      return;
    }
    if (event.target.closest('[data-action="dismiss-username-onboarding"]')) {
      closeUsernameOnboarding();
      // Session-only, not a source of truth for "has a username" (that's
      // always profiles.username_normalized/username) - just stops this
      // same tab from reopening the modal on every nav change for the rest
      // of the session. A brand new session (new login) re-evaluates fresh.
      sessionStorage.setItem(USERNAME_ONBOARDING_DISMISSED_KEY, 'true');
      return;
    }

    // A locked lesson's "Desbloquear" button (see renderLessonWorkspace's
    // premium-lock-box) opens the same paywall modal used for usage-limit
    // lockouts instead of navigating away to the plans section - the
    // student is already looking at exactly what they'd unlock.
    if (event.target.closest('[data-action="open-lesson-paywall"]')) {
      openPaywallModal({
        title: 'Esta lección es Premium.',
        message: `Desbloquea esta lección y toda la ruta por USD ${premiumPriceUsd}.`
      });
      return;
    }

    const upgradeButton = event.target.closest('.upgrade-btn');
    if (upgradeButton) {
      handleHomeAction('upgrade');
      if (!authStatus.session?.access_token) {
        openModal('signup', {
          message: `Crea tu cuenta para desbloquear la ruta premium por USD ${premiumPriceUsd}.`
        });
      }
      return;
    }

    const skillCompetencyCard = event.target.closest('.skill-competency-card');
    if (skillCompetencyCard) {
      const skill = skillCompetencyCard.dataset.skill;
      if (!SKILL_VIEWS.includes(skill)) return;
      if (hasUnits() && learningPathState.unitId) {
        learningPathState.skillEntryContext = 'route';
        const unitActivity = getSkillActivities(skill).find(
          (item) => item.unitId === learningPathState.unitId
        );
        if (unitActivity) setActiveLesson(unitActivity.slug);
      } else {
        learningPathState.skillEntryContext = 'explore';
        learningPathState.activeSlug = '';
      }
      if (window.location.hash !== `#${skill}`) history.pushState(null, '', `#${skill}`);
      showView(skill);
      return;
    }

    const suggestion = event.target.closest('.predictive-suggestion');
    if (suggestion) {
      const group = suggestion.closest('.predictive-suggestions');
      group
        ?.querySelectorAll('.predictive-suggestion')
        .forEach((item) => item.classList.remove('selected'));
      suggestion.classList.add('selected');
      const tutorPrompt = document.getElementById('aiTutorPrompt');
      if (tutorPrompt && suggestion.closest('#tutor')) {
        tutorPrompt.value = suggestion.textContent.trim();
        tutorPrompt.focus();
      }
      showHomeToast(`Seleccionado: ${suggestion.textContent.trim()}`);
      const skillPanel = suggestion.closest('.skill-panel');
      window.AndergoGamification?.recordSkillTouched(
        skillPanel?.dataset.skill,
        learningPathState.language
      );
      return;
    }

    const mcqOption = event.target.closest('.mcq-option');
    if (mcqOption) {
      const questionItem = mcqOption.closest('.mcq-question');
      const slug = questionItem?.dataset.lessonSlug;
      if (
        !questionItem ||
        questionItem.classList.contains('answered') ||
        mcqOption.disabled ||
        !slug
      )
        return;

      const exerciseIndex = Number(questionItem.dataset.exerciseIndex);
      const exerciseId = questionItem.dataset.exerciseId || '';
      const chosenKey = mcqOption.dataset.optionKey;
      const feedback = questionItem.querySelector('.mcq-feedback');
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);
      const frenchFeedback = isFrenchExerciseFeedbackInTargetLanguage(lesson?.level);

      questionItem.classList.add('is-checking');
      questionItem.querySelectorAll('.mcq-option').forEach((option) => {
        option.disabled = true;
        option.setAttribute('aria-pressed', option === mcqOption ? 'true' : 'false');
      });
      if (feedback) {
        feedback.textContent = frenchFeedback
          ? 'Vérification de votre réponse…'
          : 'Comprobando tu respuesta…';
      }

      try {
        const payload = exerciseId
          ? { exerciseId, selectedOptionId: chosenKey }
          : { index: exerciseIndex, selectedOption: Number(chosenKey) };
        const response = await authFetch(`${backendBaseUrl}/api/lessons/${slug}/check-answer`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) {
          throw new Error(
            response.status === 401
              ? getExerciseAuthMessage()
              : data.error ||
                (frenchFeedback
                  ? 'Impossible de vérifier la réponse.'
                  : 'No se pudo verificar la respuesta.')
          );
        }

        learningPathState.exerciseResults[slug] = learningPathState.exerciseResults[slug] || {};
        learningPathState.exerciseResults[slug][exerciseIndex] = {
          selectedOption: chosenKey,
          correct: Boolean(data.correct)
        };

        if (data.correct) {
          window.AndergoGamification?.recordCorrectAnswer();
          window.AndergoGamification?.recordSkillTouched(
            questionItem.dataset.skill,
            questionItem.dataset.language || learningPathState.language
          );
        }
        window.playExerciseFeedbackSound?.(Boolean(data.correct));
      } catch (error) {
        questionItem.classList.remove('is-checking');
        if (feedback) {
          feedback.textContent =
            error.message ||
            (frenchFeedback
              ? 'Impossible de vérifier la réponse.'
              : 'No se pudo verificar la respuesta.');
        }
        questionItem.querySelectorAll('.mcq-option').forEach((option) => {
          option.disabled = false;
          option.setAttribute('aria-pressed', 'false');
        });
        return;
      }

      // Re-render whichever dedicated skill view is actually on screen
      // (Reading/Grammar/Listening each keep their own progress bar) rather
      // than always refreshing the legacy #lessonWorkspace, which otherwise
      // goes stale until the student navigates away and back.
      const currentView = getViewFromHash();
      if (SKILL_VIEWS.includes(currentView)) {
        renderSkillView(currentView);
      } else {
        renderLessonWorkspace();
      }
      return;
    }

    const readingCompCountBtn = event.target.closest('.reading-comp-count-btn');
    if (readingCompCountBtn) {
      const slug = readingCompCountBtn.dataset.lessonSlug;
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);
      const count = Number(readingCompCountBtn.dataset.questionCount);
      const entries = (lesson?.exercises || [])
        .map((item, exerciseIndex) => ({ item, exerciseIndex }))
        .filter(({ item }) => item.type === 'mcq' && !isTrueFalseExercise(item));
      const runtime = slug ? getReadingComprehensionRuntime(slug) : null;
      const { choices } = lesson && runtime
        ? getReadingQuestionCountConfig(lesson, entries, runtime)
        : { choices: [] };
      if (!lesson || !choices.includes(count) || runtime?.grading) return;
      resetReadingComprehensionRuntime(slug, count);
      if (SKILL_VIEWS.includes(getViewFromHash())) {
        renderSkillView(getViewFromHash());
      } else {
        renderLessonWorkspace();
      }
      return;
    }

    // Reading comprehension quiz (see renderReadingComprehensionQuiz above):
    // every selection is checked immediately, while "Evaluar" remains the
    // final score/summary action after all items have individual feedback.
    const readingQuestionNav = event.target.closest(
      '.reading-comp-nav-btn, .reading-comp-step'
    );
    if (readingQuestionNav) {
      if (readingQuestionNav.disabled) return;
      const slug = readingQuestionNav.dataset.lessonSlug;
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);
      if (!lesson) return;
      const runtime = getReadingComprehensionRuntime(slug);
      const entries = getVisibleReadingComprehensionEntries(
        lesson,
        (lesson.exercises || [])
          .map((item, exerciseIndex) => ({ item, exerciseIndex }))
          .filter(({ item }) => item.type === 'mcq' && !isTrueFalseExercise(item))
      );
      const directIndex = Number(readingQuestionNav.dataset.readingQuestionIndex);
      const direction = readingQuestionNav.dataset.readingDirection;
      const nextIndex = Number.isInteger(directIndex)
        ? directIndex
        : runtime.currentIndex + (direction === 'prev' ? -1 : 1);
      runtime.currentIndex = Math.max(0, Math.min(entries.length - 1, nextIndex));
      if (SKILL_VIEWS.includes(getViewFromHash())) renderSkillView(getViewFromHash());
      else renderLessonWorkspace();
      return;
    }

    const readingCompOption = event.target.closest('.reading-comp-option');
    if (readingCompOption) {
      if (readingCompOption.disabled) return;
      const questionItem = readingCompOption.closest('.reading-comp-question');
      const slug = questionItem?.dataset.lessonSlug;
      if (!questionItem || !slug) return;

      const runtime = getReadingComprehensionRuntime(slug);
      if (runtime.graded || runtime.grading) return;

      const exerciseIndex = Number(questionItem.dataset.exerciseIndex);
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);
      const exercise = lesson?.exercises?.[exerciseIndex];
      if (!lesson || !exercise) return;

      runtime.selections[exerciseIndex] = readingCompOption.dataset.optionKey;
      runtime.error = '';

      if (SKILL_VIEWS.includes(getViewFromHash())) {
        renderSkillView(getViewFromHash());
      } else {
        renderLessonWorkspace();
      }
      return;
    }

    // "Calificar": grades every comprehension question at once against the
    // real (server-side-only) answer key, then shows the 0-100 score.
    const readingCompSubmitBtn = event.target.closest('.reading-comp-submit-btn');
    if (readingCompSubmitBtn) {
      if (readingCompSubmitBtn.disabled) return;
      const slug = readingCompSubmitBtn.dataset.lessonSlug;
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);
      if (!lesson) return;

      const runtime = getReadingComprehensionRuntime(slug);
      const comprehensionEntries = (lesson.exercises || [])
        .map((item, exerciseIndex) => ({ item, exerciseIndex }))
        .filter(({ item }) => item.type === 'mcq' && !isTrueFalseExercise(item));
      const visibleEntries = getVisibleReadingComprehensionEntries(lesson, comprehensionEntries);
      const unanswered = visibleEntries.some(
        ({ exerciseIndex }) => runtime.selections[exerciseIndex] == null
      );
      if (unanswered || runtime.grading) return;

      runtime.grading = true;
      runtime.error = '';
      try {
        const gradedResults = await Promise.all(
          visibleEntries.map(async ({ item, exerciseIndex }) => {
            const selected = runtime.selections[exerciseIndex];
            const payload = item.id
              ? { exerciseId: item.id, selectedOptionId: selected }
              : { index: exerciseIndex, selectedOption: Number(selected) };
            const response = await authFetch(`${backendBaseUrl}/api/lessons/${slug}/check-answer`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(
                response.status === 401
                  ? getExerciseAuthMessage()
                  : data.error || 'No se pudo calificar. Intenta de nuevo.'
              );
            }
            const correctKey = data.correctOption ?? data.correctOptionId ?? null;
            const correctOptionIndex = (item.options || []).findIndex(
              (option, optionIndex) =>
                String(optionKey(option, optionIndex)) === String(correctKey)
            );
            return {
              exerciseIndex,
              correct: Boolean(data.correct),
              correctOption: correctKey,
              correctLabel: correctOptionIndex >= 0
                ? `${String.fromCharCode(65 + correctOptionIndex)}. ${optionLabel(item.options[correctOptionIndex])}`
                : '',
              selectedOption: selected
            };
          })
        );
        gradedResults.forEach((result) => {
          runtime.results[result.exerciseIndex] = result;
          learningPathState.exerciseResults[slug] = learningPathState.exerciseResults[slug] || {};
          learningPathState.exerciseResults[slug][result.exerciseIndex] = {
            selectedOption: result.selectedOption,
            correct: result.correct
          };
        });
        const correctCount = gradedResults.filter((result) => result.correct).length;
        if (correctCount > 0) {
          window.AndergoGamification?.recordSkillTouched('reading', learningPathState.language);
        }
        for (let index = 0; index < correctCount; index += 1) {
          window.AndergoGamification?.recordCorrectAnswer();
        }
      } catch (error) {
        runtime.error = error.message || 'No se pudo calificar. Intenta de nuevo.';
        runtime.grading = false;
        if (SKILL_VIEWS.includes(getViewFromHash())) renderSkillView(getViewFromHash());
        else renderLessonWorkspace();
        return;
      }

      runtime.graded = true;
      if (authStatus.session?.access_token) {
        try {
          const answers = visibleEntries.map(({ item, exerciseIndex }) => ({
            exerciseId: item.id,
            index: exerciseIndex,
            selectedOptionId: runtime.selections[exerciseIndex],
            selectedOption: runtime.selections[exerciseIndex]
          }));
          const response = await fetch(`${backendBaseUrl}/api/lessons/${slug}/complete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders() },
            body: JSON.stringify({
              answers,
              assessmentScope: 'reading_comprehension',
              assessmentExerciseIds: visibleEntries.map(({ item }) => item.id).filter(Boolean)
            })
          });
          const data = await response.json().catch(() => ({}));
          if (!response.ok) throw new Error(data.error || 'No se pudo guardar la evaluación.');
          lesson.completed = true;
          if (data.bestScore != null) lesson.bestScore = data.bestScore;
          runtime.serverResult = data;
          updateProgressDisplay(data, true);
          renderSkillCards();
          renderLearningPath();
          loadDashboard();
          window.AndergoGamification?.recordLessonCompletion({
            slug: lesson.slug,
            language: learningPathState.language,
            ...getLessonGamificationContext(lesson),
            score: data.score,
            xpReward: lesson.xpReward || 20
          });
          window.AndergoGamification?.syncFromServer(data);
          if (data.newBadges?.length)
            data.newBadges.forEach((badge) => showCelebration(`🏅 ¡Insignia desbloqueada! ${badge.label}`));
          showHomeToast(`Evaluación completada. +${data.earnedXp || lesson.xpReward || 20} XP`);
        } catch (error) {
          runtime.error = error.message || 'No se pudo guardar la evaluación.';
        } finally {
          runtime.grading = false;
        }
      }
      const summaryView = getViewFromHash();
      if (SKILL_VIEWS.includes(summaryView)) {
        renderSkillView(summaryView);
      } else {
        renderLessonWorkspace();
      }
      return;

      /*
       * Legacy batch-grading fallback retained below for reference while
       * older cached clients age out. New clients grade each item on click.
       */
      runtime.grading = true;
      runtime.error = '';
      readingCompSubmitBtn.disabled = true;
      readingCompSubmitBtn.textContent = 'Calificando…';

      try {
        const gradedResults = await Promise.all(
          comprehensionEntries.map(async ({ item, exerciseIndex }) => {
            const selected = runtime.selections[exerciseIndex];
            const payload = item.id
              ? { exerciseId: item.id, selectedOptionId: selected }
              : { index: exerciseIndex, selectedOption: Number(selected) };
            const response = await authFetch(`${backendBaseUrl}/api/lessons/${slug}/check-answer`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify(payload)
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(
                response.status === 401
                  ? getExerciseAuthMessage()
                  : data.error || 'No se pudo calificar. Intenta de nuevo.'
              );
            }

            // Only the key of the correct option comes back from the server
            // (never the answer itself ahead of time) - the option's own
            // text is already public in the client bundle, so this just
            // looks up the matching option locally to build a human label.
            const correctKey = data.correctOption ?? data.correctOptionId ?? null;
            const correctOptionIndex = (item.options || []).findIndex(
              (option, optionIndex) => String(optionKey(option, optionIndex)) === String(correctKey)
            );
            const correctLabel =
              correctOptionIndex >= 0
                ? `${String.fromCharCode(65 + correctOptionIndex)}. ${optionLabel(item.options[correctOptionIndex])}`
                : '';

            return {
              exerciseIndex,
              correct: Boolean(data.correct),
              correctOption: correctKey,
              correctLabel,
              selectedOption: selected
            };
          })
        );

        gradedResults.forEach((result) => {
          runtime.results[result.exerciseIndex] = result;
          learningPathState.exerciseResults[slug] = learningPathState.exerciseResults[slug] || {};
          learningPathState.exerciseResults[slug][result.exerciseIndex] = {
            selectedOption: result.selectedOption,
            correct: result.correct
          };
        });
        runtime.graded = true;
        runtime.grading = false;

        const correctCount = gradedResults.filter((r) => r.correct).length;
        if (correctCount > 0) {
          window.AndergoGamification?.recordSkillTouched('reading', learningPathState.language);
        }
        for (let i = 0; i < correctCount; i += 1) window.AndergoGamification?.recordCorrectAnswer();
      } catch (error) {
        runtime.grading = false;
        runtime.error = error.message || 'No se pudo calificar. Intenta de nuevo.';
      }

      const currentView = getViewFromHash();
      if (SKILL_VIEWS.includes(currentView)) {
        renderSkillView(currentView);
      } else {
        renderLessonWorkspace();
      }
      return;
    }

    const readingCompSignupBtn = event.target.closest('.reading-comp-signup-btn');
    if (readingCompSignupBtn) {
      openModal('signup', {
        message: 'Crea tu cuenta gratis para guardar tu nota, XP y logros.'
      });
      return;
    }

    // "Intentar de nuevo": clears selections/results and returns the score
    // to zero without touching the questions themselves or re-fetching the
    // reading (see resetReadingComprehensionRuntime above).
    const readingCompRetryBtn = event.target.closest('.reading-comp-retry-btn');
    if (readingCompRetryBtn) {
      const slug = readingCompRetryBtn.dataset.lessonSlug;
      if (!slug) return;
      const lesson = learningPathState.lessons.find((item) => item.slug === slug);

      resetReadingComprehensionRuntime(slug);
      if (lesson && learningPathState.exerciseResults[slug]) {
        (lesson.exercises || []).forEach((item, exerciseIndex) => {
          if (item.type === 'mcq' && !isTrueFalseExercise(item)) {
            delete learningPathState.exerciseResults[slug][exerciseIndex];
          }
        });
      }

      const currentView = getViewFromHash();
      if (SKILL_VIEWS.includes(currentView)) {
        renderSkillView(currentView);
      } else {
        renderLessonWorkspace();
      }
      return;
    }

    // Scored Grammar test (see renderGrammarTestView and friends above).
    // Every handler below resolves the active lesson the same way the
    // Listening "regenerate" handler above does: via the enclosing
    // .skill-view-section's data-active-lesson-slug, not a slug stashed on
    // the clicked element itself.
    function getGrammarTestContext(target) {
      const skillSection = target.closest('.skill-view-section');
      const lesson = learningPathState.lessons.find(
        (item) => item.slug === skillSection?.dataset.activeLessonSlug
      );
      const content = skillSection?.querySelector('.skill-view-content');
      if (!lesson?.extra?.grammarTest?.questions?.length || !content) return null;
      return { lesson, content, test: lesson.extra.grammarTest, runtime: getGrammarTestRuntime(lesson) };
    }

    const grammarTestStartBtn = event.target.closest('.grammar-test-start-btn');
    if (grammarTestStartBtn) {
      const ctx = getGrammarTestContext(grammarTestStartBtn);
      if (!ctx) return;
      ctx.runtime.phase = 'question';
      ctx.runtime.currentIndex = 0;
      renderGrammarTestView(ctx.content, ctx.lesson);
      return;
    }

    const grammarTestOption = event.target.closest('.grammar-test-option');
    if (grammarTestOption) {
      if (grammarTestOption.disabled) return;
      const optionsWrap = grammarTestOption.closest('.grammar-test-options');
      optionsWrap?.querySelectorAll('.grammar-test-option').forEach((btn) => {
        btn.classList.remove('is-selected');
        btn.setAttribute('aria-pressed', 'false');
      });
      grammarTestOption.classList.add('is-selected');
      grammarTestOption.setAttribute('aria-pressed', 'true');
      const ctx = getGrammarTestContext(grammarTestOption);
      const questionId = grammarTestOption.closest('.grammar-test-question-item')?.dataset.questionId;
      if (ctx && questionId) {
        ctx.runtime.answers[questionId] = grammarTestOption.dataset.optionId;
        const answered = ctx.test.questions.filter((question) => ctx.runtime.answers[question.id] != null).length;
        const total = ctx.test.questions.length;
        const progress = total ? Math.round((answered / total) * 100) : 0;
        const counter = ctx.content.querySelector('.grammar-test-counter');
        const progressBar = ctx.content.querySelector('.grammar-test-progress-bar div');
        const warning = ctx.content.querySelector('.grammar-test-review-warning');
        const submit = ctx.content.querySelector('.grammar-test-submit-btn');
        if (counter) {
          counter.textContent = isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
            ? `${answered} sur ${total} réponses`
            : `${answered} de ${total} respuestas`;
        }
        if (progressBar) progressBar.style.width = `${progress}%`;
        if (warning) warning.hidden = answered === total;
        if (submit) submit.setAttribute('aria-disabled', String(answered !== total));
        updateGrammarChallengeProgress(
          ctx.content,
          ctx.test,
          ctx.runtime,
          isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
        );
        try {
          const response = await authFetch(
            `${backendBaseUrl}/api/lessons/${ctx.lesson.slug}/check-question`,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                questionId,
                answer: grammarTestOption.dataset.optionId
              })
            }
          );
          const data = await response.json().catch(() => ({}));
          if (!response.ok) {
            throw new Error(
              data.error ||
                (isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
                  ? 'Impossible de vérifier la réponse.'
                  : 'No se pudo comprobar la respuesta.')
            );
          }
          ctx.runtime.questionResults ||= {};
          ctx.runtime.questionResults[questionId] = { correct: Boolean(data.correct) };
          renderGrammarTestView(ctx.content, ctx.lesson);
          // The browser paints the red/green state and starts its sound in
          // the same animation frame, so neither feedback channel leads the
          // other after the asynchronous server check.
          window.requestAnimationFrame(() =>
            window.playExerciseFeedbackSound?.(Boolean(data.correct))
          );
        } catch (error) {
          showHomeToast(
            error.message ||
              (isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
                ? 'Impossible de vérifier la réponse.'
                : 'No se pudo comprobar la respuesta.')
          );
        }
      }
      const listeningCtx = getListeningComprehensionContext(grammarTestOption);
      const listeningQuestion = grammarTestOption.closest('.listening-comp-question-item');
      const listeningQuestionId = listeningQuestion?.dataset.questionId;
      if (listeningCtx && listeningQuestionId) {
        listeningCtx.runtime.answers[listeningQuestionId] = grammarTestOption.dataset.optionId;
        listeningQuestion.classList.add('is-answered');
        const answered = listeningCtx.bank.questions.filter((question) =>
          isGrammarTestQuestionAnswered(listeningCtx.runtime, question)
        ).length;
        const total = listeningCtx.bank.questions.length;
        const progress = total ? Math.round((answered / total) * 100) : 0;
        const counter = listeningCtx.panel.querySelector('.grammar-test-counter');
        const progressBar = listeningCtx.panel.querySelector('.grammar-test-progress-bar div');
        const warning = listeningCtx.panel.querySelector('.grammar-test-review-warning');
        const submit = listeningCtx.panel.querySelector('.listening-comp-submit-btn');
        if (counter) counter.textContent = `${answered} ${listeningUiText('de', 'sur')} ${total}`;
        if (progressBar) progressBar.style.width = `${progress}%`;
        if (warning) warning.hidden = answered === total;
        if (submit) submit.disabled = answered !== total;
      }
      return;
    }

    const grammarTestPrevBtn = event.target.closest('.grammar-test-prev-btn');
    if (grammarTestPrevBtn) {
      const ctx = getGrammarTestContext(grammarTestPrevBtn);
      if (!ctx) return;
      collectGrammarTestAnswer(ctx.content, ctx.test, ctx.runtime);
      ctx.runtime.currentIndex = Math.max(0, ctx.runtime.currentIndex - 1);
      renderGrammarTestView(ctx.content, ctx.lesson);
      return;
    }

    const grammarTestNextBtn = event.target.closest('.grammar-test-next-btn');
    if (grammarTestNextBtn) {
      const ctx = getGrammarTestContext(grammarTestNextBtn);
      if (!ctx) return;
      collectGrammarTestAnswer(ctx.content, ctx.test, ctx.runtime);
      if (ctx.runtime.currentIndex >= ctx.test.questions.length - 1) {
        ctx.runtime.phase = 'review';
      } else {
        ctx.runtime.currentIndex += 1;
      }
      renderGrammarTestView(ctx.content, ctx.lesson);
      return;
    }

    const grammarTestReviewEditBtn = event.target.closest('.grammar-test-review-edit-btn');
    if (grammarTestReviewEditBtn) {
      const ctx = getGrammarTestContext(grammarTestReviewEditBtn);
      if (!ctx) return;
      ctx.runtime.currentIndex = Number(grammarTestReviewEditBtn.dataset.questionIndex) || 0;
      ctx.runtime.phase = 'question';
      renderGrammarTestView(ctx.content, ctx.lesson);
      return;
    }

    const grammarTestRetryBtn = event.target.closest('.grammar-test-retry-btn');
    if (grammarTestRetryBtn) {
      const ctx = getGrammarTestContext(grammarTestRetryBtn);
      if (!ctx) return;
      grammarTestState.set(ctx.lesson.slug, {
        phase: 'question',
        currentIndex: 0,
        answers: {},
        questionResults: {},
        lastResult: null
      });
      renderGrammarTestView(ctx.content, ctx.lesson);
      return;
    }

    const grammarTestSubmitBtn = event.target.closest('.grammar-test-submit-btn');
    if (grammarTestSubmitBtn) {
      const ctx = getGrammarTestContext(grammarTestSubmitBtn);
      if (!ctx || grammarTestSubmitBtn.dataset.submitting === 'true') return;

      collectAllGrammarTestAnswers(ctx.content, ctx.test, ctx.runtime);
      const firstMissing = ctx.test.questions.find(
        (question) => !isGrammarTestQuestionAnswered(ctx.runtime, question)
      );
      if (firstMissing) {
        const missingItem = [...ctx.content.querySelectorAll('.grammar-test-question-item')].find(
          (item) => String(item.dataset.questionId) === String(firstMissing.id)
        );
        const warning = ctx.content.querySelector('.grammar-test-review-warning');
        if (warning) warning.hidden = false;
        missingItem?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        missingItem?.querySelector('input, select, button')?.focus({ preventScroll: true });
        showHomeToast(
          isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
            ? 'Il reste une question sans réponse.'
            : 'Queda una pregunta sin responder.'
        );
        return;
      }

      if (!authStatus.session?.access_token) {
        const restored = await refreshAuthSession();
        if (!restored || !authStatus.session?.access_token) {
          openModal('login', {
            message: 'Inicia sesión para guardar el resultado de tu prueba.'
          });
          return;
        }
      }

      const { lesson, content, test, runtime } = ctx;
      grammarTestSubmitBtn.disabled = true;
      grammarTestSubmitBtn.dataset.submitting = 'true';
      grammarTestSubmitBtn.textContent = isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
        ? 'Envoi en cours…'
        : 'Enviando…';

      try {
        const answers = test.questions.map((q) => ({ questionId: q.id, answer: runtime.answers[q.id] }));
        const response = await authFetch(`${backendBaseUrl}/api/lessons/${lesson.slug}/complete`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ answers })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) {
          throw new Error(
            data.error ||
              (isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
                ? 'Impossible d’envoyer l’exercice.'
                : 'No se pudo enviar el ejercicio.')
          );
        }

        lesson.completed = true;
        if (data.bestScore != null) lesson.bestScore = data.bestScore;
        updateProgressDisplay(data, true);
        renderSkillCards();
        renderLearningPath();
        loadDashboard();
        window.AndergoGamification?.recordLessonCompletion({
          slug: lesson.slug,
          language: learningPathState.language,
          ...getLessonGamificationContext(lesson),
          score: data.score ?? 100,
          xpReward: lesson.xpReward || 20
        });
        window.AndergoGamification?.syncFromServer(data);
        if (data.newBadges?.length) {
          data.newBadges.forEach((badge) =>
            showCelebration(`🏅 ¡Insignia desbloqueada! ${badge.label}`)
          );
        }
        if (data.leveledUp) showCelebration(`🎉 ¡Subiste a nivel ${data.level}!`);
        showHomeToast(
          isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
            ? `Exercice terminé. +${data.earnedXp || lesson.xpReward || 20} XP`
            : `Ejercicio completado. +${data.earnedXp || lesson.xpReward || 20} XP`
        );
        celebrateActivityCompletion();

        runtime.lastResult = data;
        runtime.phase = 'results';
        renderGrammarTestView(content, lesson);
      } catch (error) {
        grammarTestSubmitBtn.disabled = false;
        delete grammarTestSubmitBtn.dataset.submitting;
        grammarTestSubmitBtn.textContent = isFrenchExerciseFeedbackInTargetLanguage(ctx.lesson.level)
          ? 'Vérifier mon score de grammaire'
          : learningPathState.language === 'spanish'
            ? 'Comprobar mi puntuación de gramática'
            : 'Check my Grammar score';
        showHomeToast(error.message || 'No se pudo enviar la prueba.');
      }
      return;
    }

    // Scored Listening Comprehension (see renderListeningComprehensionPanel
    // and friends above) - same shape/endpoint as the Grammar test handlers
    // just above, but resolves into .listening-mode-panel (one tab among
    // Escuchar/Diálogos/Dictado/Transcripción/Transcripción fonética)
    // instead of the whole .skill-view-content, and reads
    // lesson.extra.listeningComprehension instead of lesson.extra.grammarTest.
    function getListeningComprehensionContext(target) {
      const skillSection = target.closest('.skill-view-section');
      const lesson = learningPathState.lessons.find(
        (item) => item.slug === skillSection?.dataset.activeLessonSlug
      );
      const panel = skillSection?.querySelector('.listening-mode-panel');
      const bank = lesson ? getListeningComprehensionBank(lesson) : null;
      if (!bank?.questions?.length || !panel) return null;
      return {
        lesson,
        content: skillSection.querySelector('.skill-view-content'),
        panel,
        bank,
        runtime: getListeningComprehensionRuntime(lesson)
      };
    }

    const listeningCompStartBtn = event.target.closest('.listening-comp-start-btn');
    if (listeningCompStartBtn) {
      const ctx = getListeningComprehensionContext(listeningCompStartBtn);
      if (!ctx) return;
      ctx.runtime.phase = 'question';
      ctx.runtime.currentIndex = 0;
      ctx.panel.innerHTML = renderListeningComprehensionPanel(ctx.lesson);
      return;
    }

    const listeningCompPrevBtn = event.target.closest('.listening-comp-prev-btn');
    if (listeningCompPrevBtn) {
      const ctx = getListeningComprehensionContext(listeningCompPrevBtn);
      if (!ctx) return;
      collectGrammarTestAnswer(ctx.panel, ctx.bank, ctx.runtime);
      ctx.runtime.currentIndex = Math.max(0, ctx.runtime.currentIndex - 1);
      ctx.panel.innerHTML = renderListeningComprehensionPanel(ctx.lesson);
      return;
    }

    const listeningCompNextBtn = event.target.closest('.listening-comp-next-btn');
    if (listeningCompNextBtn) {
      const ctx = getListeningComprehensionContext(listeningCompNextBtn);
      if (!ctx) return;
      collectGrammarTestAnswer(ctx.panel, ctx.bank, ctx.runtime);
      if (ctx.runtime.currentIndex >= ctx.bank.questions.length - 1) {
        ctx.runtime.phase = 'review';
      } else {
        ctx.runtime.currentIndex += 1;
      }
      ctx.panel.innerHTML = renderListeningComprehensionPanel(ctx.lesson);
      return;
    }

    const listeningCompReviewEditBtn = event.target.closest('.listening-comp-review-edit-btn');
    if (listeningCompReviewEditBtn) {
      const ctx = getListeningComprehensionContext(listeningCompReviewEditBtn);
      if (!ctx) return;
      ctx.runtime.currentIndex = Number(listeningCompReviewEditBtn.dataset.questionIndex) || 0;
      ctx.runtime.phase = 'question';
      ctx.panel.innerHTML = renderListeningComprehensionPanel(ctx.lesson);
      return;
    }

    const listeningCompRetryBtn = event.target.closest('.listening-comp-retry-btn');
    if (listeningCompRetryBtn) {
      const ctx = getListeningComprehensionContext(listeningCompRetryBtn);
      if (!ctx) return;
      listeningComprehensionState.set(ctx.lesson.slug, {
        phase: 'question',
        currentIndex: 0,
        answers: {},
        lastResult: null
      });
      ctx.panel.innerHTML = renderListeningComprehensionPanel(ctx.lesson);
      return;
    }

    const listeningCompSubmitBtn = event.target.closest('.listening-comp-submit-btn');
    if (listeningCompSubmitBtn) {
      const ctx = getListeningComprehensionContext(listeningCompSubmitBtn);
      if (!ctx || listeningCompSubmitBtn.disabled) return;

      if (!authStatus.session?.access_token) {
        openModal('login', {
          message: 'Inicia sesión para guardar el resultado de esta prueba.'
        });
        return;
      }

      const { lesson, panel, bank, runtime } = ctx;
      listeningCompSubmitBtn.disabled = true;
      listeningCompSubmitBtn.textContent = 'Enviando...';

      try {
        const answers = bank.questions.map((q) => ({ questionId: q.id, answer: runtime.answers[q.id] }));
        const response = await authFetch(`${backendBaseUrl}/api/lessons/${lesson.slug}/complete`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ answers })
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(data.error || 'No se pudo enviar la prueba.');

        lesson.completed = true;
        if (data.bestScore != null) lesson.listeningComprehensionBestScore = data.bestScore;
        if (data.bestScore != null) lesson.bestScore = data.bestScore;
        updateProgressDisplay(data, true);
        renderSkillCards();
        renderLearningPath();
        loadDashboard();
        window.AndergoGamification?.recordLessonCompletion({
          slug: lesson.slug,
          language: learningPathState.language,
          ...getLessonGamificationContext(lesson),
          score: data.score ?? 100,
          xpReward: lesson.xpReward || 20
        });
        window.AndergoGamification?.syncFromServer(data);
        if (data.newBadges?.length) {
          data.newBadges.forEach((badge) =>
            showCelebration(`🏅 ¡Insignia desbloqueada! ${badge.label}`)
          );
        }
        if (data.leveledUp) showCelebration(`🎉 ¡Subiste a nivel ${data.level}!`);
        showHomeToast(`Comprensión completada. +${data.earnedXp || lesson.xpReward || 20} XP`);
        celebrateActivityCompletion();

        runtime.lastResult = data;
        runtime.phase = 'results';
        panel.innerHTML = renderListeningComprehensionPanel(lesson);
      } catch (error) {
        listeningCompSubmitBtn.disabled = false;
        listeningCompSubmitBtn.textContent = 'Enviar';
        showHomeToast(error.message || 'No se pudo enviar la prueba.');
      }
      return;
    }

    const practiceButton = event.target.closest('.practice-mark-btn');
    if (practiceButton) {
      const exerciseBlock = practiceButton.closest('.open-exercise');
      const slug = exerciseBlock?.dataset.lessonSlug;
      if (practiceButton.disabled || !slug) return;

      const exerciseIndex = Number(exerciseBlock.dataset.exerciseIndex);
      const selfScore = Math.max(0, Math.min(100, Number(practiceButton.dataset.selfScore) || 50));
      learningPathState.exerciseResults[slug] = learningPathState.exerciseResults[slug] || {};
      learningPathState.exerciseResults[slug][exerciseIndex] = { practiced: true, selfScore };

      if (selfScore >= 75) window.AndergoGamification?.recordCorrectAnswer();
      window.AndergoGamification?.recordSkillTouched(
        exerciseBlock.dataset.skill,
        exerciseBlock.dataset.language || learningPathState.language
      );
      window.playExerciseFeedbackSound?.(selfScore >= 75);

      renderLessonWorkspace();
      return;
    }

    const tutorClearButton = event.target.closest('.tutor-clear-btn');
    if (tutorClearButton) {
      resetTutorTopicSessions();
      const conversation = document.getElementById('tutorConversation');
      if (conversation) {
        conversation.innerHTML =
          '<p class="tutor-welcome">👋 Soy el Tutor IA ANDERGO Academy. Puedes preguntarme lo que quieras, en el idioma que prefieras.</p>';
      }
      restoreTutorTopicComposer(document.getElementById('aiTutorPrompt'), tutorClearButton.closest('.tutor-action')?.querySelector('.tutor-chat-btn'));
      return;
    }

    const tutorButton = event.target.closest('.tutor-chat-btn');
    if (tutorButton) {
      primeTutorAudioForAutoplay();
      const card = tutorButton.closest('#tutor');
      const selectedSuggestion = card
        ?.querySelector('.skill-panel.active .predictive-suggestion.selected')
        ?.textContent?.trim();
      const fallbackPrompt = 'Pregúntame lo que quieras.';
      const isFreeTutorContext = tutorDrawerContext.contextScope === 'general';

      await sendTutorMessage({
        conversationEl: document.getElementById('tutorConversation'),
        thinkingEl: document.getElementById('tutorThinking'),
        connectionStatusEl: document.getElementById('tutorConnectionStatus'),
        promptEl: document.getElementById('aiTutorPrompt'),
        sendBtn: tutorButton,
        skill: tutorDrawerContext.skill || 'general',
        level: isFreeTutorContext ? 'N/A' : learningPathState.level || 'N/A',
        language: getTutorLanguage(),
        // Outside a learning route, Spanish is the default support language
        // (L1). The selected Tutor language remains the independent L2/TTS.
        bridgeLanguage: isFreeTutorContext ? 'spanish' : learningPathState.bridgeLanguage,
        lessonTitle: tutorDrawerContext.lessonTitle,
        lessonIntro: tutorDrawerContext.lessonIntro,
        lessonSlug: tutorDrawerContext.lessonSlug,
        currentActivity: tutorDrawerContext.currentActivity || 'Consulta libre con Tutor IA',
        supportMode: tutorDrawerContext.supportMode,
        contextScope: tutorDrawerContext.contextScope,
        transcript: tutorDrawerContext.transcript,
        vocabulary: tutorDrawerContext.vocabulary,
        currentQuestion: tutorDrawerContext.currentQuestion,
        selectedAnswer: tutorDrawerContext.selectedAnswer,
        selectedSuggestion,
        fallbackPrompt: tutorDrawerContext.fallbackPrompt || fallbackPrompt
      });
      return;
    }

    const openTutorBtn = event.target.closest('.open-tutor-btn');
    if (openTutorBtn) {
      const skillSection = openTutorBtn.closest('.skill-view-section');
      const skill = skillSection?.dataset.skill || 'speaking';
      const lesson =
        learningPathState.lessons.find(
          (item) => item.slug === skillSection?.dataset.activeLessonSlug
        ) || getActiveLearningLesson();
      openTutorDrawer({
        skill,
        contextScope: 'lesson',
        lessonTitle: lesson?.title || '',
        lessonIntro: lesson?.intro || lesson?.description || '',
        lessonSlug: lesson?.slug || '',
        supportMode: openTutorBtn.dataset.supportMode || 'practice',
        currentActivity: `Practicando ${getSkillLabel(skill)}`,
        prefill: openTutorBtn.dataset.tutorPrompt || '',
        transcript: openTutorBtn.dataset.tutorTranscript || '',
        vocabulary: openTutorBtn.dataset.tutorVocabulary || '',
        currentQuestion: openTutorBtn.dataset.tutorCurrentQuestion || '',
        selectedAnswer: openTutorBtn.dataset.tutorSelectedAnswer || ''
      });
      return;
    }

    // "Traducir" shortcuts from Reading/Grammar/Vocabulary/Speaking - see
    // openTranslator(). Always translates target-language content back into
    // the student's bridge language; data-return-label lets each view name
    // itself in "‹ Volver a ...".
    const openCorrectorBtn = event.target.closest('.open-corrector-btn');
    if (openCorrectorBtn) {
      const editorText = document.getElementById('writingEditor')?.value.trim() || '';
      if (!editorText) {
        showHomeToast('Escribe tu texto antes de abrir el Corrector.');
        return;
      }
      const activeLesson = learningPathState.lessons.find((item) => item.slug === learningPathState.activeSlug);
      const speakingLesson = learningPathState.lessons.find(
        (item) => item.unitId === activeLesson?.unitId && item.skill === 'speaking'
      );
      if (!speakingLesson) {
        showHomeToast('Esta unidad todavía no tiene una actividad de Speaking.');
        return;
      }
      pendingSpeakingCorrectorText = editorText;
      speakingViewState = {
        lessonSlug: speakingLesson.slug,
        mode: 'corrector',
        guidedTurnIndex: 0,
        pronunciationIndex: 0,
        pronunciationOverride: ''
      };
      setActiveLesson(speakingLesson.slug);
      updateLearnHash('speaking');
      showView('speaking');
      renderSkillView('speaking');
      return;
    }

    const openPhoneticsBtn = event.target.closest('.open-phonetics-btn');
    if (openPhoneticsBtn) {
      openTranslator({
        mode: 'phonetics',
        text: openPhoneticsBtn.dataset.phoneticsText || '',
        toolLanguage: learningPathState.language,
        returnHash: window.location.hash || '#learn',
        returnLabel: openPhoneticsBtn.dataset.returnLabel || 'Volver a Reading'
      });
      return;
    }

    const openTranslatorBtn = event.target.closest('.open-translator-btn');
    if (openTranslatorBtn) {
      openTranslator({
        text: openTranslatorBtn.dataset.translateText || '',
        sourceLanguage: learningPathState.language,
        targetLanguage: learningPathState.bridgeLanguage,
        returnHash: window.location.hash || '#learn',
        returnLabel: openTranslatorBtn.dataset.returnLabel || 'Volver a la lección'
      });
      return;
    }

    // AI Tutor voice controls (Escuchar/Repetir share one button - see
    // renderTutorVoiceControls(); its label switches once played once).
    const tutorVoiceListenBtn = event.target.closest('.tutor-voice-listen');
    if (tutorVoiceListenBtn) {
      const messageEl = tutorVoiceListenBtn.closest('.tutor-message');
      if (messageEl) requestTutorSpeech(messageEl);
      return;
    }
    const tutorVoicePauseBtn = event.target.closest('.tutor-voice-pause');
    if (tutorVoicePauseBtn) {
      toggleTutorVoicePause(tutorVoicePauseBtn.closest('.tutor-message'));
      return;
    }
    const tutorVoiceRewindBtn = event.target.closest('.tutor-voice-rewind');
    if (tutorVoiceRewindBtn) {
      rewindTutorVoice(5);
      return;
    }
    const tutorVoiceStopBtn = event.target.closest('.tutor-voice-stop');
    if (tutorVoiceStopBtn) {
      // The stop control embedded in a spoken answer is the same stop action
      // as the conversation header: halt TTS and disarm hands-free listening
      // so the tutor cannot restart the microphone after playback ends.
      if (tutorVoiceStopBtn.closest('#tutor')) stopTutorMainConversation();
      else {
        setTutorConversationMode(false, 'drawer');
        stopTutorDictation();
        stopAllTutorAudio();
      }
      return;
    }
    const tutorVoiceSpeedBtn = event.target.closest('.tutor-voice-speed-btn');
    if (tutorVoiceSpeedBtn) {
      const messageEl = tutorVoiceSpeedBtn.closest('.tutor-message');
      const wasPlaying = messageEl && currentTutorAudio.messageEl === messageEl;
      tutorVoiceSpeedBtn
        .closest('.tutor-voice-speed-group')
        ?.querySelectorAll('.tutor-voice-speed-btn')
        .forEach((btn) => {
          const isActive = btn === tutorVoiceSpeedBtn;
          btn.classList.toggle('is-active', isActive);
          btn.setAttribute('aria-pressed', String(isActive));
        });
      // Spec §6: "al cambiar entre Normal y Lenta: detener la lectura
      // actual, reiniciar desde el comienzo con la nueva velocidad" -
      // requestTutorSpeech already calls stopAllTutorAudio() first thing,
      // so re-calling it here (only when this message was the one actually
      // speaking) restarts fresh at wordIndex -1 instead of resuming
      // mid-utterance at the old rate.
      if (wasPlaying) requestTutorSpeech(messageEl);
      return;
    }

    const changeComboBtn = event.target.closest('.change-combination-btn');
    if (changeComboBtn) {
      openChangeCombinationPopover();
      return;
    }
    if (event.target.closest('.change-combo-apply')) {
      applyChangeCombination();
      return;
    }
    if (event.target.closest('.change-combo-close') || event.target.id === 'changeComboPopover') {
      closeChangeCombinationPopover();
      return;
    }

    if (event.target.closest('[data-action="close-tutor-drawer"]')) {
      closeTutorDrawer();
      return;
    }

    const readingSizeButton = event.target.closest('.reading-size-btn');
    if (readingSizeButton) {
      const area = readingSizeButton.closest('.reading-print-area');
      const preferences = getReadingDisplayPreferences();
      preferences.size = readingSizeButton.dataset.readingSize;
      applyReadingDisplayPreferences(area, preferences);
      setReadingDisplayPreferences(preferences);
      return;
    }
    const readingAlignButton = event.target.closest('.reading-align-btn');
    if (readingAlignButton) {
      const area = readingAlignButton.closest('.reading-print-area');
      const preferences = getReadingDisplayPreferences();
      preferences.alignment = preferences.alignment === 'justify' ? 'left' : 'justify';
      applyReadingDisplayPreferences(area, preferences);
      setReadingDisplayPreferences(preferences);
      return;
    }
    const readingToggleVocab = event.target.closest('.reading-toggle-vocab');
    if (readingToggleVocab) {
      const list = readingToggleVocab
        .closest('.reading-vocab-section')
        ?.querySelector('.reading-vocab-list');
      if (list) {
        list.hidden = !list.hidden;
        readingToggleVocab.textContent = list.hidden ? 'Ver vocabulario' : 'Ocultar vocabulario';
        readingToggleVocab.setAttribute('aria-expanded', String(!list.hidden));
      }
      return;
    }
    const readingToggleSupport = event.target.closest('.reading-toggle-support');
    if (readingToggleSupport) {
      const area = readingToggleSupport.closest('.reading-print-area');
      const showSupport = readingToggleSupport.getAttribute('aria-pressed') !== 'true';
      const vocabList = area?.querySelector('.reading-vocab-list');
      area?.querySelectorAll('.reading-vocab-support').forEach((element) => {
        element.hidden = !showSupport;
      });
      if (showSupport && vocabList) {
        vocabList.hidden = false;
        const vocabButton = area.querySelector('.reading-toggle-vocab');
        if (vocabButton) {
          vocabButton.textContent = 'Ocultar vocabulario';
          vocabButton.setAttribute('aria-expanded', 'true');
        }
      }
      readingToggleSupport.setAttribute('aria-pressed', String(showSupport));
      readingToggleSupport.textContent = showSupport
        ? learningPathState.language === 'french'
          ? "Masquer l'aide en espagnol"
          : 'Ocultar ayuda en español'
        : learningPathState.language === 'french'
          ? "Afficher l'aide en espagnol"
          : 'Mostrar ayuda en español';
      return;
    }
    if (event.target.closest('.reading-word-btn')) {
      downloadReadingWord(getActiveLearningLesson());
      return;
    }
    if (event.target.closest('.reading-print-btn') || event.target.closest('.skill-print-btn')) {
      // window.print() itself rarely throws, but embedding contexts that
      // block it (some sandboxed iframes/webviews) do - never leave the
      // student with silent nothing-happened.
      try {
        window.print();
      } catch {
        showHomeToast('No pudimos generar el PDF. Inténtalo nuevamente.');
      }
      return;
    }

    const vocabTranslationButton = event.target.closest('.vocab-l1-translation-btn');
    if (vocabTranslationButton) {
      const activeSection = vocabTranslationButton.closest('.skill-view-section');
      const activeLesson = activeSection ? getActiveLearningLesson() : null;
      if (!activeSection || !activeLesson) return;
      vocabL1TranslationVisible = !vocabL1TranslationVisible;
      if (vocabL1TranslationVisible) {
        vocabTranslationButton.disabled = true;
        vocabTranslationButton.textContent = isFrenchAdvancedImmersion()
          ? 'Traduction en cours…'
          : 'Traduciendo…';
        await loadMissingAdvancedVocabTranslations(
          vocabPracticeSources.get(activeLesson.slug) || [],
          activeLesson.slug
        );
      }
      renderVocabularyView(activeSection, activeLesson);
      return;
    }

    if (event.target.closest('.vocab-shuffle-btn')) {
      // Fisher-Yates on the display-order array only - lesson.vocabulary
      // itself (and therefore the underlying test exercises' indices) never
      // changes, so "Mezclar tarjetas" only reorders what the student sees.
      for (let i = vocabCardOrder.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1));
        [vocabCardOrder[i], vocabCardOrder[j]] = [vocabCardOrder[j], vocabCardOrder[i]];
      }
      const activeSection = event.target.closest('.skill-view-section');
      const activeLesson = activeSection ? getActiveLearningLesson() : null;
      if (activeSection && activeLesson) renderVocabularyView(activeSection, activeLesson);
      return;
    }

    // Full-reading audio player (spec section A/C) - the only controls that
    // move forward/back through a reading; they act on the audio only and
    // never touch which text is visible (no pagination, no part viewer). A
    // single toggle button cycles Reproducir -> Pausar -> Continuar ->
    // Pausar..., the rest are one-shot actions on the shared
    // readingSpeechPlayer singleton.
    const readingAudioPlayPauseBtn = event.target.closest('.reading-audio-playpause-btn');
    if (readingAudioPlayPauseBtn) {
      const snap = readingSpeechPlayer.getSnapshot();
      if (snap.state === 'playing') readingSpeechPlayer.pauseReading();
      else if (snap.state === 'paused') readingSpeechPlayer.resumeReading();
      else readingSpeechPlayer.playReading();
      return;
    }
    const readingAudioRewindBtn = event.target.closest('.reading-audio-rewind-btn');
    if (readingAudioRewindBtn) {
      readingSpeechPlayer.rewindReading(5);
      return;
    }
    const readingAudioStopBtn = event.target.closest('.reading-audio-stop-btn');
    if (readingAudioStopBtn) {
      readingSpeechPlayer.stopReading();
      return;
    }
    const readingAudioVoiceBtn = event.target.closest('.reading-audio-voice-btn');
    if (readingAudioVoiceBtn) {
      readingSpeechPlayer.changeReadingVoice();
      return;
    }
    const readingAudioRateBtn = event.target.closest('.reading-audio-rate-btn');
    if (readingAudioRateBtn) {
      readingSpeechPlayer.changeReadingRate(readingAudioRateBtn.dataset.rate);
      return;
    }
    const writingReviewBtn = event.target.closest('.writing-review-btn');
    if (writingReviewBtn) {
      const editor = document.getElementById('writingEditor');
      const editorText = editor?.value.trim() || '';
      if (!editorText) {
        showHomeToast('Escribe tu texto antes de pedir revisión.');
        return;
      }
      const mode = writingReviewBtn.dataset.supportMode;
      const prompts = {
        'review-complete': `Revisa este texto de manera sencilla. Responde en tres bloques breves: 1) Lo que está bien, 2) Las tres mejoras más importantes de claridad, gramática o vocabulario, 3) Un ejemplo corregido sin reemplazar toda la voz del estudiante: ${editorText}`,
        'review-grammar': `Revisa la gramática de este texto y explica los errores: ${editorText}`,
        'review-vocabulary': `Sugiere mejoras de vocabulario para este texto: ${editorText}`,
        'review-coherence': `Revisa la coherencia y organización de este texto: ${editorText}`,
        'explain-errors': `Explícame en español los errores de este texto: ${editorText}`,
        hint: `Dame una pista para mejorar este texto sin reescribirlo tú: ${editorText}`
      };
      const section = writingReviewBtn.closest('.skill-view-section');
      const lesson = learningPathState.lessons.find(
        (item) => item.slug === section?.dataset.activeLessonSlug
      );
      const panel = document.getElementById('writingTutorPanel');
      if (panel) {
        panel.hidden = false;
        panel.querySelector('.writing-tutor-original p').textContent = editorText;
        panel.querySelector('.writing-tutor-suggestion p').textContent = 'Consultando al Tutor IA…';
      }
      writingReviewBtn.disabled = true;
      const data = await sendTutorMessage({
        conversationEl: null,
        thinkingEl: null,
        connectionStatusEl: null,
        promptEl: null,
        sendBtn: null,
        skill: 'writing',
        level: learningPathState.level || 'A1',
        language: learningPathState.language,
        bridgeLanguage: learningPathState.bridgeLanguage,
        lessonTitle: lesson?.title || '',
        lessonIntro: lesson?.intro || lesson?.description || '',
        lessonSlug: lesson?.slug || '',
        currentActivity: 'Escribiendo un texto',
        supportMode: mode,
        fallbackPrompt: prompts[mode] || editorText
      });
      writingReviewBtn.disabled = false;
      if (panel)
        panel.querySelector('.writing-tutor-suggestion p').textContent =
          data?.reply || 'No se pudo obtener una respuesta del Tutor IA.';
      return;
    }
    if (event.target.closest('.writing-accept-btn')) {
      // Never auto-replaces the student's text - just acknowledges the
      // suggestion was reviewed and dismisses the panel.
      document.getElementById('writingTutorPanel')?.setAttribute('hidden', '');
      showHomeToast('Sugerencia aceptada. Tu texto no se modificó automáticamente.');
      return;
    }
    if (event.target.closest('.writing-reject-btn')) {
      document.getElementById('writingTutorPanel')?.setAttribute('hidden', '');
      showHomeToast('Sugerencia descartada.');
      return;
    }
    if (event.target.closest('.writing-compare-btn')) {
      const panel = document.getElementById('writingTutorPanel');
      const currentBlock = panel?.querySelector('.writing-tutor-current');
      if (currentBlock) {
        currentBlock.hidden = !currentBlock.hidden;
        if (!currentBlock.hidden)
          currentBlock.querySelector('p').textContent =
            document.getElementById('writingEditor')?.value.trim() || '';
      }
      return;
    }

    // Header speaker button - plays the target word without flipping the
    // card. stopPropagation keeps it from also falling through to the
    // "tap anywhere flips" handler below. Marks itself "is-playing" while
    // speaking (speakText's onEnd clears it) so the playing state is
    // visible, not just audible.
    const vocabAudioBtn = event.target.closest('.vocab-card-audio-btn');
    if (vocabAudioBtn) {
      event.stopPropagation();
      const card = vocabAudioBtn.closest('.vocab-card');
      if (card) {
        vocabAudioBtn.classList.add('is-playing');
        speakText(card.dataset.speakText, {
          locale: card.dataset.speakLocale,
          rate: Number(card.dataset.speakRate) || 1,
          onEnd: () => vocabAudioBtn.classList.remove('is-playing')
        });
      }
      return;
    }
    // Each context's own speaker button on the back of the card (only
    // rendered when there's a context sentence to speak).
    const vocabExampleAudioBtn = event.target.closest('.vocab-example-audio-btn');
    if (vocabExampleAudioBtn) {
      event.stopPropagation();
      vocabExampleAudioBtn.classList.add('is-playing');
      speakText(vocabExampleAudioBtn.dataset.speakText, {
        locale: vocabExampleAudioBtn.dataset.speakLocale,
        rate: Number(vocabExampleAudioBtn.dataset.speakRate) || 1,
        onEnd: () => vocabExampleAudioBtn.classList.remove('is-playing')
      });
      return;
    }
    const vocabKnowBtn = event.target.closest('.vocab-know-btn');
    if (vocabKnowBtn) {
      event.stopPropagation();
      setVocabCardMastery(vocabKnowBtn.closest('.vocab-card'), 'mastered');
      return;
    }
    const vocabRetryBtn = event.target.closest('.vocab-retry-btn');
    if (vocabRetryBtn) {
      event.stopPropagation();
      setVocabCardMastery(vocabRetryBtn.closest('.vocab-card'), 'practicing');
      return;
    }
    const vocabBackBtn = event.target.closest('.vocab-back-btn');
    if (vocabBackBtn) {
      event.stopPropagation();
      flipVocabCard(vocabBackBtn.closest('.vocab-card'), { toBack: false });
      return;
    }
    // Tapping any free area of the card flips it: front -> back speaks the
    // target word once (via flipVocabCard's speak option), back -> front
    // stays silent. Only fires when the click wasn't already handled by a
    // more specific control above.
    const vocabCardBody = event.target.closest('.vocab-card');
    if (vocabCardBody) {
      const isFlipped = vocabCardBody.dataset.flipped === 'true';
      flipVocabCard(vocabCardBody, { toBack: !isFlipped, speak: !isFlipped });
      return;
    }
  });

  document.getElementById('tutorFab')?.addEventListener('click', () => openTutorDrawer());

  document.getElementById('tutorPageReturn')?.addEventListener('click', () => {
    const target = tutorPageReturnHash || '#learn';
    tutorPageReturnHash = '';
    history.pushState(null, '', target);
    showView(getViewFromHash());
  });

  document.getElementById('tutorDrawerSend')?.addEventListener('click', async () => {
    primeTutorAudioForAutoplay();
    const sendBtn = document.getElementById('tutorDrawerSend');
    document.querySelector('#tutorDrawer .tutor-drawer-panel')?.classList.add('is-response-focused');
    await sendTutorMessage({
      conversationEl: document.getElementById('tutorDrawerConversation'),
      thinkingEl: document.getElementById('tutorDrawerThinking'),
      connectionStatusEl: document.getElementById('tutorDrawerConnectionStatus'),
      promptEl: document.getElementById('tutorDrawerPrompt'),
      sendBtn,
      skill: tutorDrawerContext.skill,
      level: learningPathState.level || 'A1',
      language: getTutorLanguage(),
      bridgeLanguage: learningPathState.bridgeLanguage,
      lessonTitle: tutorDrawerContext.lessonTitle,
      lessonIntro: tutorDrawerContext.lessonIntro,
      lessonSlug: tutorDrawerContext.lessonSlug,
      currentActivity:
        tutorDrawerContext.currentActivity ||
        `Practicando ${getSkillLabel(tutorDrawerContext.skill)}`,
      supportMode: tutorDrawerContext.supportMode,
      contextScope: tutorDrawerContext.contextScope,
      transcript: tutorDrawerContext.transcript,
      vocabulary: tutorDrawerContext.vocabulary,
      currentQuestion: tutorDrawerContext.currentQuestion,
      selectedAnswer: tutorDrawerContext.selectedAnswer,
      fallbackPrompt: tutorDrawerContext.fallbackPrompt || 'Quiero practicar esta habilidad.'
    });
  });

  document.getElementById('tutorDrawerClear')?.addEventListener('click', () => {
    resetTutorTopicSessions();
    const conversation = document.getElementById('tutorDrawerConversation');
    if (conversation)
      conversation.innerHTML = `<p class="tutor-welcome">${escapeHtml(
        tutorDrawerContext.welcomeMessage ||
          '👋 Soy el Tutor IA ANDERGO Academy. Puedes preguntarme lo que quieras, en el idioma que prefieras.'
      )}</p>`;
    restoreTutorTopicComposer(document.getElementById('tutorDrawerPrompt'), document.getElementById('tutorDrawerSend'));
    document.querySelector('#tutorDrawer .tutor-drawer-panel')?.classList.remove('is-response-focused');
  });

  document.getElementById('tutorDrawerNewQuestion')?.addEventListener('click', () => {
    document.querySelector('#tutorDrawer .tutor-drawer-panel')?.classList.remove('is-response-focused');
    document.getElementById('tutorDrawerPrompt')?.focus();
  });

  document.querySelectorAll('.tutor-quick-action').forEach((button) => {
    button.addEventListener('click', () => {
      const prompt = button.closest('#tutor')
        ? document.getElementById('aiTutorPrompt')
        : document.getElementById('tutorDrawerPrompt');
      if (!prompt) return;
      prompt.value = button.dataset.tutorQuickPrompt || '';
      delete prompt.dataset.tutorInputSource;
      prompt.focus();
      prompt.setSelectionRange(prompt.value.length, prompt.value.length);
    });
  });

  document.getElementById('tutorDrawerPrompt')?.addEventListener('keydown', (event) => {
    // Any keystroke while a post-dictation auto-send is pending restarts its
    // 2s window (spec §5), letting the student finish an edit before it
    // fires - a no-op the rest of the time.
    restartTutorAutoSendIfPending('tutorDrawerPrompt');
    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    document.getElementById('tutorDrawerSend')?.click();
  });

  // Two autoplay checkboxes (drawer + full Tutor page) share the same
  // localStorage preference - keep both in sync whenever either changes.
  const autoplayToggleIds = ['tutorAutoplayToggle', 'tutorMainAutoplayToggle'];
  const autoplayToggles = autoplayToggleIds
    .map((id) => document.getElementById(id))
    .filter(Boolean);
  autoplayToggles.forEach((toggle) => {
    toggle.checked = getTutorAutoplayPref();
    toggle.addEventListener('change', () => {
      setTutorAutoplayPref(toggle.checked);
      autoplayToggles.forEach((other) => {
        if (other !== toggle) other.checked = toggle.checked;
      });
    });
  });

  document.getElementById('tutorMainVoiceStop')?.addEventListener('click', stopTutorMainConversation);
  document.querySelectorAll('[data-tutor-language]').forEach((button) => {
    button.addEventListener('click', () => setTutorLanguage(button.dataset.tutorLanguage));
  });
  setTutorLanguage(getTutorLanguage());

  document.addEventListener('input', (event) => {
    const input = event.target.closest('.grammar-test-fill-input');
    if (!input) return;

    const questionItem = input.closest('.grammar-test-question-item');
    const skillSection = input.closest('.skill-view-section');
    const lesson = learningPathState.lessons.find(
      (item) => item.slug === skillSection?.dataset.activeLessonSlug
    );
    const test = lesson?.extra?.grammarTest;
    const content = skillSection?.querySelector('.skill-view-content');
    const questionId = questionItem?.dataset.questionId;
    if (!test?.questions?.length || !content || !questionId) return;

    const runtime = getGrammarTestRuntime(lesson);
    const value = input.value.trim();
    if (value) runtime.answers[questionId] = value;
    else delete runtime.answers[questionId];

    const answered = test.questions.filter((question) =>
      isGrammarTestQuestionAnswered(runtime, question)
    ).length;
    const total = test.questions.length;
    const progress = total ? Math.round((answered / total) * 100) : 0;
    const counter = content.querySelector('.grammar-test-counter');
    const progressBar = content.querySelector('.grammar-test-progress-bar div');
    const warning = content.querySelector('.grammar-test-review-warning');
    const submit = content.querySelector('.grammar-test-submit-btn');

    if (counter) {
      counter.textContent = isFrenchTargetLanguage()
        ? `${answered} sur ${total} réponses`
        : `${answered} of ${total} answered`;
    }
    if (progressBar) progressBar.style.width = `${progress}%`;
    if (warning) warning.hidden = answered === total;
    if (submit) submit.setAttribute('aria-disabled', String(answered !== total));
    updateGrammarChallengeProgress(content, test, runtime, isFrenchTargetLanguage());
  });

  document.addEventListener('change', (event) => {
    const select = event.target.closest('.grammar-test-order-select');
    if (!select) return;
    const questionItem = select.closest('.grammar-test-question-item');
    const skillSection = select.closest('.skill-view-section');
    const lesson = learningPathState.lessons.find(
      (item) => item.slug === skillSection?.dataset.activeLessonSlug
    );
    const test = lesson?.extra?.grammarTest;
    const content = skillSection?.querySelector('.skill-view-content');
    const questionId = questionItem?.dataset.questionId;
    const question = test?.questions?.find((item) => String(item.id) === String(questionId));
    if (!question || !content || question.type !== 'ordering') return;

    const picks = [...questionItem.querySelectorAll('.grammar-test-order-select')].map((item) => ({
      itemId: item.dataset.itemId,
      position: Number(item.value)
    }));
    const positions = picks.map((item) => item.position);
    const complete = picks.length > 0 && picks.every((item) => item.position) && new Set(positions).size === positions.length;
    const runtime = getGrammarTestRuntime(lesson);
    if (complete) {
      runtime.answers[question.id] = picks
        .slice()
        .sort((a, b) => a.position - b.position)
        .map((item) => item.itemId);
    } else {
      delete runtime.answers[question.id];
    }
    updateGrammarChallengeProgress(content, test, runtime, isFrenchTargetLanguage());
  });
}

let draggedGrammarOrderItem = null;

function refreshGrammarOrderNumbers(list) {
  list?.querySelectorAll('.grammar-test-order-item').forEach((item, index) => {
    const number = item.querySelector('.grammar-test-order-number');
    if (number) number.textContent = String(index + 1);
  });
}

async function syncGrammarReconstruction(item) {
  const questionItem = item?.closest('.grammar-test-question-item');
  const skillSection = item?.closest('.skill-view-section');
  const lesson = learningPathState.lessons.find(
    (candidate) => candidate.slug === skillSection?.dataset.activeLessonSlug
  );
  const content = skillSection?.querySelector('.skill-view-content');
  const test = lesson?.extra?.grammarTest;
  const question = test?.questions?.find(
    (candidate) => String(candidate.id) === String(questionItem?.dataset.questionId)
  );
  if (!lesson || !content || question?.interaction !== 'reconstruction') return;

  const answerZone = questionItem.querySelector('[data-order-zone="answer"]');
  const order = [...answerZone.querySelectorAll('.grammar-test-order-item')].map(
    (piece) => piece.dataset.itemId
  );
  const runtime = getGrammarTestRuntime(lesson);
  delete runtime.questionResults?.[question.id];
  questionItem.querySelector('.grammar-question-feedback')?.remove();
  answerZone.classList.remove('is-correct', 'is-incorrect');

  if (order.length === (question.items || []).length) {
    runtime.answers[question.id] = order;
  } else {
    delete runtime.answers[question.id];
  }
  updateGrammarChallengeProgress(
    content,
    test,
    runtime,
    isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
  );
  if (order.length !== (question.items || []).length) return;

  try {
    const response = await authFetch(
      `${backendBaseUrl}/api/lessons/${lesson.slug}/check-question`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ questionId: question.id, answer: order })
      }
    );
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(
        data.error ||
          (isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
            ? 'Impossible de vérifier la réponse.'
            : 'No se pudo comprobar la respuesta.')
      );
    }
    const correct = Boolean(data.correct);
    runtime.questionResults ||= {};
    runtime.questionResults[question.id] = { correct };
    answerZone.classList.add(correct ? 'is-correct' : 'is-incorrect');
    answerZone.insertAdjacentHTML(
      'afterend',
      `<p class="grammar-question-feedback ${correct ? 'is-correct' : 'is-incorrect'}" role="status">${
        correct
          ? isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
            ? '✓ Excellent !'
            : '✓ ¡Excelente!'
          : isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
            ? '✕ Essaie une autre combinaison.'
            : '✕ Prueba otra combinación.'
      }</p>`
    );
    window.requestAnimationFrame(() => window.playExerciseFeedbackSound?.(correct));
  } catch (error) {
    showHomeToast(
      error.message ||
        (isFrenchExerciseFeedbackInTargetLanguage(lesson.level)
          ? 'Impossible de vérifier la réponse.'
          : 'No se pudo comprobar la respuesta.')
    );
  }
}

document.addEventListener('dragstart', (event) => {
  const item = event.target.closest('.grammar-test-order-item');
  if (!item) return;
  draggedGrammarOrderItem = item;
  item.classList.add('is-dragging');
  event.dataTransfer.effectAllowed = 'move';
});

document.addEventListener('dragover', (event) => {
  const list = event.target.closest('.grammar-test-order-list');
  if (!list || !draggedGrammarOrderItem) return;
  event.preventDefault();
  const target = event.target.closest('.grammar-test-order-item');
  if (target && target !== draggedGrammarOrderItem) {
    const rect = target.getBoundingClientRect();
    const sameRow = Math.abs(event.clientY - (rect.top + rect.height / 2)) < rect.height / 2;
    const insertAfter = sameRow
      ? event.clientX > rect.left + rect.width / 2
      : event.clientY > rect.top + rect.height / 2;
    list.insertBefore(draggedGrammarOrderItem, insertAfter ? target.nextSibling : target);
  } else if (draggedGrammarOrderItem.parentElement !== list) {
    list.appendChild(draggedGrammarOrderItem);
  }
});

document.addEventListener('dragend', () => {
  const list = draggedGrammarOrderItem?.closest('.grammar-test-order-list');
  const item = draggedGrammarOrderItem;
  draggedGrammarOrderItem?.classList.remove('is-dragging');
  refreshGrammarOrderNumbers(list);
  draggedGrammarOrderItem = null;
  if (item?.classList.contains('grammar-reconstruction-chip')) {
    syncGrammarReconstruction(item);
  }
});

document.addEventListener('click', (event) => {
  const chip = event.target.closest('.grammar-reconstruction-chip');
  if (chip) {
    const questionItem = chip.closest('.grammar-test-question-item');
    const currentZone = chip.closest('[data-order-zone]');
    const destination =
      currentZone?.dataset.orderZone === 'bank'
        ? questionItem?.querySelector('[data-order-zone="answer"]')
        : questionItem?.querySelector('[data-order-zone="bank"]');
    destination?.appendChild(chip);
    syncGrammarReconstruction(chip);
    return;
  }
  const button = event.target.closest('.grammar-test-order-move');
  if (!button) return;
  const item = button.closest('.grammar-test-order-item');
  const list = item?.parentElement;
  if (!item || !list) return;
  if (button.dataset.orderMove === 'up' && item.previousElementSibling) {
    list.insertBefore(item, item.previousElementSibling);
  } else if (button.dataset.orderMove === 'down' && item.nextElementSibling) {
    list.insertBefore(item.nextElementSibling, item);
  }
  refreshGrammarOrderNumbers(list);
});

function setupLearningPathControls() {
  const languageSelect = document.getElementById('pathLanguageSelect');
  const levelSelect = document.getElementById('pathLevelSelect');
  const bridgeSelect = document.getElementById('pathBridgeSelect');

  languageSelect?.addEventListener('change', () => {
    const requestedLanguage = normalizeLanguageKey(languageSelect.value);

    // If the learner picks the current support language as L2, preserve both
    // useful choices by swapping the pair instead of rejecting the selection.
    // Example: Español (support) + Français (L2), then choosing Español as
    // L2 becomes Français (support) + Español (L2). This makes Spanish
    // directly selectable while keeping L1 and L2 distinct.
    if (
      requestedLanguage === learningPathState.bridgeLanguage &&
      requestedLanguage !== learningPathState.language
    ) {
      if (swapLearningPathLanguages()) return;
    }

    const level = levelSelect?.value || learningPathState.level;
    if (!setTargetLanguage(requestedLanguage, { level })) {
      languageSelect.value = learningPathState.language;
    }
  });
  levelSelect?.addEventListener('change', () => {
    const language = languageSelect?.value || learningPathState.language;
    const selectedLevel = levelSelect.value;
    const level = selectedLevel === 'PRE-A1' && !['english', 'french', 'spanish'].includes(language) ? 'A1' : selectedLevel;
    if (level !== selectedLevel) {
      levelSelect.value = level;
      showHomeToast('Pre-A1 visual está disponible en inglés, francés y español.');
    }
    loadLearningPath({ language, level });
    savePreferences(language, level);
  });
  bridgeSelect?.addEventListener('change', () => {
    if (setBridgeLanguage(bridgeSelect.value)) {
      try {
        localStorage.setItem(L1_CONFIRMED_STORAGE_KEY, bridgeSelect.value);
      } catch {
        // Preference persistence already has its own backend/local fallback.
      }
      const suggestion = document.getElementById('l1LanguageSuggestion');
      if (suggestion) suggestion.hidden = true;
    }
  });
  document.getElementById('confirmL1SuggestionBtn')?.addEventListener('click', () => {
    if (!pendingL1Suggestion || !setBridgeLanguage(pendingL1Suggestion)) return;
    try {
      localStorage.setItem(L1_CONFIRMED_STORAGE_KEY, pendingL1Suggestion);
    } catch {
      // The confirmed selection is still persisted through savePreferences().
    }
    const suggestion = document.getElementById('l1LanguageSuggestion');
    if (suggestion) suggestion.hidden = true;
    showHomeToast('Lengua materna confirmada.');
  });
  document.getElementById('chooseL1ManuallyBtn')?.addEventListener('click', () => {
    const suggestion = document.getElementById('l1LanguageSuggestion');
    if (suggestion) suggestion.hidden = true;
    bridgeSelect?.focus();
    bridgeSelect?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
  document
    .getElementById('pathSwapLanguagesBtn')
    ?.addEventListener('click', () => swapLearningPathLanguages());
  updateLanguagePreviewSelection();
}

function initScrollReveal() {
  const elements = document.querySelectorAll(
    '.section-heading, .features-grid article, .plan, .missions-panel, .badges-panel, .goal-card, .download-box, .course-card, .how-it-works-step'
  );
  if (!elements.length) return;

  if (!('IntersectionObserver' in window)) {
    elements.forEach((el) => el.classList.add('is-visible'));
    return;
  }

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      });
    },
    { threshold: 0.15, rootMargin: '0px 0px -60px 0px' }
  );

  elements.forEach((el, index) => {
    el.classList.add('reveal-on-scroll');
    el.style.transitionDelay = `${(index % 4) * 60}ms`;
    observer.observe(el);
  });
}

// ---------------------------------------------------------------------
// Translator (#translator) - English/French/Spanish only, matching the rest
// of the public frontend. Always calls POST /api/translator (never Azure
// directly - see lib/translatorService.js); when that route reports
// configured:false this shows the pending-configuration message instead of
// ever fabricating a translation.
// Local-only translation history (never sent anywhere) - last
// TRANSLATOR_HISTORY_LIMIT entries, most recent first. Kept as a plain
// localStorage array rather than anything server-side, matching "historial
// local opcional" - it's a convenience for the student's own browser, not
// account data.
const TRANSLATOR_HISTORY_KEY = 'andergo_translator_history';
const TRANSLATOR_HISTORY_LIMIT = 20;

function loadTranslatorHistory() {
  try {
    const raw = localStorage.getItem(TRANSLATOR_HISTORY_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveTranslatorHistoryEntry(entry) {
  try {
    const history = [entry, ...loadTranslatorHistory()].slice(0, TRANSLATOR_HISTORY_LIMIT);
    localStorage.setItem(TRANSLATOR_HISTORY_KEY, JSON.stringify(history));
    return history;
  } catch {
    return loadTranslatorHistory();
  }
}

function clearTranslatorHistory() {
  try {
    localStorage.removeItem(TRANSLATOR_HISTORY_KEY);
  } catch {
    /* ignore - private browsing / storage disabled */
  }
}

// Prefills the Traductor's own source/target selects from the platform's
// current bridge/target pair the first time the student lands on #translator
// in a given session - see translatorUserAdjustedPair's comment for why this
// stops once the student has picked a pair inside the Traductor itself.
// bridge->target (not the other way) matches the rest of the app's "Puente
// -> Objetivo" framing: translate what I want to say FROM my own language
// INTO the one I'm learning.
function syncTranslatorLanguagesFromState() {
  if (translatorUserAdjustedPair) return;
  const sourceSelect = document.getElementById('translatorSourceLang');
  const targetSelect = document.getElementById('translatorTargetLang');
  if (!sourceSelect || !targetSelect) return;
  const bridge = learningPathState.bridgeLanguage;
  const target = learningPathState.language;
  if ([...sourceSelect.options].some((opt) => opt.value === bridge)) sourceSelect.value = bridge;
  if ([...targetSelect.options].some((opt) => opt.value === target)) targetSelect.value = target;
}

// Opens the Traductor pre-filled with context from another view (Reading/
// Grammar/Vocabulary/Speaking's "Traducir" shortcuts) - the sibling of
// openTutorDrawer() for the Traductor. Defaults to translating FROM the
// target language INTO the bridge language (the "explain this to me"
// direction those shortcuts need), overridable via overrides.sourceLanguage/
// targetLanguage. overrides.returnHash/returnLabel wire up
// #translatorReturnLink so the student can get back to exactly where they
// were instead of hunting through the nav.
function openTranslator(overrides = {}) {
  const sourceSelect = document.getElementById('translatorSourceLang');
  const targetSelect = document.getElementById('translatorTargetLang');
  const input = document.getElementById('translatorInput');
  const returnLink = document.getElementById('translatorReturnLink');
  const mode = ['translate', 'corrector', 'phonetics'].includes(overrides.mode)
    ? overrides.mode
    : 'translate';

  if (mode === 'translate') {
    const sourceLang = overrides.sourceLanguage || learningPathState.language;
    const targetLang = overrides.targetLanguage || learningPathState.bridgeLanguage;
    if (sourceSelect && [...sourceSelect.options].some((opt) => opt.value === sourceLang)) {
      sourceSelect.value = sourceLang;
    }
    if (targetSelect && [...targetSelect.options].some((opt) => opt.value === targetLang)) {
      targetSelect.value = targetLang;
    }
    // An explicit shortcut always wins over the generic sync for the rest of
    // this session - the student (or the lesson view on their behalf) just
    // chose this pair on purpose.
    translatorUserAdjustedPair = true;

    if (input && overrides.text) {
      const maxLength = Number(input.getAttribute('maxlength')) || 1000;
      input.value = String(overrides.text).slice(0, maxLength);
      input.dispatchEvent(new Event('input'));
    }
  }

  if (returnLink) {
    if (overrides.returnHash) {
      translatorReturnContext = {
        hash: overrides.returnHash,
        label: overrides.returnLabel || 'Volver a la lección'
      };
      returnLink.textContent = `‹ ${translatorReturnContext.label}`;
      returnLink.hidden = false;
    } else {
      translatorReturnContext = null;
      returnLink.hidden = true;
    }
  }

  if (window.location.hash !== '#translator') history.pushState(null, '', '#translator');
  showView('translator');

  const toolTab = document.querySelector(`#translatorTabs .skill-tab-button[data-skill="${mode}"]`);
  if (toolTab) activateSkillTab(toolTab, { scroll: false });

  if (mode === 'corrector' || mode === 'phonetics') {
    const languageSelect = document.getElementById(
      mode === 'corrector' ? 'correctorLangSelect' : 'phoneticsLangSelect'
    );
    const toolInput = document.getElementById(
      mode === 'corrector' ? 'correctorInput' : 'phoneticsInput'
    );
    const toolLanguage = overrides.toolLanguage || learningPathState.language;
    if (languageSelect && [...languageSelect.options].some((opt) => opt.value === toolLanguage)) {
      languageSelect.value = toolLanguage;
      languageSelect.dispatchEvent(new Event('change'));
    }
    if (toolInput && overrides.text) {
      const maxLength = Number(toolInput.getAttribute('maxlength')) || 1000;
      toolInput.value = String(overrides.text).slice(0, maxLength);
      toolInput.dispatchEvent(new Event('input'));
    }
  }
}

// Builds the Traductor's source/target <option> lists from the central
// src/js/translator-languages.js list instead of two hand-duplicated
// <option> blocks in index.html (Fase 1 spec: "sustituye la lista rígida
// por una lista central de idiomas admitidos"). Only DeepL-supported
// languages appear - Haitian Creole/Hawaiian stay out of the selector
// entirely until a compatible provider exists (spec item 7, "fuera del
// selector" option). Idempotent (only (re)populates when empty), same
// pattern as verbs-view.js's ensureConjugatorSelectOptions - safe to call
// every time setupTranslator() runs without disturbing a live selection.
function populateTranslatorLanguageSelects() {
  const sourceSelect = document.getElementById('translatorSourceLang');
  const targetSelect = document.getElementById('translatorTargetLang');
  const languages = window.AndergoTranslatorLanguages?.getSelectableLanguages() || [];
  if (!languages.length) return;

  const optionHtml = (lang) => `<option value="${escapeHtml(lang.key)}">${lang.flag} ${escapeHtml(lang.label)}</option>`;

  if (sourceSelect && sourceSelect.options.length <= 1) {
    sourceSelect.innerHTML =
      '<option value="auto">Detectar idioma</option>' + languages.map(optionHtml).join('');
    sourceSelect.value = 'auto';
  }
  if (targetSelect && !targetSelect.options.length) {
    targetSelect.innerHTML = languages.map(optionHtml).join('');
    // 'spanish' matches the Traductor's long-standing default target
    // (English/French bridge students translating into Spanish) - falls
    // back to the first selectable language if that ever changes.
    targetSelect.value = languages.some((lang) => lang.key === 'spanish') ? 'spanish' : languages[0].key;
  }
}

function setupTranslator() {
  populateTranslatorLanguageSelects();
  const sourceSelect = document.getElementById('translatorSourceLang');
  const targetSelect = document.getElementById('translatorTargetLang');
  const swapBtn = document.getElementById('translatorSwapBtn');
  const input = document.getElementById('translatorInput');
  const output = document.getElementById('translatorOutput');
  const charCount = document.getElementById('translatorCharCount');
  const clearBtn = document.getElementById('translatorClearBtn');
  const copyBtn = document.getElementById('translatorCopyBtn');
  const listenSourceBtn = document.getElementById('translatorListenSourceBtn');
  const listenOutputBtn = document.getElementById('translatorListenOutputBtn');
  const stopBtn = document.getElementById('translatorStopBtn');
  const submitBtn = document.getElementById('translatorSubmitBtn');
  const status = document.getElementById('translatorStatus');
  const detectedEl = document.getElementById('translatorDetected');
  const historyList = document.getElementById('translatorHistoryList');
  const historyClearBtn = document.getElementById('translatorHistoryClearBtn');
  const suggestionsList = document.getElementById('translatorSuggestions');
  const suggestionsToggle = document.getElementById('translatorSuggestionsToggle');
  if (!input || !output || !submitBtn || !status) return;

  const MAX_LENGTH = Number(input.getAttribute('maxlength')) || 1000;
  let translatorPlayback = null;

  function setTranslatorListenState(button, playing) {
    if (!button) return;
    button.classList.toggle('is-playing', playing);
    button.setAttribute('aria-pressed', String(playing));
    button.textContent = playing ? '⏹ Detener' : '🔊 Escuchar';
    button.setAttribute(
      'aria-label',
      playing
        ? 'Detener reproducción'
        : button === listenOutputBtn
          ? 'Escuchar traducción'
          : 'Escuchar texto original'
    );
  }

  function stopTranslatorPlayback() {
    if (!translatorPlayback) {
      window.speechSynthesis?.cancel();
      stopBtn?.classList.remove('is-active');
      return;
    }
    const current = translatorPlayback;
    translatorPlayback = null;
    window.speechSynthesis?.cancel();
    setTranslatorListenState(current.button, false);
    stopBtn?.classList.remove('is-active');
  }

  function toggleTranslatorPlayback(button, text, locale) {
    if (!text?.trim()) return;
    if (translatorPlayback?.button === button) {
      stopTranslatorPlayback();
      return;
    }
    stopTranslatorPlayback();
    const requestedBase = String(locale || '').toLocaleLowerCase().split('-')[0];
    // No system/browser ships a Haitian Creole voice by default. Until one is
    // installed, French is the closest-sounding synthesizer voice available
    // almost everywhere, so it reads the Creole text as a best-effort
    // approximation instead of staying silent.
    const effectiveLocale =
      requestedBase === 'ht' && !getReadingVoicesForLocale(locale).length ? 'fr-FR' : locale;
    if (effectiveLocale !== locale) {
      setStatus(
        'La voz en kreyòl no está instalada en este dispositivo. Usando pronunciación en francés como aproximación.',
        'is-loading'
      );
    }
    const playback = { button };
    translatorPlayback = playback;
    setTranslatorListenState(button, true);
    stopBtn?.classList.add('is-active');
    const utterance = speakText(text, {
      locale: effectiveLocale,
      onEnd: () => {
        if (translatorPlayback !== playback) return;
        translatorPlayback = null;
        setTranslatorListenState(button, false);
      }
    });
    if (!utterance && translatorPlayback === playback) {
      translatorPlayback = null;
      setTranslatorListenState(button, false);
    }
  }

  const setStatus = (text, mode) => {
    status.textContent = text;
    status.classList.remove('is-loading', 'is-success', 'is-unavailable');
    if (mode) status.classList.add(mode);
  };

  // Keep the loading state confined to the action that triggered it.  A
  // disabled submit button alone was being rendered inconsistently by some
  // browsers, making the whole source action row look like punctuation.
  const submitIdleLabel = submitBtn.textContent.trim();
  const setTranslationBusy = (busy) => {
    submitBtn.disabled = busy;
    submitBtn.classList.toggle('is-translating', busy);
    submitBtn.setAttribute('aria-busy', String(busy));
    submitBtn.innerHTML = busy
      ? '<span class="translator-button-spinner" aria-hidden="true"></span><span>Traduciendo…</span>'
      : submitIdleLabel;
  };

  const updateCharCount = () => {
    if (charCount) charCount.textContent = `${input.value.length} / ${MAX_LENGTH}`;
  };

  // Keep short translations compact, then expand both columns together as
  // either text grows. The cap preserves access to the actions on ordinary
  // screens while still giving long paragraphs substantially more room.
  const syncTranslatorTextareaHeights = () => {
    const textareas = [input, output].filter(Boolean);
    textareas.forEach((textarea) => {
      textarea.style.height = 'auto';
    });
    const contentHeight = Math.max(...textareas.map((textarea) => textarea.scrollHeight), 220);
    const height = Math.min(contentHeight + 2, 480);
    textareas.forEach((textarea) => {
      textarea.style.height = `${height}px`;
    });
  };

  const renderHistory = () => {
    if (!historyList) return;
    const history = loadTranslatorHistory();
    historyList.innerHTML = history.length
      ? history
          .map(
            (entry) => `
        <li class="translator-history-item">
          <span class="translator-history-pair">${escapeHtml(languageDisplayNames[entry.sourceLanguage] || entry.sourceLanguage || 'Auto')} → ${escapeHtml(languageDisplayNames[entry.targetLanguage] || entry.targetLanguage || '')}</span>
          <span class="translator-history-source">${escapeHtml(entry.source)}</span>
          <span class="translator-history-target">${escapeHtml(entry.target)}</span>
        </li>`
          )
          .join('')
      : '<li class="translator-history-empty">Sin traducciones recientes.</li>';
  };

  // ---------------------------------------------------------------------
  // Predictive text (Fase 4) - English/Spanish/French only, purely local
  // (src/js/translator-predictive.js: a curated word list + a handful of
  // common two-word sequences, never DeepL, never an AI call per
  // keystroke). Distinguishes three suggestion kinds via each item's
  // `type` (autocompletado/corrección ortográfica/predicción contextual -
  // see that module's getSuggestions()); tagged in the DOM
  // (data-type) so CSS can render them distinctly.
  // ---------------------------------------------------------------------
  const PREDICTIVE_ENABLED_KEY = 'andergo_translator_predictive_enabled';
  const PREDICTIVE_LANGUAGES = new Set(['english', 'spanish', 'french']);
  const SUGGESTIONS_DEBOUNCE_MS = 200;

  let suggestionItems = [];
  let activeSuggestionIndex = -1;
  let suggestionsDebounceId = null;

  function isPredictiveEnabled() {
    try {
      return localStorage.getItem(PREDICTIVE_ENABLED_KEY) !== 'false';
    } catch {
      return true;
    }
  }

  function renderSuggestions(items) {
    suggestionItems = items;
    activeSuggestionIndex = -1;
    if (!suggestionsList) return;
    if (!items.length) {
      suggestionsList.hidden = true;
      suggestionsList.innerHTML = '';
      input.setAttribute('aria-expanded', 'false');
      return;
    }
    // Small visual tag per suggestion kind - autocompletado has none (the
    // default/expected case), corrección ortográfica gets ✎, predicción
    // contextual gets →, puntuación gets ·, so they stay visually distinct.
    const typeGlyph = { spelling: '✎ ', contextual: '→ ', punctuation: '· ' };
    suggestionsList.innerHTML = items
      .map(
        (item, index) => `
        <li class="translator-suggestion-item" data-index="${index}" data-type="${escapeHtml(item.type)}" role="option" aria-selected="false">${typeGlyph[item.type] || ''}${escapeHtml(item.text)}</li>`
      )
      .join('');
    suggestionsList.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }

  function hideSuggestions() {
    renderSuggestions([]);
  }

  function updateSuggestionHighlight() {
    if (!suggestionsList) return;
    suggestionsList.querySelectorAll('.translator-suggestion-item').forEach((el, index) => {
      const active = index === activeSuggestionIndex;
      el.classList.toggle('is-active', active);
      el.setAttribute('aria-selected', String(active));
    });
  }

  // Replaces only the word currently being typed (or, for a contextual
  // suggestion, inserts the next word right after the caret) - never
  // touches the rest of the text, and always leaves a trailing space so
  // the student can keep typing immediately.
  function acceptSuggestion(index) {
    const item = suggestionItems[index];
    if (!item) return;
    const caret = input.selectionStart ?? input.value.length;
    const before = input.value.slice(0, caret);
    const after = input.value.slice(caret);
    // Punctuation attaches directly to the word just typed (no leading
    // space) instead of replacing/completing it like a word suggestion -
    // same convention as the Corrector's predictive punctuation. ¿…?/¡…!
    // insert BOTH marks: the opening one right at the current sentence's
    // start (only if it isn't already there) and the closing one here,
    // leaving the caret at the end so the student keeps typing normally.
    if (item.type === 'punctuation') {
      const closing = item.text === '¿…?' ? '?' : item.text === '¡…!' ? '!' : item.text;
      let nextBefore = before.replace(/\s+$/, '');
      if ((item.text === '¿…?' || item.text === '¡…!') && (sourceSelect?.value || 'english') === 'spanish') {
        const opening = item.text[0];
        const sentenceStart = Math.max(nextBefore.lastIndexOf('.'), nextBefore.lastIndexOf('!'), nextBefore.lastIndexOf('?')) + 1;
        const prefix = nextBefore.slice(0, sentenceStart);
        const sentence = nextBefore.slice(sentenceStart).trimStart();
        if (sentence && !sentence.startsWith(opening)) nextBefore = `${prefix}${prefix && !/\s$/.test(prefix) ? ' ' : ''}${opening}${sentence}`;
      }
      nextBefore = `${nextBefore}${closing} `;
      input.value = nextBefore + after.replace(/^\s+/, '');
      input.setSelectionRange(nextBefore.length, nextBefore.length);
      hideSuggestions();
      input.dispatchEvent(new Event('input'));
      input.focus();
      return;
    }
    const wordMatch = /(\S*)$/.exec(before);
    const wordStart = caret - (wordMatch ? wordMatch[1].length : 0);
    const newBefore = `${before.slice(0, wordStart)}${item.text} `;
    input.value = newBefore + after;
    const newCaret = newBefore.length;
    input.setSelectionRange(newCaret, newCaret);
    hideSuggestions();
    input.dispatchEvent(new Event('input'));
    input.focus();
  }

  function scheduleSuggestions() {
    window.clearTimeout(suggestionsDebounceId);
    if (!isPredictiveEnabled()) {
      hideSuggestions();
      return;
    }
    const language = sourceSelect?.value;
    const engine = window.AndergoTranslatorPredictive;
    if (!engine || !language || !PREDICTIVE_LANGUAGES.has(language)) {
      hideSuggestions();
      return;
    }
    suggestionsDebounceId = window.setTimeout(() => {
      const caret = input.selectionStart ?? input.value.length;
      const before = input.value.slice(0, caret);
      const wordSuggestions = engine.getSuggestions(language, before).slice(0, 3);
      // Offered right after any finished word/closing parenthesis that
      // doesn't already end in punctuation - a Spanish source additionally
      // offers the inverted opening+closing pair for questions/exclamations,
      // built and inserted together by acceptSuggestion() above.
      const trimmed = before.trimEnd();
      const canPunctuate = /[\p{L}\p{N}\)]$/u.test(trimmed) && !/[.!?,:;…]$/.test(trimmed);
      const punctuation = canPunctuate
        ? (language === 'spanish'
            ? ['.', ',', ':', ';', '…', '¿…?', '¡…!']
            : ['.', ',', ':', ';', '…', '?', '!']
          ).map((text) => ({ type: 'punctuation', text }))
        : [];
      renderSuggestions([...wordSuggestions, ...punctuation]);
    }, SUGGESTIONS_DEBOUNCE_MS);
  }

  input.addEventListener('input', scheduleSuggestions);
  // A short delay (not an immediate hide) lets a mousedown on a suggestion
  // (see the delegated listener below, which itself preventDefault()s the
  // mousedown so focus never actually leaves the textarea) register before
  // any blur-driven hide could beat it to it.
  input.addEventListener('blur', () => {
    window.setTimeout(hideSuggestions, 100);
  });

  suggestionsList?.addEventListener('mousedown', (event) => {
    const item = event.target.closest('.translator-suggestion-item');
    if (!item) return;
    event.preventDefault(); // keep focus (and the caret) in the textarea
    acceptSuggestion(Number(item.dataset.index));
  });

  if (suggestionsToggle) {
    suggestionsToggle.checked = isPredictiveEnabled();
    suggestionsToggle.addEventListener('change', () => {
      try {
        localStorage.setItem(PREDICTIVE_ENABLED_KEY, String(suggestionsToggle.checked));
      } catch {
        // Storage unavailable - the toggle still works for this session,
        // it just won't be remembered next visit.
      }
      if (!suggestionsToggle.checked) hideSuggestions();
    });
  }

  input.addEventListener('input', updateCharCount);
  input.addEventListener('input', syncTranslatorTextareaHeights);
  updateCharCount();
  syncTranslatorTextareaHeights();
  renderHistory();

  // "Textos muy cortos" (Fase 2 spec): DeepL's own auto-detection is far
  // less reliable on a couple of words than on a full sentence - never
  // trust it blindly. Below this rough word-count threshold, the
  // detected-language line adds an explicit caution; either way, whenever
  // sourceLanguage was 'auto' this also renders a one-click way to pick the
  // real language and retranslate with it ("permitir corregirlo antes de
  // volver a traducir") instead of only ever showing the guess as plain
  // text.
  const SHORT_TEXT_WORD_THRESHOLD = 3;

  function renderTranslatorDetectedLanguage(detectedKey, originalText) {
    if (!detectedEl) return;
    const languages = window.AndergoTranslatorLanguages?.getSelectableLanguages() || [];
    const label = languageDisplayNames[detectedKey] || detectedKey;
    const wordCount = originalText.trim().split(/\s+/).filter(Boolean).length;
    const isShortText = wordCount > 0 && wordCount <= SHORT_TEXT_WORD_THRESHOLD;

    const cautionHtml = isShortText
      ? '<span class="translator-detected-caution">Los textos muy cortos pueden confundir la detección automática.</span> '
      : '';

    const optionsHtml = languages
      .map(
        (lang) =>
          `<option value="${escapeHtml(lang.key)}"${lang.key === detectedKey ? ' selected' : ''}>${lang.flag} ${escapeHtml(lang.label)}</option>`
      )
      .join('');

    detectedEl.innerHTML = `
      ${cautionHtml}<span>Idioma detectado: <strong>${escapeHtml(label)}</strong></span>
      <span class="translator-detected-correct">
        <label for="translatorDetectedCorrectSelect">¿No es correcto?</label>
        <select id="translatorDetectedCorrectSelect">${optionsHtml}</select>
        <button type="button" class="secondary-btn" id="translatorDetectedCorrectBtn">Volver a traducir</button>
      </span>`;
    detectedEl.hidden = false;
  }

  // Delegated (detectedEl's own innerHTML is rebuilt on every detection, so
  // a listener bound directly to the button would be orphaned each time).
  detectedEl?.addEventListener('click', (event) => {
    if (!event.target.closest('#translatorDetectedCorrectBtn')) return;
    const correctSelect = document.getElementById('translatorDetectedCorrectSelect');
    const chosen = correctSelect?.value;
    if (!chosen || !sourceSelect) return;
    // The student just told us the real source language - use it explicitly
    // from now on instead of leaving 'auto' to guess wrong again.
    sourceSelect.value = chosen;
    translatorUserAdjustedPair = true;
    runTranslation();
  });

  // recognition.lang is fixed for the life of a SpeechRecognition instance -
  // a source-language switch mid-dictation would otherwise keep listening
  // in the old language. Any manual change here also opts this session out
  // of syncTranslatorLanguagesFromState()'s auto-sync (see its comment) -
  // the student picked this pair on purpose.
  sourceSelect?.addEventListener('change', () => {
    stopTranslatorDictation();
    translatorUserAdjustedPair = true;
    // Suggestions are language-specific and tied to whatever was typed
    // under the old language - stale once the source changes; a fresh set
    // (if any) is computed on the next keystroke.
    hideSuggestions();
  });
  targetSelect?.addEventListener('change', () => {
    translatorUserAdjustedPair = true;
  });

  const returnLink = document.getElementById('translatorReturnLink');
  returnLink?.addEventListener('click', (event) => {
    event.preventDefault();
    if (!translatorReturnContext) return;
    const hash = translatorReturnContext.hash;
    translatorReturnContext = null;
    returnLink.hidden = true;
    if (window.location.hash !== hash) history.pushState(null, '', hash);
    showView(getViewFromHash());
  });

  swapBtn?.addEventListener('click', () => {
    stopTranslatorDictation();
    stopTranslatorPlayback();
    hideSuggestions();
    // Swapping the selects only makes sense when the source is a real
    // language - with 'auto' there is nothing known to place in the target
    // slot, so leave both selects as-is and just swap the text either way.
    if (sourceSelect.value !== 'auto' && targetSelect) {
      const sourceValue = sourceSelect.value;
      sourceSelect.value = targetSelect.value;
      targetSelect.value = sourceValue;
    }
    const inputValue = input.value;
    input.value = output.value;
    output.value = inputValue;
    updateCharCount();
    syncTranslatorTextareaHeights();
  });

  clearBtn?.addEventListener('click', () => {
    // Otherwise the next dictation 'result' event would overwrite the
    // clear with the baseText captured when dictation started.
    stopTranslatorDictation();
    stopTranslatorPlayback();
    hideSuggestions();
    input.value = '';
    output.value = '';
    if (detectedEl) detectedEl.hidden = true;
    updateCharCount();
    syncTranslatorTextareaHeights();
    setStatus('Listo');
  });

  copyBtn?.addEventListener('click', async () => {
    if (!output.value) return;
    try {
      await navigator.clipboard.writeText(output.value);
      showHomeToast('Traducción copiada.');
    } catch {
      showHomeToast('No se pudo copiar la traducción.');
    }
  });

  listenSourceBtn?.addEventListener('click', () => {
    const lang = sourceSelect?.value;
    toggleTranslatorPlayback(
      listenSourceBtn,
      input.value,
      lang && lang !== 'auto' ? LANGUAGE_LOCALES[lang] : undefined
    );
  });

  listenOutputBtn?.addEventListener('click', () => {
    toggleTranslatorPlayback(listenOutputBtn, output.value, LANGUAGE_LOCALES[targetSelect?.value]);
  });
  document.getElementById('tutorDrawerPrompt')?.addEventListener('input', (event) => {
    if (event.isTrusted && tutorDictation.status !== 'listening') {
      delete event.currentTarget.dataset.tutorInputSource;
    }
  });

  stopBtn?.addEventListener('click', () => {
    const wasActive = Boolean(translatorPlayback) || translatorDictation.status === 'listening';
    stopTranslatorPlayback();
    stopTranslatorDictation();
    stopBtn.classList.remove('is-active');
    if (wasActive) setStatus('Reproducción detenida.');
  });

  historyClearBtn?.addEventListener('click', () => {
    clearTranslatorHistory();
    renderHistory();
  });

  // Shared by the Traducir button, Enter-to-translate, and the ~2s
  // auto-translate after voice dictation (startTranslatorDictation) - one
  // place decides "can we translate right now", so none of those three
  // entry points can double-submit or send empty content.
  async function runTranslation() {
    if (submitBtn.disabled) return; // already in flight - never a second request
    hideSuggestions();
    stopTranslatorPlayback();

    // Manual translate (Enter or the Traducir button) while the mic is
    // still listening: grabs whatever's in the textarea right now (already
    // live-updated with interim results) and stops the recognizer, marking
    // its 'end' handler to skip its own auto-translate so this one is never
    // duplicated.
    if (translatorDictation.status === 'listening') {
      translatorDictationManualSendSuppressed = true;
      stopTranslatorDictationRecognizer();
    }

    // A stale dictation message (e.g. "No se entendió el audio.") from an
    // earlier voice attempt must never linger once the student translates
    // by any means (typing + Enter/Traducir included) - it reads as if the
    // translation that just succeeded had failed.
    setTranslatorDictateStatusText('');

    const text = input.value.trim();
    if (!text) {
      setStatus('Escribe un texto para traducir.', 'is-unavailable');
      return;
    }

    const sourceLanguage = sourceSelect?.value || 'auto';
    const targetLanguage = targetSelect?.value || 'spanish';
    // Mirrors the backend's own check (POST /api/translate rejects this the
    // same way) - checked here too so guessing/typing doesn't need a round
    // trip to find out. 'auto' is never blocked - the real detected
    // language isn't known until DeepL responds.
    if (sourceLanguage !== 'auto' && sourceLanguage === targetLanguage) {
      setStatus(LanguagePair.t('translatorSelectDifferent', learningPathState.bridgeLanguage), 'is-unavailable');
      return;
    }

    if (detectedEl) detectedEl.hidden = true;
    setStatus(LanguagePair.t('translatorTranslating', learningPathState.bridgeLanguage), 'is-loading');
    setTranslationBusy(true);
    try {
      // auth: true - sends the session token when signed in, so the backend
      // can apply the Premium character limit instead of always treating
      // the request as a guest (see POST /api/translate's attachUserIfPresent).
      const data = await postJson(
        '/api/translate',
        { text, sourceLanguage, targetLanguage },
        { auth: true }
      );

      if (data.ok) {
        output.value = data.translatedText || '';
        syncTranslatorTextareaHeights();
        setStatus('Completada', 'is-success');
        if (sourceLanguage === 'auto' && data.detectedLanguage) {
          renderTranslatorDetectedLanguage(data.detectedLanguage, text);
        }
        saveTranslatorHistoryEntry({
          source: text,
          target: output.value,
          sourceLanguage: sourceLanguage === 'auto' ? data.detectedLanguage || 'auto' : sourceLanguage,
          targetLanguage,
          timestamp: Date.now()
        });
        renderHistory();
        // Only when this translation was itself triggered by speaking (see
        // startTranslatorDictation's 'end' handler) - a manual Enter/Traducir
        // translation never auto-plays, only the voice path does.
        if (translatorAutoPlayAfterVoice && output.value) {
          speakText(output.value, { locale: LANGUAGE_LOCALES[targetLanguage] });
        }
      } else if (data.configured === false) {
        output.value = '';
        syncTranslatorTextareaHeights();
        setStatus('El traductor está temporalmente en configuración.', 'is-unavailable');
      } else {
        output.value = '';
        syncTranslatorTextareaHeights();
        setStatus(data.message || 'No disponible. Inténtalo de nuevo.', 'is-unavailable');
      }
    } catch (error) {
      output.value = '';
      syncTranslatorTextareaHeights();
      setStatus(error.message || 'No disponible. Inténtalo de nuevo.', 'is-unavailable');
    } finally {
      translatorAutoPlayAfterVoice = false;
      setTranslationBusy(false);
    }
  }

  submitBtn.addEventListener('click', runTranslation);

  // Enter translates immediately; Shift+Enter inserts a newline (the
  // textarea's own default behavior, so it's left alone). No separate
  // "double submit" guard needed here beyond runTranslation's own
  // submitBtn.disabled check - a held-down Enter key or a click landing
  // mid-request both just no-op against an already-disabled button.
  //
  // Fase 4 adds three things ahead of that: Up/Down move the highlighted
  // suggestion, Escape closes the list without touching the text, and
  // Enter accepts the highlighted suggestion INSTEAD of translating - only
  // when one is actually highlighted; otherwise Enter still translates,
  // exactly as before.
  input.addEventListener('keydown', (event) => {
    if (suggestionItems.length && (event.key === 'ArrowDown' || event.key === 'ArrowUp')) {
      event.preventDefault();
      if (event.key === 'ArrowDown') {
        activeSuggestionIndex = (activeSuggestionIndex + 1) % suggestionItems.length;
      } else {
        activeSuggestionIndex = (activeSuggestionIndex - 1 + suggestionItems.length) % suggestionItems.length;
      }
      updateSuggestionHighlight();
      return;
    }
    if (suggestionItems.length && event.key === 'Escape') {
      event.preventDefault();
      hideSuggestions();
      return;
    }
    if (event.key === 'Enter' && !event.shiftKey && suggestionItems.length && activeSuggestionIndex >= 0) {
      event.preventDefault();
      acceptSuggestion(activeSuggestionIndex);
      return;
    }

    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    runTranslation();
  });

  translateTranslatorInputNow = runTranslation;
}

// ---------------------------------------------------------------------
// Corrector (#translator's "Corrector" tab, Fase 3) - a distinct mode from
// the Traductor above, never a target language: it fixes grammar/spelling
// in the SAME language the student wrote in and never translates (POST
// /api/correct-text, the AI Tutor cascade - never DeepL). English/Spanish/
// French only, per spec. Shares the .skill-tabs markup/behavior with Verbos
// and Tutor (activateSkillTab/initSkillTabsAccessibility), so switching
// tabs here needs no extra wiring beyond this function's own controls.
// ---------------------------------------------------------------------
function renderCorrectorHighlighted(correctedText, changes) {
  if (!Array.isArray(changes) || !changes.length) return escapeHtml(correctedText);

  // Wraps each changed fragment in <mark> without corrupting HTML-escaping:
  // a placeholder token (a Private-Use-Area marker, never in real text) is
  // inserted into the RAW text first, the whole string is escaped once,
  // then each token is swapped for its escaped, <mark>-wrapped fragment.
  const MARKER = String.fromCharCode(0xe000); // Private Use Area - never in real text
  let working = correctedText;
  const placeholders = [];
  changes.forEach((change, index) => {
    if (!change.corrected) return;
    const idx = working.indexOf(change.corrected);
    if (idx === -1) return;
    const token = `${MARKER}${index}${MARKER}`;
    working = working.slice(0, idx) + token + working.slice(idx + change.corrected.length);
    placeholders.push({ token, text: change.corrected });
  });

  let escaped = escapeHtml(working);
  placeholders.forEach(({ token, text }) => {
    escaped = escaped.split(token).join(`<mark>${escapeHtml(text)}</mark>`);
  });
  return escaped;
}

function setupInterpreter() {
  const langA = document.getElementById('interpreterLangA');
  const langB = document.getElementById('interpreterLangB');
  const swapBtn = document.getElementById('interpreterSwapBtn');
  const talkA = document.getElementById('interpreterTalkA');
  const talkB = document.getElementById('interpreterTalkB');
  const labelA = document.getElementById('interpreterTalkALabel');
  const labelB = document.getElementById('interpreterTalkBLabel');
  const stopBtn = document.getElementById('interpreterStopBtn');
  const clearBtn = document.getElementById('interpreterClearBtn');
  const status = document.getElementById('interpreterStatus');
  const conversation = document.getElementById('interpreterConversation');
  if (!langA || !langB || !talkA || !talkB || !status || !conversation || talkA.dataset.ready) return;
  talkA.dataset.ready = 'true';

  const labels = { english: 'English', spanish: 'Español', french: 'Français', italian: 'Italiano', portuguese: 'Português' };

  let recognition = null;
  let activeButton = null;
  let busy = false;
  let turns = [];
  let playbackToken = 0;

  const languageLabel = (key) => labels[key] || languageDisplayNames[key] || key;

  const setStatus = (message, mode = '') => {
    status.textContent = message;
    status.classList.remove('is-loading', 'is-success', 'is-unavailable');
    if (mode) status.classList.add(mode);
  };

  // Strict turn taking for hands-free interpreting: the other microphone
  // remains unavailable until the current speaker's translated voice ends.
  const setTurnControls = (activeSide = null) => {
    const isInTurn = Boolean(activeSide);
    talkA.disabled = isInTurn && activeSide !== 'a';
    talkB.disabled = isInTurn && activeSide !== 'b';
    langA.disabled = isInTurn;
    langB.disabled = isInTurn;
    if (swapBtn) swapBtn.disabled = isInTurn;
    talkA.classList.toggle('is-waiting', isInTurn && activeSide === 'b');
    talkB.classList.toggle('is-waiting', isInTurn && activeSide === 'a');
  };

  const updateLabels = () => {
    labelA.textContent = languageLabel(langA.value);
    labelB.textContent = languageLabel(langB.value);
    talkA.setAttribute('aria-label', `Hablar en ${languageLabel(langA.value)}`);
    talkB.setAttribute('aria-label', `Hablar en ${languageLabel(langB.value)}`);
  };

  // The automatic microphone is intentionally reserved for the learner's
  // bridge language (L1). A person speaking the other selected language
  // must always start their turn explicitly, preventing an unexpected mic
  // activation in a conversation with another person.
  const getL1Side = () => {
    const bridgeLanguage = typeof learningPathState !== 'undefined'
      ? learningPathState.bridgeLanguage
      : '';
    if (langA.value === bridgeLanguage) return 'a';
    if (langB.value === bridgeLanguage) return 'b';
    return null;
  };

  const renderTurns = () => {
    if (!turns.length) {
      conversation.innerHTML = '<div class="interpreter-empty"><span aria-hidden="true">🎧</span><p>Elige el botón del idioma que va a hablar para comenzar.</p></div>';
      return;
    }
    conversation.innerHTML = turns
      .map(
        (turn, index) => `<article class="interpreter-turn interpreter-turn--${turn.side}">
          <div class="interpreter-turn-head"><span>${escapeHtml(languageLabel(turn.sourceLanguage))}</span><span>→ ${escapeHtml(languageLabel(turn.targetLanguage))}</span></div>
          <p class="interpreter-turn-original">${escapeHtml(turn.original)}</p>
          <p class="interpreter-turn-translation">${escapeHtml(turn.translation)}</p>
          <div class="interpreter-turn-footer"><button type="button" class="secondary-btn interpreter-turn-repeat" data-interpreter-repeat="${index}" aria-label="Repetir la pronunciación en ${escapeHtml(languageLabel(turn.targetLanguage))}">🔊 Repetir</button></div>
        </article>`
      )
      .join('');
    conversation.scrollTop = conversation.scrollHeight;
  };

  const stop = () => {
    // Invalidate the end callback of an interrupted L2 utterance before
    // cancelling it. Otherwise a stale callback could re-open a turn after
    // the learner explicitly pressed Stop.
    playbackToken += 1;
    try { recognition?.stop(); } catch { /* inactive */ }
    recognition = null;
    activeButton?.classList.remove('is-listening');
    activeButton = null;
    window.speechSynthesis?.cancel();
    busy = false;
    setTurnControls();
    setStatus('Detenido.');
  };

  async function translateTurn(text, sourceLanguage, targetLanguage, side) {
    busy = true;
    const turnToken = ++playbackToken;
    setStatus('Interpretando…', 'is-loading');
    setTurnControls('playback');
    try {
      const data = await postJson('/api/translate', { text, sourceLanguage, targetLanguage }, { auth: true });
      if (turnToken !== playbackToken) return;
      if (!data.ok || !data.translatedText) throw new Error(data.message || 'No se pudo interpretar.');
      turns.push({ side, original: text, translation: data.translatedText, sourceLanguage, targetLanguage });
      renderTurns();
      setStatus(`Reproduciendo ${languageLabel(targetLanguage)}…`, 'is-success');
      const finishTurn = () => {
        if (turnToken !== playbackToken) return;
        busy = false;
        setTurnControls();
        const l1Side = getL1Side();
        // Hands-free mode is deliberately one-way: only a turn that began
        // in L1 continues automatically and is interpreted into L2. A
        // manually started L2 turn may still be translated once, but never
        // becomes an alternating automatic conversation.
        if (!l1Side || side !== l1Side) {
          setStatus('Listo. Toca el idioma que va a hablar.', 'is-success');
          return;
        }
        // startTurn() re-checks mic permission itself (silent after the
        // first grant) and Stop still interrupts this at any point.
        startTurn(l1Side);
      };
      speakText(data.translatedText, {
        locale: LANGUAGE_LOCALES[targetLanguage],
        onEnd: finishTurn
      });
    } catch (error) {
      if (turnToken !== playbackToken) return;
      busy = false;
      setTurnControls();
      setStatus(error.message || 'No se pudo interpretar. Inténtalo de nuevo.', 'is-unavailable');
    }
  }

  function repeatTranslation(index) {
    if (busy) return;
    const turn = turns[index];
    if (!turn?.translation) return;
    busy = true;
    const turnToken = ++playbackToken;
    setTurnControls('playback');
    setStatus(`Reproduciendo ${languageLabel(turn.targetLanguage)}…`, 'is-success');
    const sourceButton = turn.side === 'a' ? talkA : talkB;
    speakText(turn.translation, {
      locale: LANGUAGE_LOCALES[turn.targetLanguage],
      onEnd: () => {
        if (turnToken !== playbackToken) return;
        busy = false;
        setTurnControls();
        setStatus(`Listo. Puedes hablar en ${languageLabel(turn.sourceLanguage)}.`, 'is-success');
        sourceButton.focus({ preventScroll: true });
      }
    });
  }

  async function startTurn(side) {
    if (busy || recognition) return;
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) {
      setStatus('El reconocimiento de voz no está disponible en este navegador.', 'is-unavailable');
      return;
    }
    try {
      await ensureMicrophonePermission();
    } catch (error) {
      setTurnControls();
      setStatus(microphonePermissionMessage(error), 'is-unavailable');
      return;
    }
    const sourceLanguage = side === 'a' ? langA.value : langB.value;
    const targetLanguage = side === 'a' ? langB.value : langA.value;
    if (sourceLanguage === targetLanguage) {
      setTurnControls();
      setStatus('Selecciona dos idiomas diferentes.', 'is-unavailable');
      return;
    }
    const button = side === 'a' ? talkA : talkB;
    const instance = new Ctor();
    instance.lang = DICTATION_LANGUAGE_CODES[sourceLanguage] || LANGUAGE_LOCALES[sourceLanguage] || 'es-ES';
    instance.interimResults = true;
    instance.continuous = false;
    recognition = instance;
    activeButton = button;
    setTurnControls(side);
    button.classList.add('is-listening');
    setStatus(`Escuchando ${languageLabel(sourceLanguage)}…`, 'is-loading');
    let transcript = '';
    instance.addEventListener('result', (event) => {
      transcript = Array.from(event.results).map((result) => result[0].transcript).join(' ').trim();
      setStatus(transcript || `Escuchando ${languageLabel(sourceLanguage)}…`, 'is-loading');
    });
    instance.addEventListener('error', (event) => {
      if (event.error !== 'aborted') setStatus('No pude escuchar con claridad. Inténtalo de nuevo.', 'is-unavailable');
    });
    instance.addEventListener('end', () => {
      button.classList.remove('is-listening');
      if (recognition !== instance) return;
      recognition = null;
      activeButton = null;
      setTurnControls();
      if (transcript) translateTurn(transcript, sourceLanguage, targetLanguage, side);
      else setStatus('Toca Hablar e inténtalo de nuevo.');
    });
    instance.start();
  }

  talkA.addEventListener('click', () => startTurn('a'));
  talkB.addEventListener('click', () => startTurn('b'));
  conversation.addEventListener('click', (event) => {
    const repeatButton = event.target.closest('[data-interpreter-repeat]');
    if (!repeatButton) return;
    repeatTranslation(Number(repeatButton.dataset.interpreterRepeat));
  });
  stopBtn?.addEventListener('click', stop);
  clearBtn?.addEventListener('click', () => {
    stop();
    turns = [];
    renderTurns();
    setStatus('Conversación limpia.');
  });
  swapBtn?.addEventListener('click', () => {
    const value = langA.value;
    langA.value = langB.value;
    langB.value = value;
    updateLabels();
  });
  langA.addEventListener('change', updateLabels);
  langB.addEventListener('change', updateLabels);
  updateLabels();
  renderTurns();
}

function setupCorrector() {
  const langSelect = document.getElementById('correctorLangSelect');
  const input = document.getElementById('correctorInput');
  const output = document.getElementById('correctorOutput');
  const charCount = document.getElementById('correctorCharCount');
  const clearBtn = document.getElementById('correctorClearBtn');
  const talkBtn = document.getElementById('correctorTalkBtn');
  const copyBtn = document.getElementById('correctorCopyBtn');
  const listenBtn = document.getElementById('correctorListenBtn');
  const applyBtn = document.getElementById('correctorApplyBtn');
  const submitBtn = document.getElementById('correctorSubmitBtn');
  const status = document.getElementById('correctorStatus');
  const suggestionsList = document.getElementById('correctorSuggestions');
  if (!input || !output || !submitBtn || !status) return;

  const MAX_LENGTH = Number(input.getAttribute('maxlength')) || 1000;
  let lastCorrection = null; // { correctedText, explanation, changes } from the last successful call
  let recognition = null;
  let suggestionItems = [];
  let activeSuggestionIndex = -1;
  let suggestionsDebounceId = null;

  const setStatus = (text, mode) => {
    status.textContent = text;
    status.classList.remove('is-loading', 'is-success', 'is-unavailable');
    if (mode) status.classList.add(mode);
  };

  const updateCharCount = () => {
    if (charCount) charCount.textContent = `${input.value.length} / ${MAX_LENGTH}`;
  };

  const setResultActionsEnabled = (enabled) => {
    if (copyBtn) copyBtn.disabled = !enabled;
    if (listenBtn) listenBtn.disabled = !enabled;
    if (applyBtn) applyBtn.disabled = !enabled;
  };

  const resetOutput = () => {
    output.innerHTML = '<p class="skill-graph-empty">La corrección aparecerá aquí.</p>';
    lastCorrection = null;
    setResultActionsEnabled(false);
  };

  // The Corrector shares the translator's local prediction engine: it offers
  // word completions, spelling fixes and a likely next word without sending a
  // request on every keystroke. The full correction still happens only after
  // the learner chooses Corregir (or finishes dictating).
  const hideSuggestions = () => {
    suggestionItems = [];
    activeSuggestionIndex = -1;
    if (!suggestionsList) return;
    suggestionsList.hidden = true;
    suggestionsList.innerHTML = '';
    input.setAttribute('aria-expanded', 'false');
  };

  const renderSuggestions = (items) => {
    suggestionItems = items;
    activeSuggestionIndex = -1;
    if (!suggestionsList) return;
    if (!items.length) {
      hideSuggestions();
      return;
    }
    const typeGlyph = { spelling: '✎ ', contextual: '→ ', punctuation: '· ' };
    suggestionsList.innerHTML = items
      .map((item, index) => `
        <li class="translator-suggestion-item" data-index="${index}" data-type="${escapeHtml(item.type)}" role="option" aria-selected="false">${typeGlyph[item.type] || ''}${escapeHtml(item.text)}</li>`)
      .join('');
    suggestionsList.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  };

  const updateSuggestionHighlight = () => {
    suggestionsList?.querySelectorAll('.translator-suggestion-item').forEach((element, index) => {
      const active = index === activeSuggestionIndex;
      element.classList.toggle('is-active', active);
      element.setAttribute('aria-selected', String(active));
    });
  };

  const acceptSuggestion = (index) => {
    const item = suggestionItems[index];
    if (!item) return;
    const caret = input.selectionStart ?? input.value.length;
    const before = input.value.slice(0, caret);
    const after = input.value.slice(caret);
    if (item.type === 'punctuation') {
      const closing = item.text === '¿…?' ? '?' : item.text === '¡…!' ? '!' : item.text;
      let nextBefore = before.replace(/\s+$/, '');
      if ((item.text === '¿…?' || item.text === '¡…!') && (langSelect?.value || 'english') === 'spanish') {
        const opening = item.text[0];
        const sentenceStart = Math.max(nextBefore.lastIndexOf('.'), nextBefore.lastIndexOf('!'), nextBefore.lastIndexOf('?')) + 1;
        const prefix = nextBefore.slice(0, sentenceStart);
        const sentence = nextBefore.slice(sentenceStart).trimStart();
        if (sentence && !sentence.startsWith(opening)) nextBefore = `${prefix}${prefix && !/\s$/.test(prefix) ? ' ' : ''}${opening}${sentence}`;
      }
      nextBefore = `${nextBefore}${closing} `;
      input.value = nextBefore + after.replace(/^\s+/, '');
      input.setSelectionRange(nextBefore.length, nextBefore.length);
      hideSuggestions();
      input.dispatchEvent(new Event('input'));
      input.focus();
      return;
    }
    const wordMatch = /(\S*)$/.exec(before);
    const wordStart = caret - (wordMatch ? wordMatch[1].length : 0);
    const nextBefore = `${before.slice(0, wordStart)}${item.text} `;
    input.value = nextBefore + after;
    input.setSelectionRange(nextBefore.length, nextBefore.length);
    hideSuggestions();
    input.dispatchEvent(new Event('input'));
    input.focus();
  };

  const scheduleSuggestions = () => {
    window.clearTimeout(suggestionsDebounceId);
    const engine = window.AndergoTranslatorPredictive;
    const language = langSelect?.value || 'english';
    if (!['english', 'spanish', 'french'].includes(language)) {
      hideSuggestions();
      return;
    }
    suggestionsDebounceId = window.setTimeout(() => {
      const caret = input.selectionStart ?? input.value.length;
      const before = input.value.slice(0, caret);
      const wordSuggestions = engine?.getSuggestions(language, before).slice(0, 3) || [];
      const trimmed = before.trimEnd();
      const canPunctuate = /[\p{L}\p{N}\)]$/u.test(trimmed) && !/[.!?,:;…]$/.test(trimmed);
      const punctuation = canPunctuate
        ? (language === 'spanish'
            ? ['.', ',', ':', ';', '…', '¿…?', '¡…!']
            : ['.', ',', ':', ';', '…', '?', '!'])
            .map((text) => ({ type: 'punctuation', text }))
        : [];
      renderSuggestions([...wordSuggestions, ...punctuation]);
    }, 180);
  };

  input.addEventListener('input', updateCharCount);
  input.addEventListener('input', scheduleSuggestions);
  input.addEventListener('blur', () => window.setTimeout(hideSuggestions, 100));
  suggestionsList?.addEventListener('mousedown', (event) => {
    const item = event.target.closest('.translator-suggestion-item');
    if (!item) return;
    event.preventDefault();
    acceptSuggestion(Number(item.dataset.index));
  });
  updateCharCount();

  // A new language or a freshly-edited text invalidates whatever correction
  // is currently shown - never let a stale "Aplicar corrección"/"Escuchar"
  // apply text from a previous language or a previous version of the input.
  langSelect?.addEventListener('change', () => {
    resetOutput();
    hideSuggestions();
  });
  input.addEventListener('input', () => {
    if (lastCorrection) resetOutput();
  });

  async function runCorrection({ speakResult = false } = {}) {
    if (submitBtn.disabled) return; // already in flight - never a second request

    const text = input.value.trim();
    if (!text) {
      setStatus('Escribe un texto para corregir.', 'is-unavailable');
      return;
    }

    const language = langSelect?.value || 'english';
    setStatus('Corrigiendo…', 'is-loading');
    submitBtn.disabled = true;
    try {
      // auth: true, same as the Traductor's own call - lets the backend
      // apply Premium limits instead of always treating the request as a
      // guest (see POST /api/correct-text's attachUserIfPresent).
      const data = await postJson('/api/correct-text', { text, language }, { auth: true });

      if (data.ok) {
        lastCorrection = {
          originalText: text,
          correctedText: data.correctedText || '',
          explanation: data.explanation || '',
          changes: data.changes || []
        };
        output.innerHTML = `
          <div class="corrector-original">
            <span class="corrector-result-label">Original</span>
            <p>${escapeHtml(text)}</p>
          </div>
          <div class="corrector-corrected">
            <span class="corrector-result-label">Corrección</span>
            <p>${renderCorrectorHighlighted(lastCorrection.correctedText, lastCorrection.changes)}</p>
          </div>
          ${lastCorrection.explanation ? `<p class="corrector-explanation">${escapeHtml(lastCorrection.explanation)}</p>` : ''}
        `;
        setResultActionsEnabled(true);
        if (speakResult && lastCorrection.correctedText) {
          const spokenIntroductions = {
            english: 'A more natural way to say it is:',
            spanish: 'Una forma más natural de decirlo es:',
            french: 'Une façon plus naturelle de le dire est :'
          };
          const spokenCorrection = `${spokenIntroductions[language] || spokenIntroductions.english} ${lastCorrection.correctedText}`;
          setStatus(`Corrección completada. Reproduciendo ${languageDisplayNames[language] || language}…`, 'is-success');
          speakText(spokenCorrection, {
            locale: LANGUAGE_LOCALES[language],
            onEnd: () => setStatus('Corrección completada.', 'is-success')
          });
        } else {
          // Typed corrections remain quiet by default. The learner can use
          // Repetir when they explicitly want to hear the final L2 text.
          setStatus('Completada', 'is-success');
        }
      } else if (data.configured === false) {
        resetOutput();
        setStatus('El corrector está temporalmente en configuración.', 'is-unavailable');
      } else {
        resetOutput();
        setStatus(data.message || 'No disponible. Inténtalo de nuevo.', 'is-unavailable');
      }
    } catch (error) {
      resetOutput();
      setStatus(error.message || 'No disponible. Inténtalo de nuevo.', 'is-unavailable');
    } finally {
      submitBtn.disabled = false;
    }
  }

  submitBtn.addEventListener('click', runCorrection);
  input.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowDown' && suggestionItems.length) {
      event.preventDefault();
      activeSuggestionIndex = (activeSuggestionIndex + 1) % suggestionItems.length;
      updateSuggestionHighlight();
      return;
    }
    if (event.key === 'ArrowUp' && suggestionItems.length) {
      event.preventDefault();
      activeSuggestionIndex = (activeSuggestionIndex - 1 + suggestionItems.length) % suggestionItems.length;
      updateSuggestionHighlight();
      return;
    }
    if ((event.key === 'Tab' || (event.key === 'Enter' && !event.shiftKey)) && activeSuggestionIndex >= 0) {
      event.preventDefault();
      acceptSuggestion(activeSuggestionIndex);
      return;
    }
    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    runCorrection();
  });

  clearBtn?.addEventListener('click', () => {
    try { recognition?.stop(); } catch { /* inactive */ }
    recognition = null;
    talkBtn?.classList.remove('is-listening');
    if (talkBtn) {
      talkBtn.disabled = false;
      talkBtn.innerHTML = '🎙 Hablar';
    }
    input.value = '';
    updateCharCount();
    hideSuggestions();
    resetOutput();
    setStatus('Listo');
  });

  copyBtn?.addEventListener('click', async () => {
    if (!lastCorrection?.correctedText) return;
    try {
      await navigator.clipboard.writeText(lastCorrection.correctedText);
      showHomeToast('Corrección copiada.');
    } catch {
      showHomeToast('No se pudo copiar la corrección.');
    }
  });

  listenBtn?.addEventListener('click', () => {
    if (!lastCorrection?.correctedText) return;
    speakText(lastCorrection.correctedText, { locale: LANGUAGE_LOCALES[langSelect?.value] });
  });

  // Dictation is intentionally separate from typing: only a spoken L1 input
  // triggers an automatic spoken L2 correction. Written drafts always return
  // quietly, with Repetir available as an explicit choice.
  talkBtn?.addEventListener('click', async () => {
    if (recognition) {
      try { recognition.stop(); } catch { /* inactive */ }
      return;
    }
    const Ctor = getSpeechRecognitionCtor();
    if (!Ctor) {
      setStatus('El reconocimiento de voz no está disponible en este navegador.', 'is-unavailable');
      return;
    }
    try {
      await ensureMicrophonePermission();
    } catch (error) {
      setStatus(microphonePermissionMessage(error), 'is-unavailable');
      return;
    }

    const language = langSelect?.value || 'english';
    const instance = new Ctor();
    instance.lang = DICTATION_LANGUAGE_CODES[language] || LANGUAGE_LOCALES[language] || 'en-US';
    instance.interimResults = true;
    instance.continuous = false;
    recognition = instance;
    talkBtn.classList.add('is-listening');
    talkBtn.innerHTML = '⏹ Detener';
    setStatus(`Escuchando ${languageDisplayNames[language] || language}…`, 'is-loading');
    let transcript = '';

    instance.addEventListener('result', (event) => {
      transcript = Array.from(event.results).map((result) => result[0].transcript).join(' ').trim();
      input.value = transcript.slice(0, MAX_LENGTH);
      updateCharCount();
      setStatus(transcript || 'Escuchando…', 'is-loading');
    });
    instance.addEventListener('error', (event) => {
      if (event.error !== 'aborted') setStatus('No pude escuchar con claridad. Inténtalo de nuevo.', 'is-unavailable');
    });
    instance.addEventListener('end', () => {
      if (recognition !== instance) return;
      recognition = null;
      talkBtn.classList.remove('is-listening');
      talkBtn.innerHTML = '🎙 Hablar';
      if (transcript) runCorrection({ speakResult: true });
      else if (!status.classList.contains('is-unavailable')) setStatus('Toca Hablar e inténtalo de nuevo.');
    });
    instance.start();
  });

  // "Aplicar corrección": replaces the student's own draft with the
  // corrected version, same direct-field-mutation pattern the Traductor's
  // own swap button already uses - lets the student keep editing or
  // re-submit from the corrected text.
  applyBtn?.addEventListener('click', () => {
    if (!lastCorrection?.correctedText) return;
    input.value = lastCorrection.correctedText;
    updateCharCount();
    resetOutput();
    setStatus('Corrección aplicada. Puedes seguir editando.', 'is-success');
  });
}

function splitPhoneticTextForDisplay(text) {
  return String(text || '')
    .replace(/\r\n/g, '\n')
    .split(/\n+/)
    .flatMap((paragraph) => paragraph.match(/[^.!?…]+(?:[.!?…]+|$)/g) || [paragraph])
    .map((segment) => segment.trim())
    .filter(Boolean);
}

function renderPhoneticParallelHtml(text, ipa, ipaSegments) {
  const originalSegments = splitPhoneticTextForDisplay(text);
  if (!Array.isArray(ipaSegments) || ipaSegments.length !== originalSegments.length) {
    return `<p class="phonetics-ipa">${escapeHtml(ipa)}</p>`;
  }
  return `
    <div class="phonetics-parallel-list">
      ${originalSegments.map((original, index) => `
        <article class="phonetics-parallel-row">
          <span class="phonetics-parallel-number" aria-hidden="true">${index + 1}</span>
          <div class="phonetics-parallel-source">
            <span class="phonetics-parallel-label">Texto</span>
            <p>${escapeHtml(original)}</p>
          </div>
          <div class="phonetics-parallel-ipa">
            <span class="phonetics-parallel-label">IPA</span>
            <p>${escapeHtml(ipaSegments[index])}</p>
          </div>
        </article>
      `).join('')}
    </div>
  `;
}

function setupPhonetics() {
  const langSelect = document.getElementById('phoneticsLangSelect');
  const input = document.getElementById('phoneticsInput');
  const output = document.getElementById('phoneticsOutput');
  const charCount = document.getElementById('phoneticsCharCount');
  const clearBtn = document.getElementById('phoneticsClearBtn');
  const copyBtn = document.getElementById('phoneticsCopyBtn');
  const listenBtn = document.getElementById('phoneticsListenBtn');
  const stopBtn = document.getElementById('phoneticsStopBtn');
  const submitBtn = document.getElementById('phoneticsSubmitBtn');
  const status = document.getElementById('phoneticsStatus');
  if (!langSelect || !input || !output || !submitBtn || !status) return;

  const allLanguages = window.AndergoTranslatorLanguages?.getSelectableLanguages() || [];
  const languages = allLanguages.filter((lang) => lang.key === 'english' || lang.key === 'french');
  langSelect.innerHTML = languages.map((lang) =>
    `<option value="${escapeHtml(lang.key)}">${lang.flag} ${escapeHtml(lang.label)}</option>`
  ).join('');
  if (languages.some((lang) => lang.key === learningPathState.bridgeLanguage)) {
    langSelect.value = learningPathState.bridgeLanguage;
  }

  const MAX_LENGTH = Number(input.getAttribute('maxlength')) || 1000;
  let lastIpa = '';
  let lastIpaSegments = [];
  let pronunciationPlaying = false;
  const setStatus = (text, mode) => {
    status.textContent = text;
    status.classList.remove('is-loading', 'is-success', 'is-unavailable');
    if (mode) status.classList.add(mode);
  };
  const updateCharCount = () => {
    if (charCount) charCount.textContent = `${input.value.length} / ${MAX_LENGTH}`;
  };
  const stopPronunciation = () => {
    pronunciationPlaying = false;
    window.speechSynthesis?.cancel();
    listenBtn?.classList.remove('is-playing');
    listenBtn?.setAttribute('aria-pressed', 'false');
    if (stopBtn) stopBtn.disabled = true;
  };
  const resetOutput = () => {
    stopPronunciation();
    lastIpa = '';
    lastIpaSegments = [];
    output.innerHTML = '<p class="skill-graph-empty">La transcripción fonética aparecerá aquí.</p>';
    if (copyBtn) copyBtn.disabled = true;
    if (listenBtn) listenBtn.disabled = true;
  };

  input.addEventListener('input', () => {
    updateCharCount();
    if (lastIpa) resetOutput();
  });
  langSelect.addEventListener('change', resetOutput);
  updateCharCount();

  async function runPhoneticTranscription() {
    if (submitBtn.disabled) return;
    const text = input.value.trim();
    if (!text) {
      setStatus('Escribe un texto para transcribir.', 'is-unavailable');
      return;
    }
    stopPronunciation();
    setStatus('Generando transcripción IPA…', 'is-loading');
    submitBtn.disabled = true;
    try {
      const data = await postJson('/api/phonetic-transcription', {
        text, language: langSelect.value
      }, { auth: true });
      if (!data.ok) {
        resetOutput();
        setStatus(data.message || 'No se pudo generar la transcripción fonética.', 'is-unavailable');
        return;
      }
      lastIpa = data.ipa || '';
      lastIpaSegments = Array.isArray(data.segments) ? data.segments : [];
      output.innerHTML = renderPhoneticParallelHtml(text, lastIpa, lastIpaSegments);
      if (copyBtn) copyBtn.disabled = !lastIpa;
      if (listenBtn) listenBtn.disabled = !lastIpa;
      setStatus('Transcripción completada', 'is-success');
    } catch (error) {
      resetOutput();
      setStatus(error.message || 'No se pudo generar la transcripción fonética.', 'is-unavailable');
    } finally {
      submitBtn.disabled = false;
    }
  }

  submitBtn.addEventListener('click', runPhoneticTranscription);
  input.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    runPhoneticTranscription();
  });
  clearBtn?.addEventListener('click', () => {
    input.value = '';
    updateCharCount();
    resetOutput();
    setStatus('Listo');
  });
  copyBtn?.addEventListener('click', async () => {
    if (!lastIpa) return;
    try {
      await navigator.clipboard.writeText(lastIpa);
      showHomeToast('Transcripción IPA copiada.');
    } catch {
      showHomeToast('No se pudo copiar la transcripción IPA.');
    }
  });
  listenBtn?.addEventListener('click', () => {
    const text = input.value.trim();
    if (!text) return;
    stopPronunciation();
    pronunciationPlaying = true;
    listenBtn.classList.add('is-playing');
    listenBtn.setAttribute('aria-pressed', 'true');
    if (stopBtn) stopBtn.disabled = false;
    const lang = window.AndergoTranslatorLanguages?.getTranslatorLanguage(langSelect.value);
    const utterance = speakText(text, {
      locale: lang?.locale || LANGUAGE_LOCALES[langSelect.value],
      onEnd: stopPronunciation
    });
    if (!utterance) stopPronunciation();
  });
  stopBtn?.addEventListener('click', stopPronunciation);
}

function initHeroCopyCarousel() {
  const carousel = document.querySelector('.hero-copy-carousel');
  if (!carousel) return;

  const slides = [...carousel.querySelectorAll('[data-hero-slide]')];
  const controls = [...carousel.querySelectorAll('[data-hero-carousel]')];
  if (slides.length < 2) return;

  let activeIndex = slides.findIndex((slide) => slide.classList.contains('is-active'));
  activeIndex = activeIndex < 0 ? 0 : activeIndex;
  let rotationId = null;

  const activateSlide = (nextIndex) => {
    activeIndex = (nextIndex + slides.length) % slides.length;
    slides.forEach((slide, index) => {
      const isActive = index === activeIndex;
      slide.classList.toggle('is-active', isActive);
      slide.setAttribute('aria-hidden', String(!isActive));
    });
    controls.forEach((control) => {
      const target = Number(control.dataset.heroCarousel);
      if (Number.isNaN(target)) return;
      const isActive = target === activeIndex;
      control.classList.toggle('is-active', isActive);
      control.setAttribute('aria-selected', String(isActive));
    });
  };

  const stopRotation = () => {
    if (rotationId) window.clearInterval(rotationId);
    rotationId = null;
  };
  const startRotation = () => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    stopRotation();
    rotationId = window.setInterval(() => activateSlide(activeIndex + 1), 6500);
  };

  controls.forEach((control) => {
    control.addEventListener('click', () => {
      const action = control.dataset.heroCarousel;
      if (action === 'previous') activateSlide(activeIndex - 1);
      else if (action === 'next') activateSlide(activeIndex + 1);
      else activateSlide(Number(action));
      startRotation();
    });
  });

  carousel.addEventListener('mouseenter', stopRotation);
  carousel.addEventListener('mouseleave', startRotation);
  carousel.addEventListener('focusin', stopRotation);
  carousel.addEventListener('focusout', (event) => {
    if (!carousel.contains(event.relatedTarget)) startRotation();
  });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stopRotation();
    else startRotation();
  });
  startRotation();
}

document.addEventListener('change', (event) => {
  const fontSelect = event.target.closest?.('.reading-font-select');
  if (!fontSelect) return;
  const area = fontSelect.closest('.reading-print-area');
  const preferences = getReadingDisplayPreferences();
  preferences.font = fontSelect.value === 'times' ? 'times' : 'arial';
  applyReadingDisplayPreferences(area, preferences);
  setReadingDisplayPreferences(preferences);
});

